const PACE_BUILD={"scope":"individual_u1","showWeek4":false};
const UNITS=[{"id":"u1","roman":"I","title":"Números y operaciones","subtitle":"APAE · 13 estaciones · Aprende guiado y banco Practica v6 · borrador docente","icon":"01","groups":[{"title":"Enteros y conjuntos","subtitle":"Conjuntos, enteros, divisibilidad y factorización"},{"title":"Divisibilidad y fracciones","subtitle":"MCD, MCM y operaciones con fracciones"},{"title":"Potencias y racionales","subtitle":"Exponentes enteros y operaciones combinadas"},{"title":"Raíces cuadradas","subtitle":"Estimación, simplificación y operaciones con radicales"}],"hints":["Conjuntos, operaciones enteras, criterios de divisibilidad y factorización prima.","De la divisibilidad al cálculo razonado con fracciones.","Potencias y operaciones combinadas con racionales.","Comprensión, simplificación y operaciones con raíces cuadradas."],"ready":true}];
const STATIONS=[{"id":"u1-s001","title":"Conjuntos numéricos","subtitle":"Naturales, enteros, racionales y reales","group":0,"symbol":"✧","minutes":20,"concept":"","example":"","media":[],"practice":[{"q":"¿Cuál es el conjunto más específico al que pertenece $5$?","options":["$\\mathbb Z$","$\\mathbb Q$","$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb N$"],"correct":3,"why":"El 5 sirve para contar. Aquí $\\mathbb N$ comienza en 1.","level":1},{"q":"¿Cuál es el conjunto más específico al que pertenece $0$?","options":["$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Q$","$\\mathbb Z$","$\\mathbb N$"],"correct":2,"why":"Con nuestra convención, el 0 no es natural. Aquí $\\mathbb N$ comienza en 1.","level":1},{"q":"¿Cuál es el conjunto más específico al que pertenece $-7$?","options":["$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb N$","$\\mathbb Q$","$\\mathbb Z$"],"correct":3,"why":"Es entero negativo. Aquí $\\mathbb N$ comienza en 1.","level":1},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\dfrac34$?","options":["$\\mathbb Z$","$\\mathbb N$","$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Q$"],"correct":3,"why":"Es un cociente de enteros. Aquí $\\mathbb N$ comienza en 1.","level":1},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\sqrt9$?","options":["$\\mathbb Q$","$\\mathbb N$","$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Z$"],"correct":1,"why":"La raíz cuadrada principal de 9 es 3. Aquí $\\mathbb N$ comienza en 1.","level":1},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\sqrt2$?","options":["$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Q$","$\\mathbb N$","$\\mathbb Z$"],"correct":0,"why":"La raíz de 2 es irracional. Aquí $\\mathbb N$ comienza en 1.","level":1},{"q":"¿Cuál es el conjunto más específico al que pertenece $0,75$?","options":["$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Q$","$\\mathbb N$","$\\mathbb Z$"],"correct":1,"why":"El decimal finito 0,75 equivale a 3/4. Aquí $\\mathbb N$ comienza en 1.","level":1},{"q":"¿Cuál es el conjunto más específico al que pertenece $-\\dfrac{12}{4}$?","options":["$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Z$","$\\mathbb Q$","$\\mathbb N$"],"correct":1,"why":"La fracción representa el entero -3. Aquí $\\mathbb N$ comienza en 1.","level":1},{"q":"¿Cuál es el conjunto más específico al que pertenece $0,\\overline3$?","options":["$\\mathbb Z$","$\\mathbb N$","$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Q$"],"correct":3,"why":"El decimal periódico equivale a 1/3. Aquí $\\mathbb N$ comienza en 1.","level":2},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\sqrt{49}$?","options":["$\\mathbb N$","$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Q$","$\\mathbb Z$"],"correct":0,"why":"La raíz de 49 es 7. Aquí $\\mathbb N$ comienza en 1.","level":2},{"q":"¿Cuál es el conjunto más específico al que pertenece $-\\sqrt{25}$?","options":["$\\mathbb Q$","$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Z$","$\\mathbb N$"],"correct":2,"why":"Su valor es -5. Aquí $\\mathbb N$ comienza en 1.","level":2},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\dfrac{-7}{2}$?","options":["$\\mathbb N$","$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Q$","$\\mathbb Z$"],"correct":2,"why":"Es racional, pero no entero. Aquí $\\mathbb N$ comienza en 1.","level":2},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\sqrt3$?","options":["$\\mathbb N$","$\\mathbb Z$","$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Q$"],"correct":2,"why":"La raíz de 3 es irracional. Aquí $\\mathbb N$ comienza en 1.","level":2},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\dfrac{18}{3}$?","options":["$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb N$","$\\mathbb Z$","$\\mathbb Q$"],"correct":1,"why":"Su valor es 6. Aquí $\\mathbb N$ comienza en 1.","level":2},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\pi$?","options":["$\\mathbb Z$","$\\mathbb Q$","$\\mathbb N$","$\\mathbb R\\setminus\\mathbb Q$"],"correct":3,"why":"Pi es irracional. Aquí $\\mathbb N$ comienza en 1.","level":2},{"q":"¿Cuál es el conjunto más específico al que pertenece $2,125$?","options":["$\\mathbb Z$","$\\mathbb N$","$\\mathbb Q$","$\\mathbb R\\setminus\\mathbb Q$"],"correct":2,"why":"Todo decimal finito es racional. Aquí $\\mathbb N$ comienza en 1.","level":2},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\sqrt{8}$?","options":["$\\mathbb Q$","$\\mathbb N$","$\\mathbb Z$","$\\mathbb R\\setminus\\mathbb Q$"],"correct":3,"why":"Se simplifica a 2 por raíz de 2, que es irracional. Aquí $\\mathbb N$ comienza en 1.","level":3},{"q":"¿Cuál es el conjunto más específico al que pertenece $(-3)^2$?","options":["$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb N$","$\\mathbb Q$","$\\mathbb Z$"],"correct":1,"why":"Al cuadrar -3 se obtiene 9, natural. Aquí $\\mathbb N$ comienza en 1.","level":3},{"q":"¿Cuál es el conjunto más específico al que pertenece $\\dfrac02$?","options":["$\\mathbb R\\setminus\\mathbb Q$","$\\mathbb Z$","$\\mathbb Q$","$\\mathbb N$"],"correct":1,"why":"Vale 0, entero no natural con nuestra convención. Aquí $\\mathbb N$ comienza en 1.","level":3},{"q":"¿Cuál es el conjunto más específico al que pertenece $0,\\overline{12}$?","options":["$\\mathbb N$","$\\mathbb Z$","$\\mathbb Q$","$\\mathbb R\\setminus\\mathbb Q$"],"correct":2,"why":"La expresión decimal es periódica. Aquí $\\mathbb N$ comienza en 1.","level":3}],"check":{"q":"Una medición de temperatura es $-2\\,^\\circ\\mathrm{C}$. ¿En qué conjunto más pequeño de la lista pertenece?","options":["$\\mathbb{Z}$","$\\mathbb{N}$","$\\mathbb{R}\\setminus\\mathbb{Q}$"],"correct":0,"why":"$-2$ es un número entero."},"learn":{"goal":"Identificar naturales, enteros, racionales e irracionales y reconocer sus inclusiones.","idea":"1. **Naturales**: $\\mathbb N=\\{1,2,3,\\ldots\\}$ (algunos textos incluyen el $0$).\n2. **Enteros**: $\\mathbb Z=\\{\\cdots,-3,-2,-1,0,1,2,3,\\cdots\\}$.\n3. **Racionales**: $\\mathbb Q$, fracciones $\\frac{a}{b}$ de enteros, con $b\\ne0$. Pueden expresarse como decimal finito o periódico.\n4. **Reales**: $\\mathbb R$ reúne racionales e irracionales.\nLos irracionales tienen decimales infinitos no periódicos, como $\\sqrt2$ o $\\pi$.","steps":{"title":"Clasifica $\\sqrt{16}$ en el conjunto más específico","items":[{"math":"\\sqrt{16}=4","why":"Calcula primero el número representado.","side":{"title":"¿Qué significa la raíz cuadrada de 16?","text":"Es el número positivo tal que multiplicado por sí mismo da 16."}},{"math":"4\\in\\mathbb N","why":"El 4 es natural.","side":{"title":"Recordar","text":"$\\mathbb N=\\{1,2,3,\\ldots\\}$"}},{"math":"\\mathbb N\\subseteq\\mathbb Z\\subseteq\\mathbb Q\\subseteq\\mathbb R","why":"Por inclusión, 4 también es entero, racional y real.","side":{"title":"No confundir","text":"El conjunto más pequeño es $\\mathbb N$, aunque pertenece a varios."}}]},"warn":"Aquí $0\\notin\\mathbb N$; en otros libros sí se incluye. Clasifica por el valor: $\\sqrt{16}=4$ es natural; $\\sqrt2$ es irracional. Una aproximación decimal de $\\sqrt2$ no es su valor exacto."},"draw":5,"unit":0},{"id":"u1-s002","title":"Operaciones con enteros","subtitle":"Signos, paréntesis y prioridades","group":0,"symbol":"✧","minutes":45,"concept":"Resolver operaciones con enteros respetando paréntesis, signos y prioridad.\n\nOrden: 1) paréntesis; 2) potencias, cuando aparezcan; 3) productos y cocientes; 4) sumas y restas.\n• Si hay igual prioridad, avanza de izquierda a derecha.\n• Restar un número equivale a sumar su opuesto.","example":"Resuelve $6-2\\cdot(3-7)$.\n1. $$6-2\\cdot(3-7)$$ — Expresión inicial.\n2. $$6-2\\cdot(-4)$$ — Resolvemos el paréntesis.\n3. $$6-(-8)$$ — Calculamos el producto.\n4. $$6+8=14$$ — Sumamos el opuesto.","media":[],"practice":[{"q":"Calcula $(-7)+(12)$.","options":["$6$","$5$","$-5$","$4$"],"correct":1,"why":"Resolvemos la operación considerando los signos.","level":1},{"q":"Calcula $(9)+(-14)$.","options":["$-5$","$5$","$-6$","$-4$"],"correct":0,"why":"Resolvemos la operación considerando los signos.","level":1},{"q":"Calcula $(-5)+(-8)$.","options":["$-12$","$-14$","$13$","$-13$"],"correct":3,"why":"Resolvemos la operación considerando los signos.","level":1},{"q":"Calcula $(14)-(23)$.","options":["$-9$","$9$","$-10$","$-8$"],"correct":0,"why":"Resolvemos la operación considerando los signos.","level":1},{"q":"Calcula $(-6)-(11)$.","options":["$17$","$-18$","$-16$","$-17$"],"correct":3,"why":"Resolvemos la operación considerando los signos.","level":1},{"q":"Calcula $(-4)\\cdot(-7)$.","options":["$28$","$-28$","$27$","$29$"],"correct":0,"why":"Resolvemos la operación considerando los signos.","level":1},{"q":"Calcula $(7)\\cdot(-8)$.","options":["$-56$","$-55$","$-57$","$56$"],"correct":0,"why":"Resolvemos la operación considerando los signos.","level":1},{"q":"Calcula $(-36)\\div(6)$.","options":["$6$","$-6$","$-5$","$-7$"],"correct":1,"why":"Resolvemos la operación considerando los signos.","level":1},{"q":"Calcula $6-(3)\\cdot(7-2)$.","options":["$-8$","$-10$","$-9$","$9$"],"correct":2,"why":"Primero el paréntesis: 7-2=5. Luego multiplicamos 3 por 5 y finalmente restamos.","level":2},{"q":"Calcula $11-(8)\\cdot(-2-2)$.","options":["$-43$","$44$","$42$","$43$"],"correct":3,"why":"Primero el paréntesis: -2-2=-4. Luego multiplicamos 8 por -4 y finalmente restamos.","level":2},{"q":"Calcula $-4-(6)\\cdot(1-2)$.","options":["$3$","$2$","$1$","$-2$"],"correct":1,"why":"Primero el paréntesis: 1-2=-1. Luego multiplicamos 6 por -1 y finalmente restamos.","level":2},{"q":"Calcula $20-(-2)\\cdot(7-2)$.","options":["$30$","$-30$","$31$","$29$"],"correct":0,"why":"Primero el paréntesis: 7-2=5. Luego multiplicamos -2 por 5 y finalmente restamos.","level":2},{"q":"Calcula $15-(5)\\cdot(9-2)$.","options":["$-20$","$-19$","$20$","$-21$"],"correct":0,"why":"Primero el paréntesis: 9-2=7. Luego multiplicamos 5 por 7 y finalmente restamos.","level":2},{"q":"Calcula $9-(-4)\\cdot(-6-2)$.","options":["$-24$","$-22$","$-23$","$23$"],"correct":2,"why":"Primero el paréntesis: -6-2=-8. Luego multiplicamos -4 por -8 y finalmente restamos.","level":2},{"q":"Calcula $18-(3)\\cdot(-5-2)$.","options":["$40$","$-39$","$39$","$38$"],"correct":2,"why":"Primero el paréntesis: -5-2=-7. Luego multiplicamos 3 por -7 y finalmente restamos.","level":2},{"q":"Calcula $12-(-3)\\cdot(8-2)$.","options":["$30$","$31$","$-30$","$29$"],"correct":0,"why":"Primero el paréntesis: 8-2=6. Luego multiplicamos -3 por 6 y finalmente restamos.","level":2},{"q":"Calcula $(24)\\div(4)\\cdot(2)+(3)$.","options":["$16$","$-15$","$15$","$14$"],"correct":2,"why":"División y multiplicación tienen igual prioridad: 24 entre 4 es 6; después multiplicamos por 2 y sumamos 3.","level":3},{"q":"Calcula $(36)\\div(6)\\cdot(-3)+(5)$.","options":["$-12$","$-13$","$13$","$-14$"],"correct":1,"why":"División y multiplicación tienen igual prioridad: 36 entre 6 es 6; después multiplicamos por -3 y sumamos 5.","level":3},{"q":"Calcula $(-48)\\div(8)\\cdot(2)+(-1)$.","options":["$-13$","$13$","$-12$","$-14$"],"correct":0,"why":"División y multiplicación tienen igual prioridad: -48 entre 8 es -6; después multiplicamos por 2 y sumamos -1.","level":3},{"q":"Calcula $(54)\\div(-9)\\cdot(3)+(7)$.","options":["$-10$","$11$","$-12$","$-11$"],"correct":3,"why":"División y multiplicación tienen igual prioridad: 54 entre -9 es -6; después multiplicamos por 3 y sumamos 7.","level":3}],"check":{"q":"Un sensor marca $-3$ unidades y disminuye $4$ unidades. ¿Cuál es su nueva lectura?","options":["$1$","$-7$","$7$"],"correct":1,"why":"$-3-4=-7$."},"learn":{"goal":"Resolver operaciones con enteros respetando paréntesis, signos y prioridad.","idea":"Orden: 1) paréntesis; 2) potencias, cuando aparezcan; 3) productos y cocientes; 4) sumas y restas.\n• Si hay igual prioridad, avanza de izquierda a derecha.\n• Restar un número equivale a sumar su opuesto.","steps":{"title":"Resuelve $6-2\\cdot(3-7)$.","items":[{"math":"6-2\\cdot(3-7)","why":"Expresión inicial.","side":{"title":"Primero","text":"El paréntesis tiene prioridad."}},{"math":"6-2\\cdot(-4)","why":"Resolvemos el paréntesis.","side":{"title":"Resta en enteros","text":"$3-7=-4$."}},{"math":"6-(-8)","why":"Calculamos el producto.","side":{"title":"Signos","text":"Un positivo por un negativo es negativo."}},{"math":"6+8=14","why":"Sumamos el opuesto.","side":{"title":"Doble signo","text":"Restar $-8$ equivale a sumar $8$."}}]},"warn":"Atención: $24\\div4\\cdot2=12$ porque división y multiplicación tienen igual prioridad y se resuelven de izquierda a derecha. No cambies arbitrariamente el orden."},"example2":"Ejemplo 2 · Signos y producto\n1. $$(-3)\\cdot(-5)+2$$\n   Primero efectuamos la multiplicación.\n2. $$15+2$$\n   Dos negativos multiplicados dan positivo.\n3. $$17$$\n   Resolvemos la suma.","example3":"Ejemplo 3 · Prioridad de igual nivel\n1. $$24\\div4\\cdot2$$\n   Multiplicación y división tienen igual prioridad.\n2. $$6\\cdot2$$\n   Avanzamos de izquierda a derecha.\n3. $$12$$\n   Terminamos el producto.","explore":{"title":"Viaje por los enteros","desc":"Experimenta con desplazamientos positivos y negativos sobre la recta numérica.","instr":"Elige valores, observa el recorrido y vuelve a intentarlo.","alt":"Viaje por los enteros · actividad interactiva opcional, sin porcentaje de avance.","height":850,"html":"<!DOCTYPE html>\n<html lang=\"es\"><head><meta charset=\"UTF-8\"/><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"/><meta name=\"color-scheme\" content=\"light\"/><title>Explora · Viaje por los enteros · PACE UACh</title><style>:root{--bg:#f3f7fb;--paper:#fff;--ink:#1a3044;--muted:#607588;--stroke:#dce6ed;--main:#2575ac;--main2:#0b9a83;--mist:#e9f4f9;--warm:#fff6e5;--gold:#aa731d;--ok:#137d64;--bad:#a04a3c;--shadow:0 16px 36px rgba(30,62,86,.07)}\n*{box-sizing:border-box}html{font-size:16px}body{margin:0;background:radial-gradient(circle at 90% 0%,#e1f3f7 0%,transparent 32%),var(--bg);font-family:system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif;color:var(--ink);line-height:1.5}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f3bd59;outline-offset:2px}button:disabled{cursor:not-allowed;opacity:.45}\n.shell{width:min(1060px,calc(100% - 32px));margin:26px auto 42px}.hero{padding:25px 27px 24px;color:white;border-radius:22px;background:linear-gradient(119deg,#12476f 0%,#1b7d9f 57%,#138d83 100%);box-shadow:var(--shadow);position:relative;overflow:hidden}.hero:before,.hero:after{content:\"\";position:absolute;border:2px solid #ffffff20;border-radius:50%;width:270px;height:270px;right:-95px;top:-175px}.hero:after{width:180px;height:180px;right:35px;top:-120px}.kicker{text-transform:uppercase;font-size:.77rem;letter-spacing:.14em;font-weight:750;opacity:.88}.hero h1{font-size:clamp(1.48rem,3.6vw,2.15rem);margin:7px 0 5px;line-height:1.17;letter-spacing:-.03em}.hero p{margin:0;max-width:700px;color:#ebf9ff;line-height:1.5}.topline{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.chip{display:inline-flex;border-radius:999px;padding:6px 11px;background:#ffffff2b;font-weight:650;font-size:.79rem;white-space:nowrap;z-index:1}.layout{display:grid;grid-template-columns:335px minmax(0,1fr);align-items:start;gap:16px;margin-top:16px}.card{background:var(--paper);border:1px solid var(--stroke);border-radius:18px;padding:20px;box-shadow:var(--shadow);min-width:0}.card h2,.card h3{margin:0 0 12px;letter-spacing:-.02em}.card h2{font-size:1.14rem}.card h3{font-size:1.02rem}.lede{font-size:.96rem;color:var(--muted);margin:0 0 13px}.muted{color:var(--muted)}.small{font-size:.85rem}.tiny{font-size:.75rem}.controls{display:grid;gap:12px}.field{display:grid;gap:5px}.field label{font-size:.87rem;font-weight:700;color:#344f65}.field select,.field input[type=number]{width:100%;min-height:43px;border:1px solid #cddce7;background:#fff;border-radius:10px;padding:8px 11px;color:var(--ink)}.field input[type=range]{width:100%;accent-color:var(--main2);cursor:pointer}.inline-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pills{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--main);background:var(--main);color:white;font-weight:720;min-height:42px;border-radius:11px;padding:8px 14px;transition:transform .15s,filter .15s}.btn:hover:not(:disabled){filter:brightness(1.06);transform:translateY(-1px)}.btn.alt{background:#f1f7fb;color:#235e82;border-color:#bcd5e4}.btn.minor{border-color:#d4e1e9;background:white;color:#3b5d75}.btn.green{background:#0e8f78;border-color:#0e8f78}.btn.active{background:#155d89;color:white;border-color:#155d89}.btn.sm{font-size:.85rem;min-height:36px;padding:6px 10px}.btnrow{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.panel{border-radius:14px;background:#f5fafc;border:1px solid #dfecf2;padding:15px}.panel.warm{background:var(--warm);border-color:#f1e2c4}.panel.green{background:#eaf8f3;border-color:#c9e9dd}.panel p:last-child{margin-bottom:0}.panel p:first-child{margin-top:0}.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat{background:#f1f8fb;border:1px solid #ddebf1;border-radius:13px;padding:12px}.stat .value{font-size:1.45rem;font-weight:800;color:#1a6289;line-height:1.25}.stat .label{font-size:.78rem;color:var(--muted)}.formula{font-family:Georgia,\"Times New Roman\",serif;font-size:clamp(1.25rem,3.5vw,1.8rem);font-weight:650;line-height:1.5;text-align:center;word-break:normal}.formula.big{font-size:clamp(1.6rem,4.5vw,2.4rem)}.formula-row{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}.frac{display:inline-flex;flex-direction:column;vertical-align:middle;text-align:center;line-height:1.07;padding:0 2px;font-variant-numeric:tabular-nums}.frac>.n{display:block;border-bottom:1.7px solid currentColor;padding:0 5px 3px}.frac>.d{display:block;padding:3px 5px 0}.stepper{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-top:14px}.stepbadge{font-size:.8rem;font-weight:700;color:#587186}.bar{display:flex;overflow:hidden;border:1px solid #96b0c3;height:32px;border-radius:7px;background:#eef3f5}.segment{flex:1;border-right:1px solid #ffffff90;min-width:0;background:#edf3f7}.segment:last-child{border-right:0}.segment.on{background:#248ac4}.segment.on.teal{background:#28a88b}.segment.on.amber{background:#e4a145}.section-gap{height:16px}.note{border-left:4px solid #d9a03f;background:#fff8e9;padding:11px 13px;border-radius:8px;font-size:.9rem;color:#6b5127}.footer{margin-top:16px;color:#657b8d;font-size:.8rem;text-align:center}.frame{border:1px solid #d8e6ec;background:#f9fcfd;border-radius:13px;overflow:hidden;padding:6px}.frame svg{width:100%;height:auto;display:block}.highlight{color:#0d887b;font-weight:800}.warn{color:#a45327;font-weight:780}.subhead{font-weight:800;font-size:.89rem;color:#42617a;text-transform:uppercase;letter-spacing:.055em;margin-bottom:8px}.reveal{animation:appear .3s ease-out}@keyframes appear{from{opacity:.25;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}\n@media(max-width:760px){.shell{width:min(100% - 18px,610px);margin:9px auto 28px}.hero{padding:19px;border-radius:16px}.layout{grid-template-columns:1fr;gap:11px;margin-top:11px}.card{padding:16px;border-radius:14px}.topline{flex-direction:column}.chip{align-self:flex-start}.inline-fields{grid-template-columns:1fr 1fr}.footer{padding:0 8px}.stat .value{font-size:1.25rem}}\n@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}\n</style></head><body><div class=\"shell\"><header class=\"hero\"><div class=\"topline\"><div><div class=\"kicker\">EXPLORA · UNIDAD I · ESTACIÓN 2</div><h1>Viaje por los enteros</h1><p>Muévete a derecha e izquierda. Descubre cómo funcionan los signos cuando sumas o restas números enteros.</p></div><span class=\"chip\">Sin cronómetro</span></div></header>\n<div class=\"layout\"><aside class=\"card\"><h2>1. Prepara el viaje</h2><div class=\"controls\"><div class=\"field\"><label for=\"start\">Empieza en</label><input type=\"number\" id=\"start\" min=\"-12\" max=\"12\" step=\"1\" value=\"-7\"/></div><div class=\"field\"><label for=\"operation\">Operación</label><select id=\"operation\"><option value=\"+\">Sumar</option><option value=\"-\">Restar</option></select></div><div class=\"field\"><label for=\"change\">Número que sumas o restas</label><input id=\"change\" type=\"number\" min=\"-12\" max=\"12\" step=\"1\" value=\"12\"/></div><div class=\"btnrow\"><button id=\"prepare\" class=\"btn alt\">Preparar recorrido</button><button class=\"btn minor sm\" data-eg=\"0\">−7 + 12</button><button class=\"btn minor sm\" data-eg=\"1\">3 − (−5)</button><button class=\"btn minor sm\" data-eg=\"2\">−2 − 6</button></div></div><div class=\"section-gap\"></div><div class=\"note\"><strong>Pista:</strong> en la recta, un desplazamiento positivo avanza a la derecha y uno negativo, a la izquierda. Restar un entero equivale a sumar su opuesto.</div></aside>\n<main class=\"card\"><h2>2. Observa el recorrido</h2><div class=\"panel\"><div class=\"formula big\" id=\"operationText\">−7 + 12</div><div id=\"rule\" class=\"small muted\" style=\"text-align:center\"></div></div><div class=\"section-gap\"></div>\n<div class=\"frame\"><svg id=\"line\" viewBox=\"0 0 920 255\" role=\"img\" aria-label=\"Recta numérica con punto inicial y desplazamiento\"></svg></div>\n<div class=\"section-gap\"></div><div class=\"stats\"><div class=\"stat\"><div class=\"label\">Posición actual</div><div class=\"value\" id=\"current\">−7</div></div><div class=\"stat\"><div class=\"label\">Destino</div><div class=\"value\" id=\"target\">5</div></div></div>\n<div class=\"section-gap\"></div><div class=\"panel green\" aria-live=\"polite\"><strong id=\"notice\">Comienza en −7.</strong><p id=\"progressText\" class=\"small\" style=\"margin:5px 0 0\">Avanza un paso o completa el recorrido.</p></div>\n<div class=\"section-gap\"></div><div class=\"btnrow\"><button class=\"btn\" id=\"one\">Dar 1 paso</button><button class=\"btn green\" id=\"all\">Recorrer todo ▶</button><button class=\"btn alt\" id=\"reset\">↺ Volver al inicio</button></div>\n</main></div><div class=\"footer\">Explora sin presión. Puedes cambiar los números y repetir cuantas veces quieras.</div></div>\n<script>function $(id){return document.getElementById(id)}\nfunction clamp(v,a,b){return Math.min(b,Math.max(a,Number(v)||0))}\nfunction gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b]}return a}\nfunction lcm(a,b){return Math.abs(a*b)/gcd(a,b)}\nfunction fmt(n){return String(n).replace('-', '−')}\nfunction fraction(n,d){let s=n<0?'−':'';n=Math.abs(n);return `<span class=\"frac\"><span class=\"n\">${s}${n}</span><span class=\"d\">${d}</span></span>`}\nfunction fractionStr(n,d){return `${fmt(n)}/${d}`}\nfunction simplify(n,d){if(d<0){n=-n;d=-d}const g=gcd(n,d)||1;return [n/g,d/g]}\nfunction barMarkup(n,d,cls=''){let out='';for(let i=0;i<d;i++){out+=`<span class=\"segment ${i<n?'on '+cls:''}\" aria-hidden=\"true\"></span>`}return `<div class=\"bar\" role=\"img\" aria-label=\"${n} de ${d} partes sombreadas\">${out}</div>`}\nfunction options(el,values,selected){el.innerHTML=values.map(v=>`<option value=\"${v}\" ${String(v)===String(selected)?'selected':''}>${v}</option>`).join('')}\nfunction setText(id,val){$(id).textContent=val}\n</script><script>let st={start:-7,b:12,op:'+',done:0,timer:null};\nfunction stop(){if(st.timer!==null){clearInterval(st.timer);st.timer=null}}\nfunction delta(){return st.op==='+'?st.b:-st.b}\nfunction destination(){return st.start+delta()}\nfunction setup(a,b,op){stop();st.start=a;st.b=b;st.op=op;st.done=0;$('start').value=a;$('change').value=b;$('operation').value=op;render()}\nfunction numText(n){return n<0?`(${fmt(n)})`:String(n)}\nfunction render(){let d=delta(),t=destination(),current=st.start+Math.sign(d)*st.done,total=Math.abs(d);setText('operationText',`${fmt(st.start)} ${st.op==='+'?'+':'−'} ${numText(st.b)} = ${st.done===total?fmt(t):'?'}`);\nsetText('rule',st.op==='-'?`Restar ${fmt(st.b)} es lo mismo que sumar ${fmt(-st.b)}.`:`Sumar ${fmt(st.b)} significa ${d>=0?'ir hacia la derecha':'ir hacia la izquierda'}.`);\nsetText('current',fmt(current));setText('target',fmt(t));let travel=total===0?'No necesitas desplazarte.':`Has dado ${st.done} de ${total} pasos.`;setText('progressText',travel);setText('notice',st.done===total?`Llegaste a ${fmt(t)}. ¡Recorrido completo!`:`${st.done===0?'Partimos en': 'Ahora estás en'} ${fmt(current)}. ${d>0?'Avanza a la derecha.':d<0?'Avanza a la izquierda.':''}`);\n$('one').disabled=st.done>=total;$('all').disabled=st.done>=total;\nlet min=Math.min(-10,st.start,t,current)-2,max=Math.max(10,st.start,t,current)+2;\nconst width=window.innerWidth<=600?350:920,left=width===350?18:43,right=width===350?width-18:883,span=max-min,map=n=>left+(n-min)/span*(right-left),small=width===350;\nlet ticks='';const stride=small?(span>32?5:span>22?4:2):2;\nfor(let x=min;x<=max;x++){let X=map(x),lab=(x===st.start||x===t||x===current||x===0||x%stride===0);ticks+=`<line x1=\"${X}\" y1=\"147\" x2=\"${X}\" y2=\"${lab?166:156}\" stroke=\"#9eb1be\" stroke-width=\"1.3\"/>${lab?`<text x=\"${X}\" y=\"186\" text-anchor=\"middle\" font-size=\"${small?12:15}\" fill=\"#4c6478\">${fmt(x)}</text>`:''}`}\nconst xS=map(st.start),xC=map(current),xT=map(t),mid=(xC+xS)/2,arcY=small?75:80;\nlet arc=st.done>0?`<path d=\"M ${xS} 132 Q ${mid} ${arcY} ${xC} 132\" fill=\"none\" stroke=\"#19a394\" stroke-width=\"${small?4:6}\" stroke-linecap=\"round\" marker-end=\"url(#pointer)\"/>`:'';\n$('line').setAttribute('viewBox',`0 0 ${width} 255`);\n$('line').innerHTML=`<defs><marker id=\"pointer\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"userSpaceOnUse\"><path d=\"M0,0 L0,6 L8,3 z\" fill=\"#19a394\"/></marker></defs><rect width=\"${width}\" height=\"255\" rx=\"14\" fill=\"#f9fcff\"/><line x1=\"${left}\" y1=\"147\" x2=\"${right}\" y2=\"147\" stroke=\"#58758b\" stroke-width=\"2.5\"/><path d=\"M${right} 147 L${right-9} 142 L${right-9} 152 Z\" fill=\"#58758b\"/>${ticks}<line x1=\"${xT}\" y1=\"95\" x2=\"${xT}\" y2=\"211\" stroke=\"#dfac53\" stroke-width=\"2\" stroke-dasharray=\"5 6\"/><text x=\"${xT}\" y=\"87\" text-anchor=\"middle\" font-size=\"${small?13:16}\" fill=\"#9e6c19\" font-weight=\"750\">Meta: ${fmt(t)}</text>${arc}<circle cx=\"${xS}\" cy=\"147\" r=\"6\" fill=\"#166f9e\"/><circle cx=\"${xC}\" cy=\"132\" r=\"${small?11:14}\" fill=\"#1180b2\" stroke=\"white\" stroke-width=\"3\"/><text x=\"${xC}\" y=\"116\" text-anchor=\"middle\" fill=\"#166f9e\" font-weight=\"800\" font-size=\"${small?16:17}\">${fmt(current)}</text><text x=\"${width/2}\" y=\"231\" text-anchor=\"middle\" fill=\"#74899b\" font-size=\"${small?12:14}\">Derecha → números mayores</text>`;}\n\nfunction step(){let count=Math.abs(delta());if(st.done<count){st.done++;render()}if(st.done>=count)stop()}\n$('one').addEventListener('click',()=>{stop();step()});$('all').addEventListener('click',()=>{stop();if(Math.abs(delta())===0){render();return}st.timer=setInterval(step,290)});\n$('reset').addEventListener('click',()=>{stop();st.done=0;render()});$('prepare').addEventListener('click',()=>{let a=Number($('start').value),b=Number($('change').value);if(!Number.isInteger(a)||a< -12||a>12||!Number.isInteger(b)||b< -12||b>12){$('start').setCustomValidity('Usa enteros entre −12 y 12');$('start').reportValidity();return}$('start').setCustomValidity('');setup(a,b,$('operation').value)});\n[['start','change','operation']].forEach(()=>{});document.querySelectorAll('[data-eg]').forEach(b=>b.addEventListener('click',()=>{let e=[[ -7,12,'+'],[3,-5,'-'],[-2,6,'-']][Number(b.dataset.eg)];setup(...e)}));setup(-7,12,'+');\n\nwindow.addEventListener('resize',()=>render());\n</script></body></html>"},"draw":5,"unit":0},{"id":"u1-s013","title":"Criterios de divisibilidad","subtitle":"Del resto cero a la factorización","group":0,"symbol":"✧","minutes":25,"concept":"Un número es divisible por $d>0$ si la división por $d$ tiene resto cero.\n\n1. Por 2: Termina en 0, 2, 4, 6 u 8.\n2. Por 3: La suma de sus cifras es múltiplo de 3.\n3. Por 4: Sus dos últimas cifras forman un múltiplo de 4.\n4. Por 5: Termina en 0 o 5.\n5. Por 6: Cumple a la vez los criterios de 2 y de 3.\n6. Por 8: Sus tres últimas cifras forman un múltiplo de 8.\n7. Por 9: La suma de sus cifras es múltiplo de 9.\n8. Por 10: Termina en 0.","example":"¿Por cuáles de $2,3,4,5,6,8,9,10$ es divisible $1236$?\n1. Criterio 2: Sí.\n2. Criterio 3: Sí.\n3. Criterio 4: Sí.\n4. Criterio 5: No.\n5. Criterio 6: Sí.\n6. Criterio 8: No.\n7. Criterio 9: No.\n8. Criterio 10: No.\nConclusión: $2,3,4,6$.","example2":"Ejemplo 2 · $3240$ (revisa todos los criterios)\n1. $$3240\\text{ termina en }0$$\n   Es divisible por 2, 5 y 10.\n2. $$3+2+4+0=9$$\n   Es divisible por 3 y por 9.\n3. $$40=4\\cdot10\\quad;\\quad240=8\\cdot30$$\n   Cumple también los criterios del 4 y del 8.\n4. $$2\\mid3240\\ \\text{y}\\ 3\\mid3240$$\n   Por el criterio del 6, también es divisible por 6.\n5. $$\\{2,3,4,5,6,8,9,10\\}$$\n   Cumple los ocho criterios estudiados.","media":[],"practice":[{"q":"¿Es $246$ divisible por $2$?","options":["No se puede decidir","No","Sí"],"correct":2,"why":"La última cifra es 6: es par.","level":1},{"q":"¿Es $124$ divisible por $3$?","options":["No se puede decidir","Sí","No"],"correct":2,"why":"La suma de cifras es 7; no es múltiplo de 3.","level":1},{"q":"¿Es $135$ divisible por $4$?","options":["No se puede decidir","Sí","No"],"correct":2,"why":"Las dos últimas cifras forman 35, no múltiplo de 4.","level":1},{"q":"¿Es $732$ divisible por $5$?","options":["Sí","No","No se puede decidir"],"correct":1,"why":"Termina en 2; no cumple el criterio del 5.","level":1},{"q":"¿Es $258$ divisible por $6$?","options":["No se puede decidir","Sí","No"],"correct":1,"why":"Es divisible simultáneamente por 2 y 3.","level":1},{"q":"¿Es $1024$ divisible por $8$?","options":["No se puede decidir","Sí","No"],"correct":1,"why":"Las tres últimas cifras son 24; son múltiplo de 8.","level":1},{"q":"¿Es $1236$ divisible por $9$?","options":["No","Sí","No se puede decidir"],"correct":0,"why":"La suma de cifras es 12; no es múltiplo de 9.","level":1},{"q":"¿Es $840$ divisible por $10$?","options":["No se puede decidir","No","Sí"],"correct":2,"why":"Termina en 0; cumple el criterio del 10.","level":1},{"q":"De los divisores 2, 3, 4, ¿cuáles dividen exactamente a $864$?","options":["$\\{3,4\\}$","$\\{2,3,4\\}$","$\\{2,4\\}$","$\\{2,3\\}$"],"correct":1,"why":"La última cifra es 4: es par. La suma de cifras es 18; es múltiplo de 3. Las dos últimas cifras forman 64, múltiplo de 4.","level":2},{"q":"De los divisores 2, 5, 10, ¿cuáles dividen exactamente a $1250$?","options":["$\\{2,5,10\\}$","$\\{5,10\\}$","$\\{2,10\\}$","$\\{2,5\\}$"],"correct":0,"why":"La última cifra es 0: es par. Termina en 0; cumple el criterio del 5. Termina en 0; cumple el criterio del 10.","level":2},{"q":"De los divisores 3, 8, 9, ¿cuáles dividen exactamente a $432$?","options":["$\\{3,8\\}$","$\\{3,9\\}$","$\\{3,8,9\\}$","$\\{8,9\\}$"],"correct":2,"why":"La suma de cifras es 9; es múltiplo de 3. Las tres últimas cifras son 432; son múltiplo de 8. La suma de cifras es 9; es múltiplo de 9.","level":2},{"q":"De los divisores 2, 5, 10, ¿cuáles dividen exactamente a $725$?","options":["$\\{\\}$","$\\{2,5\\}$","$\\{5\\}$","$\\{5,10\\}$"],"correct":2,"why":"La última cifra es 5: es impar. Termina en 5; cumple el criterio del 5. Termina en 5; no cumple el criterio del 10.","level":2},{"q":"De los divisores 3, 4, 8, ¿cuáles dividen exactamente a $1008$?","options":["$\\{3,4,8\\}$","$\\{3,8\\}$","$\\{3,4\\}$","$\\{4,8\\}$"],"correct":0,"why":"La suma de cifras es 9; es múltiplo de 3. Las dos últimas cifras forman 8, múltiplo de 4. Las tres últimas cifras son 8; son múltiplo de 8.","level":2},{"q":"De los divisores 5, 6, 9, ¿cuáles dividen exactamente a $2250$?","options":["$\\{6,9\\}$","$\\{5,6,9\\}$","$\\{5,9\\}$","$\\{5,6\\}$"],"correct":1,"why":"Termina en 0; cumple el criterio del 5. Es divisible simultáneamente por 2 y 3. La suma de cifras es 9; es múltiplo de 9.","level":2},{"q":"De los divisores 2, 6, 8, ¿cuáles dividen exactamente a $2448$?","options":["$\\{6,8\\}$","$\\{2,6,8\\}$","$\\{2,6\\}$","$\\{2,8\\}$"],"correct":1,"why":"La última cifra es 8: es par. Es divisible simultáneamente por 2 y 3. Las tres últimas cifras son 448; son múltiplo de 8.","level":2},{"q":"De los divisores 4, 9, 10, ¿cuáles dividen exactamente a $7200$?","options":["$\\{4,9,10\\}$","$\\{4,10\\}$","$\\{4,9\\}$","$\\{9,10\\}$"],"correct":0,"why":"Las dos últimas cifras forman 0, múltiplo de 4. La suma de cifras es 9; es múltiplo de 9. Termina en 0; cumple el criterio del 10.","level":2},{"q":"De los divisores 2, 3, 4, 5, 6, 8, 9, 10, ¿cuáles dividen exactamente a $1236$?","options":["$\\{2,3,6\\}$","$\\{2,3,4,6\\}$","$\\{3,4,6\\}$","$\\{2,4,6\\}$"],"correct":1,"why":"La última cifra es 6: es par. La suma de cifras es 12; es múltiplo de 3. Las dos últimas cifras forman 36, múltiplo de 4. Termina en 6; no cumple el criterio del 5. Es divisible simultáneamente por 2 y 3. Las tres últimas cifras son 236; no son múltiplo de 8. La suma de cifras es 12; no es múltiplo de 9. Termina en 6; no cumple el criterio del 10.","level":3},{"q":"De los divisores 2, 3, 4, 5, 6, 8, 9, 10, ¿cuáles dividen exactamente a $3240$?","options":["$\\{3,4,5,6,8,9,10\\}$","$\\{2,4,5,6,8,9,10\\}$","$\\{2,3,5,6,8,9,10\\}$","$\\{2,3,4,5,6,8,9,10\\}$"],"correct":3,"why":"La última cifra es 0: es par. La suma de cifras es 9; es múltiplo de 3. Las dos últimas cifras forman 40, múltiplo de 4. Termina en 0; cumple el criterio del 5. Es divisible simultáneamente por 2 y 3. Las tres últimas cifras son 240; son múltiplo de 8. La suma de cifras es 9; es múltiplo de 9. Termina en 0; cumple el criterio del 10.","level":3},{"q":"De los divisores 2, 3, 4, 5, 6, 8, 9, 10, ¿cuáles dividen exactamente a $2108$?","options":["$\\{4\\}$","$\\{2,4\\}$","$\\{2,3,4\\}$","$\\{2\\}$"],"correct":1,"why":"La última cifra es 8: es par. La suma de cifras es 11; no es múltiplo de 3. Las dos últimas cifras forman 8, múltiplo de 4. Termina en 8; no cumple el criterio del 5. No es divisible simultáneamente por 2 y 3. Las tres últimas cifras son 108; no son múltiplo de 8. La suma de cifras es 11; no es múltiplo de 9. Termina en 8; no cumple el criterio del 10.","level":3},{"q":"De los divisores 2, 3, 4, 5, 6, 8, 9, 10, ¿cuáles dividen exactamente a $1809$?","options":["$\\{3,4,9\\}$","$\\{2,3,9\\}$","$\\{9\\}$","$\\{3,9\\}$"],"correct":3,"why":"La última cifra es 9: es impar. La suma de cifras es 18; es múltiplo de 3. Las dos últimas cifras forman 9, no múltiplo de 4. Termina en 9; no cumple el criterio del 5. No es divisible simultáneamente por 2 y 3. Las tres últimas cifras son 809; no son múltiplo de 8. La suma de cifras es 18; es múltiplo de 9. Termina en 9; no cumple el criterio del 10.","level":3}],"check":{"q":"Un laboratorio tiene $288$ muestras. ¿Puede distribuirlas en cajas de $9$ muestras sin que sobre ninguna?","options":["Sí, porque $2+8+8=18$ es múltiplo de $9$.","No, porque $288$ termina en $8$.","No, porque $288$ no termina en $0$."],"correct":0,"why":"$2+8+8=18$ es múltiplo de $9$, por tanto $288$ es divisible por $9$. Caben exactamente $288/9=32$ cajas."},"learn":{"goal":"Aplicar y justificar criterios de divisibilidad.","idea":"**DIVISIBLE = AL DIVIDIR DA RESTO CERO**\nPor ejemplo, \n$24=6\\cdot4$ (resto 0) $\\Longrightarrow\\ 24$ es divisible por $6$.\n$32=6\\cdot5+2$ (resto 2) $\\Longrightarrow\\ 32$ no es divisible por $6$.\n\n**Criterios de divisibilidad:**\n$\\bullet$ Por 2: Termina en 0, 2, 4, 6 u 8.\n$\\bullet$ Por 3: La suma de sus cifras es múltiplo de 3.\n$\\bullet$ Por 4: Sus dos últimas cifras forman un múltiplo de 4.\n$\\bullet$ Por 5: Termina en 0 o 5.\n$\\bullet$ Por 6: Cumple a la vez los criterios de 2 y de 3.\n$\\bullet$ Por 8: Sus tres últimas cifras forman un múltiplo de 8.\n$\\bullet$ Por 9: La suma de sus cifras es múltiplo de 9.\n$\\bullet$ Por 10: Termina en 0.","steps":{"title":"¿Cuáles de los ocho números dividen a $\\underline{1236}$?","items":[{"math":"\\text{Última cifra es }6.","why":"Criterio del 2: última cifra es 0, 2, 4, 6 u 8.","side":{"math":"1236=2\\cdot618\\ (\\text{División - resto 0})","title":"2 sí lo divide"}},{"math":"1+2+3+6=12\\text{ (da múltiplo de 3).}","why":"Criterio del 3: la suma de sus cifras es múltiplo de 3.\n","side":{"title":"3 sí lo divide","math":"1236=3\\cdot412\\ (\\text{División - resto 0})"}},{"math":"\\text{Últimas dos cifras forman el }36\\text{ (que es múltiplo de 4).}","why":"Criterio del 4: Sus dos últimas cifras forman un múltiplo de 4.","side":{"title":"4 sí lo divide","math":"1236=4\\cdot309\\ (\\text{División - resto 0})"}},{"math":"\\text{Última cifra es 6.}","why":"Criterio del 5: última cifra es 0 o 5.","side":{"title":"5 no lo divide","math":"1236=5\\cdot247+1\\ (\\text{División - resto }1\\neq0)"}},{"math":"2\\text{ y }3\\text{ sí lo dividen.} ","why":"Criterio del 6: cumple los criterios del 2 y del 3.","side":{"title":"6 sí lo divide","math":"1236=6\\cdot206\\ (\\text{División - resto 0})"}},{"math":"\\text{Últimas tres cifras forman el }236\\text{ (que no es múltiplo de 8).}","why":"Criterio del 8: Sus tres últimas cifras forman un múltiplo de 8.\nNotar: $236=8\\cdot29+4$, o sea, 8 no divide a 236.","side":{"title":"8 no lo divide","math":"1236=8\\cdot154+4\\ (\\text{División - resto }4\\neq0)"}},{"math":"1+2+3+6=12\\text{ (no da múltiplo de 9).}","why":"Criterio del 9: la suma de sus cifras es múltiplo de 9.\n","side":{"title":"9 no lo divide","math":"1236=9\\cdot137+3\\ (\\text{División - resto }3\\neq0)"}},{"math":"\\text{Última cifra es 6.}","why":"Criterio del 10: última cifra es 0.","side":{"title":"10 no lo divide","math":"1236=10\\cdot123+6\\ (\\text{División - resto }6\\neq0)"}},{"math":"\\text{Conclusión:}","why":"De nuestra lista, exclusivamente el 2, 3, 4 y 6 dividen al 1236","side":{"title":"No lo dividen:","math":"\\text{5, 8, 9 y 10.}"}}]},"warn":"Estos criterios permiten decidir si un número es divisible o no por 2, 3, 4, 5, 6, 8, 0 o 10, sin necesidad de realizar la división.\nLuego, uno puede realizar la división para factorizar o verificar cuánto da el resto."},"example3":"Ejemplo 3 · $1008$ (no todo es divisible)\n1. $$1008\\text{ termina en }8$$\n   Cumple el criterio 2, pero no los de 5 ni 10.\n2. $$1+0+0+8=9$$\n   Cumple los criterios 3 y 9.\n3. $$08=8\\quad;\\quad008=8$$\n   Cumple los criterios 4 y 8.\n4. $$2\\mid1008\\ \\text{y}\\ 3\\mid1008$$\n   Cumple también el criterio 6.","draw":5,"unit":0},{"id":"u1-s003","title":"Primos y factorización","subtitle":"División, números primos y descomposición","group":0,"symbol":"✧","minutes":40,"concept":"Reconocer números primos, interpretar cociente y resto y factorizar un entero positivo en primos.\n\nDivisión: si $a=bq+r$ y $b>0$, entonces $0\\le r<b$.\n• Primo: entero mayor que $1$ con solo dos divisores positivos: $1$ y él mismo.\n• Todo entero mayor que $1$ se descompone en primos de forma única, salvo el orden.","example":"Descompón $60$ en factores primos.\n1. $$60=2\\cdot30$$ — Dividimos por un primo.\n2. $$60=2\\cdot2\\cdot15$$ — Seguimos descomponiendo.\n3. $$60=2\\cdot2\\cdot3\\cdot5$$ — Todos los factores son primos.\n4. $$60=2^2\\cdot3\\cdot5$$ — Escribimos las repeticiones con potencias.","media":[],"practice":[{"q":"¿El número $2$ es primo o compuesto?","options":["Ni primo ni compuesto","Compuesto","Primo"],"correct":2,"why":"2 solo tiene divisores positivos 1 y 2.","level":1},{"q":"¿El número $9$ es primo o compuesto?","options":["Compuesto","Ni primo ni compuesto","Primo"],"correct":0,"why":"9 es compuesto: 9=3\\cdot3.","level":1},{"q":"¿El número $11$ es primo o compuesto?","options":["Compuesto","Ni primo ni compuesto","Primo"],"correct":2,"why":"11 solo tiene divisores positivos 1 y 11.","level":1},{"q":"¿El número $15$ es primo o compuesto?","options":["Primo","Ni primo ni compuesto","Compuesto"],"correct":2,"why":"15 es compuesto: 15=3\\cdot5.","level":1},{"q":"¿El número $17$ es primo o compuesto?","options":["Primo","Ni primo ni compuesto","Compuesto"],"correct":0,"why":"17 solo tiene divisores positivos 1 y 17.","level":1},{"q":"¿El número $21$ es primo o compuesto?","options":["Primo","Ni primo ni compuesto","Compuesto"],"correct":2,"why":"21 es compuesto: 21=3\\cdot7.","level":1},{"q":"¿El número $29$ es primo o compuesto?","options":["Primo","Ni primo ni compuesto","Compuesto"],"correct":0,"why":"29 solo tiene divisores positivos 1 y 29.","level":1},{"q":"¿El número $49$ es primo o compuesto?","options":["Compuesto","Primo","Ni primo ni compuesto"],"correct":0,"why":"49 es compuesto: 49=7\\cdot7.","level":1},{"q":"¿Cuál es la descomposición en factores primos de $36$?","options":["$2^{3}\\cdot 3^{2}$","$37$","$2^{2}\\cdot 3^{2}$","$2^{2}\\cdot 3^{3}$"],"correct":2,"why":"Factorizando: $36=2^{2}\\cdot 3^{2}$. Todos los factores escritos son primos.","level":2},{"q":"¿Cuál es la descomposición en factores primos de $48$?","options":["$2^{4}\\cdot 3$","$2^{5}\\cdot 3$","$2^{4}\\cdot 3^{2}$","$7^{2}$"],"correct":0,"why":"Factorizando: $48=2^{4}\\cdot 3$. Todos los factores escritos son primos.","level":2},{"q":"¿Cuál es la descomposición en factores primos de $60$?","options":["$2^{2}\\cdot 3^{2}\\cdot 5$","$2^{3}\\cdot 3\\cdot 5$","$61$","$2^{2}\\cdot 3\\cdot 5$"],"correct":3,"why":"Factorizando: $60=2^{2}\\cdot 3\\cdot 5$. Todos los factores escritos son primos.","level":2},{"q":"¿Cuál es la descomposición en factores primos de $72$?","options":["$2^{3}\\cdot 3^{2}$","$2^{4}\\cdot 3^{2}$","$2^{3}\\cdot 3^{3}$","$73$"],"correct":0,"why":"Factorizando: $72=2^{3}\\cdot 3^{2}$. Todos los factores escritos son primos.","level":2},{"q":"¿Cuál es la descomposición en factores primos de $84$?","options":["$5\\cdot 17$","$2^{2}\\cdot 3\\cdot 7$","$2^{3}\\cdot 3\\cdot 7$","$2^{2}\\cdot 3^{2}\\cdot 7$"],"correct":1,"why":"Factorizando: $84=2^{2}\\cdot 3\\cdot 7$. Todos los factores escritos son primos.","level":2},{"q":"¿Cuál es la descomposición en factores primos de $90$?","options":["$2^{2}\\cdot 3^{2}\\cdot 5$","$2\\cdot 3^{2}\\cdot 5$","$7\\cdot 13$","$2\\cdot 3^{3}\\cdot 5$"],"correct":1,"why":"Factorizando: $90=2\\cdot 3^{2}\\cdot 5$. Todos los factores escritos son primos.","level":2},{"q":"¿Cuál es la descomposición en factores primos de $120$?","options":["$2^{3}\\cdot 3\\cdot 5$","$2^{3}\\cdot 3^{2}\\cdot 5$","$11^{2}$","$2^{4}\\cdot 3\\cdot 5$"],"correct":0,"why":"Factorizando: $120=2^{3}\\cdot 3\\cdot 5$. Todos los factores escritos son primos.","level":2},{"q":"¿Cuál es la descomposición en factores primos de $150$?","options":["$2\\cdot 3^{2}\\cdot 5^{2}$","$2\\cdot 3\\cdot 5^{2}$","$2^{2}\\cdot 3\\cdot 5^{2}$","$151$"],"correct":1,"why":"Factorizando: $150=2\\cdot 3\\cdot 5^{2}$. Todos los factores escritos son primos.","level":2},{"q":"Al dividir $47$ por $5$, ¿cuál es el resto?","options":["$3$","$-2$","$1$","$2$"],"correct":3,"why":"$47=5\\cdot9+2$ y $0\\le 2<5$.","level":3},{"q":"Al dividir $89$ por $8$, ¿cuál es el resto?","options":["$2$","$-1$","$1$","$0$"],"correct":2,"why":"$89=8\\cdot11+1$ y $0\\le 1<8$.","level":3},{"q":"Al dividir $125$ por $7$, ¿cuál es el resto?","options":["$6$","$7$","$5$","$-6$"],"correct":0,"why":"$125=7\\cdot17+6$ y $0\\le 6<7$.","level":3},{"q":"Al dividir $173$ por $11$, ¿cuál es el resto?","options":["$9$","$8$","$-8$","$7$"],"correct":1,"why":"$173=11\\cdot15+8$ y $0\\le 8<11$.","level":3}],"check":{"q":"Se distribuyen $24$ muestras en grupos iguales de $6$. ¿Cuántos grupos hay?","options":["$4$","$5$","$6$"],"correct":0,"why":"$24\\div6=4$."},"learn":{"goal":"Reconocer números primos, interpretar cociente y resto y factorizar un entero positivo en primos.","idea":"División: si $a=bq+r$ y $b>0$, entonces $0\\le r<b$.\n• Primo: entero mayor que $1$ con solo dos divisores positivos: $1$ y él mismo.\n• Todo entero mayor que $1$ se descompone en primos de forma única, salvo el orden.","steps":{"title":"Descompón $60$ en factores primos.","items":[{"math":"60=2\\cdot30","why":"Dividimos por un primo.","side":{"title":"Factor 2","text":"$60$ es par; por eso $2$ divide a $60$."}},{"math":"60=2\\cdot2\\cdot15","why":"Seguimos descomponiendo.","side":{"title":"Otro 2","text":"También $30$ es divisible por $2$."}},{"math":"60=2\\cdot2\\cdot3\\cdot5","why":"Todos los factores son primos.","side":{"title":"Factores finales","text":"$3$ y $5$ ya son primos."}},{"math":"60=2^2\\cdot3\\cdot5","why":"Escribimos las repeticiones con potencias.","side":{"title":"Comprobación","text":"$4\\cdot3\\cdot5=60$."}}]},"warn":"Atención: $1$ no es primo ni compuesto. Para el resto de una división por $b>0$, debe cumplirse $0\\le r<b$."},"example2":"Ejemplo 2 · Cociente y resto\n1. $$47=5\\cdot9+2$$\n   El cociente es 9 y el resto 2.\n2. $$0\\le2<5$$\n   El resto debe ser menor que el divisor positivo.","explore":{"title":"Árbol de factores","desc":"Descompón un número en factores primos por diferentes caminos.","instr":"Elige un número y descompón sus factores hasta llegar a primos.","alt":"Árbol de factores · actividad interactiva opcional, sin porcentaje de avance.","height":850,"html":"<!DOCTYPE html>\n<html lang=\"es\"><head><meta charset=\"UTF-8\"/><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"/><meta name=\"color-scheme\" content=\"light\"/><title>Explora · Árbol de factores · PACE UACh</title><style>:root{--bg:#f3f7fb;--paper:#fff;--ink:#1a3044;--muted:#607588;--stroke:#dce6ed;--main:#2575ac;--main2:#0b9a83;--mist:#e9f4f9;--warm:#fff6e5;--gold:#aa731d;--ok:#137d64;--bad:#a04a3c;--shadow:0 16px 36px rgba(30,62,86,.07)}\n*{box-sizing:border-box}html{font-size:16px}body{margin:0;background:radial-gradient(circle at 90% 0%,#e1f3f7 0%,transparent 32%),var(--bg);font-family:system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif;color:var(--ink);line-height:1.5}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f3bd59;outline-offset:2px}button:disabled{cursor:not-allowed;opacity:.45}\n.shell{width:min(1060px,calc(100% - 32px));margin:26px auto 42px}.hero{padding:25px 27px 24px;color:white;border-radius:22px;background:linear-gradient(119deg,#12476f 0%,#1b7d9f 57%,#138d83 100%);box-shadow:var(--shadow);position:relative;overflow:hidden}.hero:before,.hero:after{content:\"\";position:absolute;border:2px solid #ffffff20;border-radius:50%;width:270px;height:270px;right:-95px;top:-175px}.hero:after{width:180px;height:180px;right:35px;top:-120px}.kicker{text-transform:uppercase;font-size:.77rem;letter-spacing:.14em;font-weight:750;opacity:.88}.hero h1{font-size:clamp(1.48rem,3.6vw,2.15rem);margin:7px 0 5px;line-height:1.17;letter-spacing:-.03em}.hero p{margin:0;max-width:700px;color:#ebf9ff;line-height:1.5}.topline{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.chip{display:inline-flex;border-radius:999px;padding:6px 11px;background:#ffffff2b;font-weight:650;font-size:.79rem;white-space:nowrap;z-index:1}.layout{display:grid;grid-template-columns:335px minmax(0,1fr);align-items:start;gap:16px;margin-top:16px}.card{background:var(--paper);border:1px solid var(--stroke);border-radius:18px;padding:20px;box-shadow:var(--shadow);min-width:0}.card h2,.card h3{margin:0 0 12px;letter-spacing:-.02em}.card h2{font-size:1.14rem}.card h3{font-size:1.02rem}.lede{font-size:.96rem;color:var(--muted);margin:0 0 13px}.muted{color:var(--muted)}.small{font-size:.85rem}.tiny{font-size:.75rem}.controls{display:grid;gap:12px}.field{display:grid;gap:5px}.field label{font-size:.87rem;font-weight:700;color:#344f65}.field select,.field input[type=number]{width:100%;min-height:43px;border:1px solid #cddce7;background:#fff;border-radius:10px;padding:8px 11px;color:var(--ink)}.field input[type=range]{width:100%;accent-color:var(--main2);cursor:pointer}.inline-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pills{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--main);background:var(--main);color:white;font-weight:720;min-height:42px;border-radius:11px;padding:8px 14px;transition:transform .15s,filter .15s}.btn:hover:not(:disabled){filter:brightness(1.06);transform:translateY(-1px)}.btn.alt{background:#f1f7fb;color:#235e82;border-color:#bcd5e4}.btn.minor{border-color:#d4e1e9;background:white;color:#3b5d75}.btn.green{background:#0e8f78;border-color:#0e8f78}.btn.active{background:#155d89;color:white;border-color:#155d89}.btn.sm{font-size:.85rem;min-height:36px;padding:6px 10px}.btnrow{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.panel{border-radius:14px;background:#f5fafc;border:1px solid #dfecf2;padding:15px}.panel.warm{background:var(--warm);border-color:#f1e2c4}.panel.green{background:#eaf8f3;border-color:#c9e9dd}.panel p:last-child{margin-bottom:0}.panel p:first-child{margin-top:0}.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat{background:#f1f8fb;border:1px solid #ddebf1;border-radius:13px;padding:12px}.stat .value{font-size:1.45rem;font-weight:800;color:#1a6289;line-height:1.25}.stat .label{font-size:.78rem;color:var(--muted)}.formula{font-family:Georgia,\"Times New Roman\",serif;font-size:clamp(1.25rem,3.5vw,1.8rem);font-weight:650;line-height:1.5;text-align:center;word-break:normal}.formula.big{font-size:clamp(1.6rem,4.5vw,2.4rem)}.formula-row{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}.frac{display:inline-flex;flex-direction:column;vertical-align:middle;text-align:center;line-height:1.07;padding:0 2px;font-variant-numeric:tabular-nums}.frac>.n{display:block;border-bottom:1.7px solid currentColor;padding:0 5px 3px}.frac>.d{display:block;padding:3px 5px 0}.stepper{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-top:14px}.stepbadge{font-size:.8rem;font-weight:700;color:#587186}.bar{display:flex;overflow:hidden;border:1px solid #96b0c3;height:32px;border-radius:7px;background:#eef3f5}.segment{flex:1;border-right:1px solid #ffffff90;min-width:0;background:#edf3f7}.segment:last-child{border-right:0}.segment.on{background:#248ac4}.segment.on.teal{background:#28a88b}.segment.on.amber{background:#e4a145}.section-gap{height:16px}.note{border-left:4px solid #d9a03f;background:#fff8e9;padding:11px 13px;border-radius:8px;font-size:.9rem;color:#6b5127}.footer{margin-top:16px;color:#657b8d;font-size:.8rem;text-align:center}.frame{border:1px solid #d8e6ec;background:#f9fcfd;border-radius:13px;overflow:hidden;padding:6px}.frame svg{width:100%;height:auto;display:block}.highlight{color:#0d887b;font-weight:800}.warn{color:#a45327;font-weight:780}.subhead{font-weight:800;font-size:.89rem;color:#42617a;text-transform:uppercase;letter-spacing:.055em;margin-bottom:8px}.reveal{animation:appear .3s ease-out}@keyframes appear{from{opacity:.25;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}\n@media(max-width:760px){.shell{width:min(100% - 18px,610px);margin:9px auto 28px}.hero{padding:19px;border-radius:16px}.layout{grid-template-columns:1fr;gap:11px;margin-top:11px}.card{padding:16px;border-radius:14px}.topline{flex-direction:column}.chip{align-self:flex-start}.inline-fields{grid-template-columns:1fr 1fr}.footer{padding:0 8px}.stat .value{font-size:1.25rem}}\n@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}\n</style></head><body><div class=\"shell\"><header class=\"hero\"><div class=\"topline\"><div><div class=\"kicker\">EXPLORA · UNIDAD I · ESTACIONES 3–4</div><h1>Árbol de factores</h1><p>Divide números compuestos hasta llegar a factores primos. Puedes tomar caminos distintos y descubrir qué se conserva.</p></div><span class=\"chip\">Exploración libre</span></div></header>\n<div class=\"layout\"><aside class=\"card\"><h2>1. Escoge un número</h2><div class=\"field\"><label for=\"num\">Número natural (2 a 360)</label><input type=\"number\" min=\"2\" max=\"360\" step=\"1\" id=\"num\" value=\"84\"/></div><div class=\"section-gap\"></div><div class=\"pills\"><button class=\"btn minor sm\" data-value=\"60\">60</button><button class=\"btn minor sm\" data-value=\"84\">84</button><button class=\"btn minor sm\" data-value=\"180\">180</button><button class=\"btn minor sm\" data-value=\"360\">360</button></div><div class=\"section-gap\"></div><button class=\"btn alt\" id=\"start\">Construir árbol</button><div class=\"section-gap\"></div>\n<div class=\"panel\"><h3>2. Elige un número para dividir</h3><p id=\"chosenInfo\" class=\"lede\">Selecciona un nodo compuesto del árbol.</p><div class=\"field\"><label for=\"pair\">Par de factores</label><select id=\"pair\"></select></div><div class=\"section-gap\"></div><div class=\"btnrow\"><button class=\"btn green\" id=\"split\">Separar factores</button><button class=\"btn minor\" id=\"undo\">Deshacer último</button></div></div>\n<div class=\"section-gap\"></div><div class=\"note\">Un número <strong>primo</strong> tiene exactamente dos divisores positivos: 1 y él mismo. El <strong>1 no es primo</strong>.</div></aside>\n<main class=\"card\"><h2>3. Construye y observa</h2><p class=\"lede\">Pulsa un recuadro azul para elegir qué descomponer. Los verdes ya son primos. En celular, <strong>desliza el árbol hacia los lados</strong> para ver todas sus ramas.</p><div class=\"frame\" style=\"overflow-x:auto\"><svg id=\"tree\" viewBox=\"0 0 650 245\" role=\"img\" aria-label=\"Árbol de descomposición en factores primos\"></svg></div><div class=\"section-gap\"></div><div class=\"panel green\" aria-live=\"polite\"><div class=\"subhead\" id=\"statusTitle\">Comienza la descomposición</div><div class=\"formula\" id=\"primeResult\">84</div><p class=\"small\" id=\"statusDesc\" style=\"text-align:center\"></p></div>\n<div class=\"section-gap\"></div><div class=\"btnrow\"><button id=\"restart\" class=\"btn alt\">↺ Otro camino con el mismo número</button><button id=\"auto\" class=\"btn minor\">Ver una descomposición</button></div></main></div>\n<div class=\"footer\">Puedes repetir con otros pares de factores. No hay una puntuación ni se registra progreso.</div></div>\n<script>function $(id){return document.getElementById(id)}\nfunction clamp(v,a,b){return Math.min(b,Math.max(a,Number(v)||0))}\nfunction gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b]}return a}\nfunction lcm(a,b){return Math.abs(a*b)/gcd(a,b)}\nfunction fmt(n){return String(n).replace('-', '−')}\nfunction fraction(n,d){let s=n<0?'−':'';n=Math.abs(n);return `<span class=\"frac\"><span class=\"n\">${s}${n}</span><span class=\"d\">${d}</span></span>`}\nfunction fractionStr(n,d){return `${fmt(n)}/${d}`}\nfunction simplify(n,d){if(d<0){n=-n;d=-d}const g=gcd(n,d)||1;return [n/g,d/g]}\nfunction barMarkup(n,d,cls=''){let out='';for(let i=0;i<d;i++){out+=`<span class=\"segment ${i<n?'on '+cls:''}\" aria-hidden=\"true\"></span>`}return `<div class=\"bar\" role=\"img\" aria-label=\"${n} de ${d} partes sombreadas\">${out}</div>`}\nfunction options(el,values,selected){el.innerHTML=values.map(v=>`<option value=\"${v}\" ${String(v)===String(selected)?'selected':''}>${v}</option>`).join('')}\nfunction setText(id,val){$(id).textContent=val}\n</script><script>let nextId=0, root=null, selected=null, history=[];\nfunction isPrime(n){if(n<2)return false;for(let d=2;d*d<=n;d++)if(n%d===0)return false;return true}\nfunction pairs(n){let out=[];for(let a=2;a*a<=n;a++)if(n%a===0)out.push([a,n/a]);return out}\nfunction newNode(n){return {id:++nextId,n,left:null,right:null}}\nfunction leaves(node){return node.left?[...leaves(node.left),...leaves(node.right)]:[node]}\nfunction findNode(node,id){if(!node)return null;if(node.id===id)return node;return findNode(node.left,id)||findNode(node.right,id)}\nfunction listNodes(node){return node.left?[node,...listNodes(node.left),...listNodes(node.right)]:[node]}\nfunction mathFactors(numbers){let groups={};numbers.sort((a,b)=>a-b).forEach(n=>groups[n]=(groups[n]||0)+1);const supers=['⁰','¹','²','³','⁴','⁵','⁶','⁷','⁸','⁹'];return Object.entries(groups).map(([p,e])=>p+(e>1?String(e).split('').map(d=>supers[+d]).join(''):'')).join(' · ')}\nfunction setup(n){root=newNode(n);history=[];selected=isPrime(n)?null:root.id;render()}\nfunction coords(node,depth,lspace){let graph=[];let leafNum=0;function assign(n,d){let x;if(n.left){let a=assign(n.left,d+1),b=assign(n.right,d+1);x=(a+b)/2}else{x=65+leafNum*lspace;leafNum++}graph.push({n,x,y:49+d*95,d});return x}assign(node,0);return graph}\nfunction render(){const ll=leaves(root),depth=Math.max(...listNodes(root).map(n=>{function dep(cur,d){if(cur.id===n.id)return d;return cur.left?dep(cur.left,d+1)??dep(cur.right,d+1):null}return dep(root,0)})),width=Math.max(650,ll.length*105+90),space=(width-130)/Math.max(1,ll.length-1);let graph=coords(root,0,space),height=depth*95+126;if(ll.length===1)graph[0].x=width/2;\nconst arr=graph.map(g=>{let n=g.n,pr=isPrime(n.n),pick=n.id===selected,composite=!n.left&&!pr,fill=pr?'#e1f5e9':pick?'#d4eaf9':composite?'#e9f4fb':'#f2f4f7';let stroke=pr?'#1b996b':pick?'#1671a2':'#8caaba';let label=pr?'PRIMO':composite?'DIVIDE':'DESCOMPUESTO';return {g,fill,stroke,label,selectable:composite}});\nlet lines='';for(let {g} of arr){let n=g.n;if(n.left){for(let ch of [n.left,n.right]){let child=arr.find(a=>a.g.n.id===ch.id);lines+=`<line x1=\"${g.x}\" y1=\"${g.y+19}\" x2=\"${child.g.x}\" y2=\"${child.g.y-20}\" stroke=\"#93b1c4\" stroke-width=\"3\"/>`}}}\nlet nodes=arr.map(({g,fill,stroke,label,selectable})=>{let n=g.n;return `<g data-id=\"${n.id}\" ${selectable?'role=\"button\" tabindex=\"0\"':'aria-hidden=\"true\"'} style=\"${selectable?'cursor:pointer;':''}\" aria-label=\"${n.n}: ${label.toLowerCase()}\"><rect x=\"${g.x-42}\" y=\"${g.y-21}\" width=\"84\" height=\"49\" rx=\"12\" fill=\"${fill}\" stroke=\"${stroke}\" stroke-width=\"${n.id===selected?3:2}\"/><text x=\"${g.x}\" y=\"${g.y+2}\" text-anchor=\"middle\" fill=\"#224259\" font-size=\"19\" font-weight=\"800\">${n.n}</text><text x=\"${g.x}\" y=\"${g.y+19}\" text-anchor=\"middle\" fill=\"${stroke}\" font-size=\"9\" font-weight=\"800\">${label}</text></g>`}).join('');\nlet svg=$('tree');svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.style.minWidth=Math.min(width,720)+'px';svg.innerHTML=lines+nodes;\nsvg.querySelectorAll('[data-id][role=button]').forEach(el=>{const pick=()=>{selected=Number(el.dataset.id);render()};el.addEventListener('click',pick);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick()}})});\nconst node=findNode(root,selected),available=node?pairs(node.n):[];options($('pair'),available.map(x=>x[0]),available.length?available[0][0]:null);$('pair').disabled=!available.length;$('split').disabled=!available.length;$('undo').disabled=!history.length;\nsetText('chosenInfo',node?`Número seleccionado: ${node.n}. Elige dos factores mayores que 1 cuyo producto sea ${node.n}.`:'Selecciona un nodo compuesto (azul).');\n$('pair').innerHTML=available.map(([a,b])=>`<option value=\"${a}\">${a} × ${b}</option>`).join('');\nlet primes=ll.filter(n=>isPrime(n.n)).map(n=>n.n),comps=ll.filter(n=>!isPrime(n.n));let completed=!comps.length;\nsetText('statusTitle',completed?'¡Todos los extremos son primos!':`Factores primos encontrados: ${primes.length}`);\nsetText('primeResult',completed?`${root.n} = ${mathFactors(primes)}`:(primes.length?`${primes.sort((a,b)=>a-b).join(' · ')} · (${comps.map(x=>x.n).join(' · ')})`:`${root.n} = sigue dividiendo`));\nsetText('statusDesc',completed?'Prueba ahora otra forma de dividir el número: la factorización prima final será la misma.':'Los extremos verdes son primos. Continúa separando los recuadros azules.');}\n$('split').addEventListener('click',()=>{let n=findNode(root,selected);if(!n)return;let a=Number($('pair').value);if(!a||n.n%a!==0)return;history.push({id:n.id});n.left=newNode(a);n.right=newNode(n.n/a);let comp=leaves(root).find(x=>!isPrime(x.n));selected=comp?comp.id:null;render()});\n$('undo').addEventListener('click',()=>{let last=history.pop();if(!last)return;let node=findNode(root,last.id);node.left=null;node.right=null;selected=node.id;render()});\n$('restart').addEventListener('click',()=>setup(root.n));$('start').addEventListener('click',()=>{let n=Number($('num').value);if(!Number.isInteger(n)||n<2||n>360){$('num').setCustomValidity('Introduce un entero entre 2 y 360');$('num').reportValidity();return}$('num').setCustomValidity('');setup(n)});\n$('auto').addEventListener('click',()=>{let n=leaves(root).find(x=>!isPrime(x.n));if(!n){setText('statusDesc','¡El árbol ya está completo!');return}let a=pairs(n.n)[0][0];history.push({id:n.id});n.left=newNode(a);n.right=newNode(n.n/a);let nxt=leaves(root).find(x=>!isPrime(x.n));selected=nxt?nxt.id:null;render()});\ndocument.querySelectorAll('[data-value]').forEach(b=>b.addEventListener('click',()=>{$('num').value=b.dataset.value;setup(Number(b.dataset.value))}));setup(84);\n</script></body></html>"},"example3":"Ejemplo 3 · Factorización de 84\n1. $$84=2\\cdot42$$\n   Separamos un factor primo.\n2. $$84=2\\cdot2\\cdot21$$\n   Volvemos a dividir por 2.\n3. $$84=2^2\\cdot3\\cdot7$$\n   Todos los factores son primos.","draw":5,"unit":0},{"id":"u1-s004","title":"MCD y MCM","subtitle":"Factores comunes y múltiplos","group":1,"symbol":"✧","minutes":35,"concept":"Obtener MCD y MCM usando la descomposición prima y explicar cuándo conviene cada uno.\n\nMCD: producto de los factores comunes con el menor exponente.\nMCM: producto de todos los factores presentes con el mayor exponente.\nLa tabla de factores organiza el mismo razonamiento.","example":"Calcula MCD y MCM de $60$ y $90$.\n1. $$60=2^2\\cdot3\\cdot5$$ — Factorizamos el primer número.\n2. $$90=2\\cdot3^2\\cdot5$$ — Factorizamos el segundo.\n3. $$\\mathrm{MCD}(60,90)=2\\cdot3\\cdot5=30$$ — Tomamos exponentes menores.\n4. $$\\mathrm{MCM}(60,90)=2^2\\cdot3^2\\cdot5=180$$ — Tomamos exponentes mayores.","media":[],"practice":[{"q":"Calcula el $MCD$ de $12$ y $18$.","options":["$18$","$6$","$36$","$12$"],"correct":1,"why":"$12=2^{2}\\cdot 3$ y $18=2\\cdot 3^{2}$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $6$.","level":1},{"q":"Calcula el $MCM$ de $18$ y $24$.","options":["$18$","$72$","$24$","$6$"],"correct":1,"why":"$18=2\\cdot 3^{2}$ y $24=2^{3}\\cdot 3$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $72$.","level":1},{"q":"Calcula el $MCD$ de $16$ y $20$.","options":["$4$","$16$","$80$","$20$"],"correct":0,"why":"$16=2^{4}$ y $20=2^{2}\\cdot 5$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $4$.","level":1},{"q":"Calcula el $MCM$ de $25$ y $40$.","options":["$5$","$200$","$40$","$25$"],"correct":1,"why":"$25=5^{2}$ y $40=2^{3}\\cdot 5$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $200$.","level":1},{"q":"Calcula el $MCD$ de $14$ y $35$.","options":["$7$","$35$","$14$","$70$"],"correct":0,"why":"$14=2\\cdot 7$ y $35=5\\cdot 7$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $7$.","level":1},{"q":"Calcula el $MCM$ de $30$ y $45$.","options":["$15$","$90$","$30$","$45$"],"correct":1,"why":"$30=2\\cdot 3\\cdot 5$ y $45=3^{2}\\cdot 5$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $90$.","level":1},{"q":"Calcula el $MCD$ de $36$ y $54$.","options":["$18$","$108$","$54$","$36$"],"correct":0,"why":"$36=2^{2}\\cdot 3^{2}$ y $54=2\\cdot 3^{3}$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $18$.","level":1},{"q":"Calcula el $MCM$ de $42$ y $56$.","options":["$42$","$56$","$14$","$168$"],"correct":3,"why":"$42=2\\cdot 3\\cdot 7$ y $56=2^{3}\\cdot 7$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $168$.","level":1},{"q":"Calcula el $MCD$ de $15$ y $28$.","options":["$28$","$15$","$420$","$1$"],"correct":3,"why":"$15=3\\cdot 5$ y $28=2^{2}\\cdot 7$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $1$.","level":2},{"q":"Calcula el $MCM$ de $48$ y $60$.","options":["$48$","$240$","$60$","$12$"],"correct":1,"why":"$48=2^{4}\\cdot 3$ y $60=2^{2}\\cdot 3\\cdot 5$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $240$.","level":2},{"q":"Calcula el $MCD$ de $24$ y $30$.","options":["$120$","$30$","$24$","$6$"],"correct":3,"why":"$24=2^{3}\\cdot 3$ y $30=2\\cdot 3\\cdot 5$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $6$.","level":2},{"q":"Calcula el $MCM$ de $18$ y $27$.","options":["$54$","$9$","$27$","$18$"],"correct":0,"why":"$18=2\\cdot 3^{2}$ y $27=3^{3}$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $54$.","level":2},{"q":"Calcula el $MCD$ de $20$ y $32$.","options":["$160$","$20$","$4$","$32$"],"correct":2,"why":"$20=2^{2}\\cdot 5$ y $32=2^{5}$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $4$.","level":2},{"q":"Calcula el $MCM$ de $45$ y $75$.","options":["$45$","$225$","$15$","$75$"],"correct":1,"why":"$45=3^{2}\\cdot 5$ y $75=3\\cdot 5^{2}$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $225$.","level":2},{"q":"Calcula el $MCD$ de $28$ y $42$.","options":["$14$","$42$","$28$","$84$"],"correct":0,"why":"$28=2^{2}\\cdot 7$ y $42=2\\cdot 3\\cdot 7$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $14$.","level":2},{"q":"Calcula el $MCM$ de $36$ y $48$.","options":["$36$","$12$","$144$","$48$"],"correct":2,"why":"$36=2^{2}\\cdot 3^{2}$ y $48=2^{4}\\cdot 3$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $144$.","level":2},{"q":"Calcula el $MCD$ de $84$ y $126$.","options":["$84$","$252$","$42$","$126$"],"correct":2,"why":"$84=2^{2}\\cdot 3\\cdot 7$ y $126=2\\cdot 3^{2}\\cdot 7$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $42$.","level":3},{"q":"Calcula el $MCM$ de $72$ y $90$.","options":["$18$","$360$","$90$","$72$"],"correct":1,"why":"$72=2^{3}\\cdot 3^{2}$ y $90=2\\cdot 3^{2}\\cdot 5$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $360$.","level":3},{"q":"Calcula el $MCD$ de $105$ y $140$.","options":["$420$","$140$","$105$","$35$"],"correct":3,"why":"$105=3\\cdot 5\\cdot 7$ y $140=2^{2}\\cdot 5\\cdot 7$. Para el MCD tomamos los exponentes menores de los factores comunes. Resultado: $35$.","level":3},{"q":"Calcula el $MCM$ de $96$ y $144$.","options":["$288$","$48$","$96$","$144$"],"correct":0,"why":"$96=2^{5}\\cdot 3$ y $144=2^{4}\\cdot 3^{2}$. Para el MCM tomamos los exponentes mayores de todos los factores. Resultado: $288$.","level":3}],"check":{"q":"Dos señales se repiten cada $6$ y $8$ minutos. Si coinciden ahora, ¿en cuántos minutos volverán a coincidir?","options":["$12$","$24$","$48$"],"correct":1,"why":"El MCM de $6$ y $8$ es $24$."},"learn":{"goal":"Obtener MCD y MCM usando la descomposición prima y explicar cuándo conviene cada uno.","idea":"MCD: producto de los factores comunes con el menor exponente.\nMCM: producto de todos los factores presentes con el mayor exponente.\nLa tabla de factores organiza el mismo razonamiento.","steps":{"title":"Calcula MCD y MCM de $60$ y $90$.","items":[{"math":"60=2^2\\cdot3\\cdot5","why":"Factorizamos el primer número.","side":{"title":"Factores","text":"El $2$ aparece dos veces; $3$ y $5$, una vez."}},{"math":"90=2\\cdot3^2\\cdot5","why":"Factorizamos el segundo.","side":{"title":"Comparación","text":"$90$ tiene un $2$, dos $3$ y un $5$."}},{"math":"\\mathrm{MCD}(60,90)=2\\cdot3\\cdot5=30","why":"Tomamos exponentes menores.","side":{"title":"Comunes","text":"Para dividir a ambos, no podemos usar más copias de un primo que las presentes en cada número."}},{"math":"\\mathrm{MCM}(60,90)=2^2\\cdot3^2\\cdot5=180","why":"Tomamos exponentes mayores.","side":{"title":"Todos los factores","text":"Para ser múltiplo de ambos necesitamos todas las copias requeridas."}}]},"warn":"Atención: el MCD es divisor de ambos números; el MCM es múltiplo de ambos. No intercambies las reglas de exponentes."},"example2":"Ejemplo 2 · MCD y MCM de 12 y 18\n1. $$12=2^2\\cdot3,\\quad18=2\\cdot3^2$$\n   Factorizamos.\n2. $$\\mathrm{MCD}(12,18)=2\\cdot3=6$$\n   Exponente menor de cada factor común.\n3. $$\\mathrm{MCM}(12,18)=2^2\\cdot3^2=36$$\n   Exponente mayor de cada factor presente.","example3":"Ejemplo 3 · Factores distintos\n1. $$8=2^3,\\quad15=3\\cdot5$$\n   No hay factores primos comunes.\n2. $$\\mathrm{MCD}(8,15)=1$$\n   No tienen divisor común mayor que 1.\n3. $$\\mathrm{MCM}(8,15)=2^3\\cdot3\\cdot5=120$$\n   Tomamos todos los factores.","draw":5,"unit":0},{"id":"u1-s005","title":"Fracciones equivalentes","subtitle":"Amplificar y simplificar","group":1,"symbol":"✧","minutes":30,"concept":"Reconocer fracciones equivalentes y simplificarlas hasta una expresión irreducible.\n\nEquivalentes: multiplicar o dividir numerador y denominador por el mismo número distinto de cero conserva la fracción.\nIrreducible: numerador y denominador no tienen divisor común mayor que $1$.","example":"Simplifica $\\frac{42}{56}$.\n1. $$\\frac{42}{56}$$ — Fracción inicial.\n2. $$\\mathrm{MCD}(42,56)=14$$ — Buscamos un divisor común máximo.\n3. $$\\frac{42}{56}=\\frac{42\\div14}{56\\div14}$$ — Dividimos ambas partes por 14.\n4. $$\\frac{42}{56}=\\frac34$$ — Obtenemos la forma irreducible.","media":[],"practice":[{"q":"Simplifica $\\dfrac{6}{8}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{2}{3}$","$\\dfrac{3}{4}$","$\\dfrac{7}{4}$","$\\dfrac{7}{8}$"],"correct":1,"why":"$2$ es el MCD; dividimos numerador y denominador entre 2 y obtenemos $\\dfrac{3}{4}$.","level":1},{"q":"¿Cuál fracción se obtiene al amplificar $\\dfrac{9}{15}$ por $2$?","options":["$\\dfrac{18}{15}$","$\\dfrac{27}{30}$","$\\dfrac{18}{30}$","$\\dfrac{9}{30}$"],"correct":2,"why":"Multiplicamos numerador y denominador por 2: $9\\cdot2/15\\cdot2=18/30$.","level":1},{"q":"Simplifica $\\dfrac{14}{21}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{2}{3}$","$\\dfrac{5}{7}$","$\\dfrac{5}{3}$","$\\dfrac{7}{11}$"],"correct":0,"why":"$7$ es el MCD; dividimos numerador y denominador entre 7 y obtenemos $\\dfrac{2}{3}$.","level":1},{"q":"Simplifica $\\dfrac{15}{35}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{5}{12}$","$\\dfrac{3}{7}$","$\\dfrac{16}{35}$","$\\dfrac{10}{7}$"],"correct":1,"why":"$5$ es el MCD; dividimos numerador y denominador entre 5 y obtenemos $\\dfrac{3}{7}$.","level":1},{"q":"Simplifica $\\dfrac{18}{24}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{19}{24}$","$\\dfrac{7}{4}$","$\\dfrac{3}{4}$","$\\dfrac{18}{25}$"],"correct":2,"why":"$6$ es el MCD; dividimos numerador y denominador entre 6 y obtenemos $\\dfrac{3}{4}$.","level":1},{"q":"¿Cuál fracción se obtiene al amplificar $\\dfrac{20}{32}$ por $3$?","options":["$\\dfrac{60}{96}$","$\\dfrac{80}{96}$","$\\dfrac{20}{96}$","$\\dfrac{60}{32}$"],"correct":0,"why":"Multiplicamos numerador y denominador por 3: $20\\cdot3/32\\cdot3=60/96$.","level":1},{"q":"Simplifica $\\dfrac{27}{45}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{27}{46}$","$\\dfrac{8}{5}$","$\\dfrac{28}{45}$","$\\dfrac{3}{5}$"],"correct":3,"why":"$9$ es el MCD; dividimos numerador y denominador entre 9 y obtenemos $\\dfrac{3}{5}$.","level":1},{"q":"Simplifica $\\dfrac{42}{56}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{43}{56}$","$\\dfrac{7}{4}$","$\\dfrac{3}{4}$","$\\dfrac{14}{19}$"],"correct":2,"why":"$14$ es el MCD; dividimos numerador y denominador entre 14 y obtenemos $\\dfrac{3}{4}$.","level":1},{"q":"Simplifica $\\dfrac{24}{60}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{7}{5}$","$\\dfrac{24}{61}$","$\\dfrac{2}{5}$","$\\dfrac{5}{12}$"],"correct":2,"why":"$12$ es el MCD; dividimos numerador y denominador entre 12 y obtenemos $\\dfrac{2}{5}$.","level":2},{"q":"¿Cuál fracción se obtiene al amplificar $\\dfrac{35}{50}$ por $4$?","options":["$\\dfrac{175}{200}$","$\\dfrac{140}{200}$","$\\dfrac{140}{50}$","$\\dfrac{35}{200}$"],"correct":1,"why":"Multiplicamos numerador y denominador por 4: $35\\cdot4/50\\cdot4=140/200$.","level":2},{"q":"Simplifica $\\dfrac{48}{72}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{49}{72}$","$\\dfrac{2}{3}$","$\\dfrac{48}{73}$","$\\dfrac{5}{3}$"],"correct":1,"why":"$24$ es el MCD; dividimos numerador y denominador entre 24 y obtenemos $\\dfrac{2}{3}$.","level":2},{"q":"Simplifica $\\dfrac{36}{84}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{37}{84}$","$\\dfrac{10}{7}$","$\\dfrac{3}{7}$","$\\dfrac{36}{85}$"],"correct":2,"why":"$12$ es el MCD; dividimos numerador y denominador entre 12 y obtenemos $\\dfrac{3}{7}$.","level":2},{"q":"Simplifica $\\dfrac{54}{90}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{3}{5}$","$\\dfrac{11}{18}$","$\\dfrac{8}{5}$","$\\dfrac{54}{91}$"],"correct":0,"why":"$18$ es el MCD; dividimos numerador y denominador entre 18 y obtenemos $\\dfrac{3}{5}$.","level":2},{"q":"¿Cuál fracción se obtiene al amplificar $\\dfrac{56}{96}$ por $5$?","options":["$\\dfrac{280}{480}$","$\\dfrac{280}{96}$","$\\dfrac{336}{480}$","$\\dfrac{56}{480}$"],"correct":0,"why":"Multiplicamos numerador y denominador por 5: $56\\cdot5/96\\cdot5=280/480$.","level":2},{"q":"Simplifica $\\dfrac{63}{105}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{64}{105}$","$\\dfrac{63}{106}$","$\\dfrac{3}{5}$","$\\dfrac{8}{5}$"],"correct":2,"why":"$21$ es el MCD; dividimos numerador y denominador entre 21 y obtenemos $\\dfrac{3}{5}$.","level":2},{"q":"Simplifica $\\dfrac{72}{108}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{73}{108}$","$\\dfrac{2}{3}$","$\\dfrac{5}{3}$","$\\dfrac{72}{109}$"],"correct":1,"why":"$36$ es el MCD; dividimos numerador y denominador entre 36 y obtenemos $\\dfrac{2}{3}$.","level":2},{"q":"Simplifica $\\dfrac{105}{140}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{35}{47}$","$\\dfrac{7}{4}$","$\\dfrac{3}{4}$","$\\dfrac{53}{70}$"],"correct":2,"why":"$35$ es el MCD; dividimos numerador y denominador entre 35 y obtenemos $\\dfrac{3}{4}$.","level":3},{"q":"¿Cuál fracción se obtiene al amplificar $\\dfrac{84}{132}$ por $2$?","options":["$\\dfrac{168}{132}$","$\\dfrac{168}{264}$","$\\dfrac{84}{264}$","$\\dfrac{252}{264}$"],"correct":1,"why":"Multiplicamos numerador y denominador por 2: $84\\cdot2/132\\cdot2=168/264$.","level":3},{"q":"Simplifica $\\dfrac{126}{198}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{127}{198}$","$\\dfrac{7}{11}$","$\\dfrac{126}{199}$","$\\dfrac{18}{11}$"],"correct":1,"why":"$18$ es el MCD; dividimos numerador y denominador entre 18 y obtenemos $\\dfrac{7}{11}$.","level":3},{"q":"Simplifica $\\dfrac{144}{216}$ hasta obtener la fracción irreducible.","options":["$\\dfrac{144}{217}$","$\\dfrac{5}{3}$","$\\dfrac{145}{216}$","$\\dfrac{2}{3}$"],"correct":3,"why":"$72$ es el MCD; dividimos numerador y denominador entre 72 y obtenemos $\\dfrac{2}{3}$.","level":3}],"check":{"q":"De $12$ muestras, $8$ reaccionan. ¿Qué fracción simplificada representan?","options":["$\\dfrac{2}{3}$","$\\dfrac{3}{2}$","$\\dfrac{1}{3}$"],"correct":0,"why":"$8/12=2/3$."},"learn":{"goal":"Reconocer fracciones equivalentes y simplificarlas hasta una expresión irreducible.","idea":"Equivalentes: multiplicar o dividir numerador y denominador por el mismo número distinto de cero conserva la fracción.\nIrreducible: numerador y denominador no tienen divisor común mayor que $1$.","steps":{"title":"Simplifica $\\frac{42}{56}$.","items":[{"math":"\\frac{42}{56}","why":"Fracción inicial.","side":{"title":"Meta","text":"Queremos una escritura más sencilla con el mismo valor."}},{"math":"\\mathrm{MCD}(42,56)=14","why":"Buscamos un divisor común máximo.","side":{"title":"Divisores","text":"$42=3\\cdot14$ y $56=4\\cdot14$."}},{"math":"\\frac{42}{56}=\\frac{42\\div14}{56\\div14}","why":"Dividimos ambas partes por 14.","side":{"title":"Equivalencia","text":"Realizar la misma división arriba y abajo no altera el cociente."}},{"math":"\\frac{42}{56}=\\frac34","why":"Obtenemos la forma irreducible.","side":{"title":"Verificación","text":"$\\mathrm{MCD}(3,4)=1$."}}]},"warn":"Atención: $\\frac23$ y $\\frac24$ no son equivalentes. Cambiar solo el denominador cambia el valor. Nunca puede quedar denominador cero."},"example2":"Ejemplo 2 · Simplificar con signo\n1. $$-\\dfrac{18}{24}$$\n   Identificamos una fracción negativa.\n2. $$\\mathrm{MCD}(18,24)=6$$\n   Buscamos un divisor común.\n3. $$-\\dfrac{18\\div6}{24\\div6}=-\\dfrac34$$\n   Simplificamos sin perder el signo.","explore":{"title":"Fracciones equivalentes","desc":"Amplifica y simplifica fracciones sin cambiar su valor.","instr":"Modifica numerador y denominador para comprobar equivalencias.","alt":"Fracciones equivalentes · actividad interactiva opcional, sin porcentaje de avance.","height":850,"html":"<!DOCTYPE html>\n<html lang=\"es\"><head><meta charset=\"UTF-8\"/><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"/><meta name=\"color-scheme\" content=\"light\"/><title>Explora · Fracciones equivalentes · PACE UACh</title><style>:root{--bg:#f3f7fb;--paper:#fff;--ink:#1a3044;--muted:#607588;--stroke:#dce6ed;--main:#2575ac;--main2:#0b9a83;--mist:#e9f4f9;--warm:#fff6e5;--gold:#aa731d;--ok:#137d64;--bad:#a04a3c;--shadow:0 16px 36px rgba(30,62,86,.07)}\n*{box-sizing:border-box}html{font-size:16px}body{margin:0;background:radial-gradient(circle at 90% 0%,#e1f3f7 0%,transparent 32%),var(--bg);font-family:system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif;color:var(--ink);line-height:1.5}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f3bd59;outline-offset:2px}button:disabled{cursor:not-allowed;opacity:.45}\n.shell{width:min(1060px,calc(100% - 32px));margin:26px auto 42px}.hero{padding:25px 27px 24px;color:white;border-radius:22px;background:linear-gradient(119deg,#12476f 0%,#1b7d9f 57%,#138d83 100%);box-shadow:var(--shadow);position:relative;overflow:hidden}.hero:before,.hero:after{content:\"\";position:absolute;border:2px solid #ffffff20;border-radius:50%;width:270px;height:270px;right:-95px;top:-175px}.hero:after{width:180px;height:180px;right:35px;top:-120px}.kicker{text-transform:uppercase;font-size:.77rem;letter-spacing:.14em;font-weight:750;opacity:.88}.hero h1{font-size:clamp(1.48rem,3.6vw,2.15rem);margin:7px 0 5px;line-height:1.17;letter-spacing:-.03em}.hero p{margin:0;max-width:700px;color:#ebf9ff;line-height:1.5}.topline{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.chip{display:inline-flex;border-radius:999px;padding:6px 11px;background:#ffffff2b;font-weight:650;font-size:.79rem;white-space:nowrap;z-index:1}.layout{display:grid;grid-template-columns:335px minmax(0,1fr);align-items:start;gap:16px;margin-top:16px}.card{background:var(--paper);border:1px solid var(--stroke);border-radius:18px;padding:20px;box-shadow:var(--shadow);min-width:0}.card h2,.card h3{margin:0 0 12px;letter-spacing:-.02em}.card h2{font-size:1.14rem}.card h3{font-size:1.02rem}.lede{font-size:.96rem;color:var(--muted);margin:0 0 13px}.muted{color:var(--muted)}.small{font-size:.85rem}.tiny{font-size:.75rem}.controls{display:grid;gap:12px}.field{display:grid;gap:5px}.field label{font-size:.87rem;font-weight:700;color:#344f65}.field select,.field input[type=number]{width:100%;min-height:43px;border:1px solid #cddce7;background:#fff;border-radius:10px;padding:8px 11px;color:var(--ink)}.field input[type=range]{width:100%;accent-color:var(--main2);cursor:pointer}.inline-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pills{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--main);background:var(--main);color:white;font-weight:720;min-height:42px;border-radius:11px;padding:8px 14px;transition:transform .15s,filter .15s}.btn:hover:not(:disabled){filter:brightness(1.06);transform:translateY(-1px)}.btn.alt{background:#f1f7fb;color:#235e82;border-color:#bcd5e4}.btn.minor{border-color:#d4e1e9;background:white;color:#3b5d75}.btn.green{background:#0e8f78;border-color:#0e8f78}.btn.active{background:#155d89;color:white;border-color:#155d89}.btn.sm{font-size:.85rem;min-height:36px;padding:6px 10px}.btnrow{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.panel{border-radius:14px;background:#f5fafc;border:1px solid #dfecf2;padding:15px}.panel.warm{background:var(--warm);border-color:#f1e2c4}.panel.green{background:#eaf8f3;border-color:#c9e9dd}.panel p:last-child{margin-bottom:0}.panel p:first-child{margin-top:0}.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat{background:#f1f8fb;border:1px solid #ddebf1;border-radius:13px;padding:12px}.stat .value{font-size:1.45rem;font-weight:800;color:#1a6289;line-height:1.25}.stat .label{font-size:.78rem;color:var(--muted)}.formula{font-family:Georgia,\"Times New Roman\",serif;font-size:clamp(1.25rem,3.5vw,1.8rem);font-weight:650;line-height:1.5;text-align:center;word-break:normal}.formula.big{font-size:clamp(1.6rem,4.5vw,2.4rem)}.formula-row{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}.frac{display:inline-flex;flex-direction:column;vertical-align:middle;text-align:center;line-height:1.07;padding:0 2px;font-variant-numeric:tabular-nums}.frac>.n{display:block;border-bottom:1.7px solid currentColor;padding:0 5px 3px}.frac>.d{display:block;padding:3px 5px 0}.stepper{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-top:14px}.stepbadge{font-size:.8rem;font-weight:700;color:#587186}.bar{display:flex;overflow:hidden;border:1px solid #96b0c3;height:32px;border-radius:7px;background:#eef3f5}.segment{flex:1;border-right:1px solid #ffffff90;min-width:0;background:#edf3f7}.segment:last-child{border-right:0}.segment.on{background:#248ac4}.segment.on.teal{background:#28a88b}.segment.on.amber{background:#e4a145}.section-gap{height:16px}.note{border-left:4px solid #d9a03f;background:#fff8e9;padding:11px 13px;border-radius:8px;font-size:.9rem;color:#6b5127}.footer{margin-top:16px;color:#657b8d;font-size:.8rem;text-align:center}.frame{border:1px solid #d8e6ec;background:#f9fcfd;border-radius:13px;overflow:hidden;padding:6px}.frame svg{width:100%;height:auto;display:block}.highlight{color:#0d887b;font-weight:800}.warn{color:#a45327;font-weight:780}.subhead{font-weight:800;font-size:.89rem;color:#42617a;text-transform:uppercase;letter-spacing:.055em;margin-bottom:8px}.reveal{animation:appear .3s ease-out}@keyframes appear{from{opacity:.25;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}\n@media(max-width:760px){.shell{width:min(100% - 18px,610px);margin:9px auto 28px}.hero{padding:19px;border-radius:16px}.layout{grid-template-columns:1fr;gap:11px;margin-top:11px}.card{padding:16px;border-radius:14px}.topline{flex-direction:column}.chip{align-self:flex-start}.inline-fields{grid-template-columns:1fr 1fr}.footer{padding:0 8px}.stat .value{font-size:1.25rem}}\n@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}\n</style></head><body><div class=\"shell\"><header class=\"hero\"><div class=\"topline\"><div><div class=\"kicker\">EXPLORA · UNIDAD I · ESTACIÓN 5</div><h1>Fracciones equivalentes</h1><p>Parte una barra en más trozos sin cambiar cuánto representa. Compara amplificar y simplificar.</p></div><span class=\"chip\">Toca, cambia y compara</span></div></header>\n<div class=\"layout\"><aside class=\"card\"><h2>1. Arma tu fracción</h2><div class=\"inline-fields\"><div class=\"field\"><label for=\"n\">Numerador</label><select id=\"n\"></select></div><div class=\"field\"><label for=\"d\">Denominador</label><select id=\"d\"></select></div></div><div class=\"section-gap\"></div><div class=\"pills\"><button class=\"btn minor sm\" data-frac=\"3/4\">3/4</button><button class=\"btn minor sm\" data-frac=\"6/8\">6/8</button><button class=\"btn minor sm\" data-frac=\"2/3\">2/3</button><button class=\"btn minor sm\" data-frac=\"9/12\">9/12</button></div><div class=\"section-gap\"></div><div class=\"subhead\">2. Prueba una transformación</div><div class=\"pills\"><button id=\"amplify\" class=\"btn active sm\">Amplificar</button><button id=\"reduce\" class=\"btn alt sm\">Simplificar</button></div><div class=\"section-gap\"></div><div id=\"ampControls\" class=\"field\"><label for=\"k\">Multiplicar por: <strong id=\"kLabel\">3</strong></label><input id=\"k\" type=\"range\" min=\"1\" max=\"6\" value=\"3\"/></div><div id=\"redControls\" style=\"display:none\"><label for=\"divisor\" class=\"small\" style=\"font-weight:700\">Divisor común</label><div class=\"section-gap\" style=\"height:6px\"></div><select id=\"divisor\" style=\"width:100%;padding:10px;border:1px solid var(--stroke);border-radius:10px\"></select><p class=\"small muted\" id=\"reduceNote\"></p></div>\n<div class=\"section-gap\"></div><button id=\"mistake\" class=\"btn minor\">¿Y si cambio solo abajo?</button><div class=\"section-gap\"></div><div class=\"note\">Amplificar o simplificar <strong>numerador y denominador por el mismo factor no nulo</strong> conserva la fracción.</div></aside>\n<main class=\"card\"><h2>3. Compara las cantidades</h2><div class=\"panel\"><div class=\"formula big formula-row\" id=\"equation\"></div></div><div class=\"section-gap\"></div><div class=\"controls\"><div><div class=\"subhead\">Barra original</div><div id=\"originalLabel\" class=\"small\" style=\"margin-bottom:7px\"></div><div id=\"barOriginal\"></div></div><div><div class=\"subhead\">Barra transformada</div><div id=\"newLabel\" class=\"small\" style=\"margin-bottom:7px\"></div><div id=\"barNew\"></div></div></div><div class=\"section-gap\"></div><div class=\"panel green\" aria-live=\"polite\" id=\"explanation\"></div><div id=\"wrongPanel\" style=\"display:none;margin-top:14px\" class=\"panel warm\"><div class=\"subhead\">Cambio incorrecto: solo denominador</div><div class=\"formula formula-row\" id=\"wrongEq\"></div><div class=\"section-gap\"></div><div id=\"wrongBar\"></div><p class=\"small\">Al cambiar solo el denominador, la parte sombreada es distinta. ¡No representa la misma cantidad!</p></div>\n</main></div><div class=\"footer\">Una actividad opcional de exploración: no afecta el avance ni guarda resultados.</div></div>\n<script>function $(id){return document.getElementById(id)}\nfunction clamp(v,a,b){return Math.min(b,Math.max(a,Number(v)||0))}\nfunction gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b]}return a}\nfunction lcm(a,b){return Math.abs(a*b)/gcd(a,b)}\nfunction fmt(n){return String(n).replace('-', '−')}\nfunction fraction(n,d){let s=n<0?'−':'';n=Math.abs(n);return `<span class=\"frac\"><span class=\"n\">${s}${n}</span><span class=\"d\">${d}</span></span>`}\nfunction fractionStr(n,d){return `${fmt(n)}/${d}`}\nfunction simplify(n,d){if(d<0){n=-n;d=-d}const g=gcd(n,d)||1;return [n/g,d/g]}\nfunction barMarkup(n,d,cls=''){let out='';for(let i=0;i<d;i++){out+=`<span class=\"segment ${i<n?'on '+cls:''}\" aria-hidden=\"true\"></span>`}return `<div class=\"bar\" role=\"img\" aria-label=\"${n} de ${d} partes sombreadas\">${out}</div>`}\nfunction options(el,values,selected){el.innerHTML=values.map(v=>`<option value=\"${v}\" ${String(v)===String(selected)?'selected':''}>${v}</option>`).join('')}\nfunction setText(id,val){$(id).textContent=val}\n</script><script>let state={n:3,d:4,k:3,mode:'amp',divisor:2,wrong:false};\nfunction validDivs(){let r=[];for(let c=2;c<=gcd(state.n,state.d);c++)if(state.n%c===0&&state.d%c===0)r.push(c);return r}\nfunction populate(){options($('d'),Array.from({length:11},(_,i)=>i+2),state.d);state.n=Math.min(state.n,state.d);options($('n'),Array.from({length:state.d},(_,i)=>i+1),state.n);$('k').value=state.k;setText('kLabel',state.k);let divs=validDivs();if(!divs.includes(state.divisor))state.divisor=divs[0]||1;options($('divisor'),divs.length?divs:[1],state.divisor);$('divisor').disabled=!divs.length;setText('reduceNote',divs.length?'Puedes dividir ambos términos por el mismo número.':'Esta fracción ya es irreducible: no hay divisor común mayor que 1.');$('ampControls').style.display=state.mode==='amp'?'grid':'none';$('redControls').style.display=state.mode==='reduce'?'block':'none';$('amplify').className='btn sm '+(state.mode==='amp'?'active':'alt');$('reduce').className='btn sm '+(state.mode==='reduce'?'active':'alt');$('mistake').textContent=state.wrong?'Ocultar comparación incorrecta':'¿Y si cambio solo abajo?'}\nfunction render(){populate();let {n,d,k,mode,divisor,wrong}=state;const divisors=validDivs();if(mode==='reduce'&&divisors.length===0){$('equation').innerHTML=`${fraction(n,d)} <span class=\"muted\">(irreducible)</span>`;$('barOriginal').innerHTML=barMarkup(n,d);$('barNew').innerHTML=barMarkup(n,d,'teal');setText('originalLabel',`${n} de ${d} partes`);setText('newLabel','No se puede simplificar más');$('explanation').innerHTML='<strong>Ya está simplificada.</strong> Solo tiene como divisor común positivo al 1.'; $('wrongPanel').style.display='none';return}\nlet N=mode==='amp'?n*k:n/divisor,D=mode==='amp'?d*k:d/divisor,factor=mode==='amp'?k:divisor,verb=mode==='amp'?'multiplicamos':'dividimos';$('equation').innerHTML=`${fraction(n,d)} <span style=\"color:var(--muted)\">=</span> ${fraction(N,D)}`;\n$('barOriginal').innerHTML=barMarkup(n,d);$('barNew').innerHTML=barMarkup(N,D,'teal');setText('originalLabel',`${n} partes de ${d}`);setText('newLabel',`${N} partes de ${D}`);\n$('explanation').innerHTML=`<strong>¡Misma cantidad!</strong> ${mode==='amp'?'La unidad está dividida en más partes, pero la zona sombreada no cambia.':'Ahora aparecen menos partes, cada una más grande, pero la cantidad sombreada sigue igual.'}<div class=\"formula formula-row\" style=\"margin-top:9px\">${mode==='amp'?`${fraction(n,d)} × ${fraction(factor,factor)} = ${fraction(N,D)}`:`<span class=\"frac\"><span class=\"n\">${n} ÷ ${factor}</span><span class=\"d\">${d} ÷ ${factor}</span></span> = ${fraction(N,D)}`}</div><p class=\"small\" style=\"margin-bottom:0\">${mode==='amp'?`Multiplicamos ambos términos por ${factor}.`:`Dividimos ambos términos por ${factor}.`} ${factor===1?'Observa que dividir o multiplicar por 1 no cambia la expresión.':''}</p>`;\n$('wrongPanel').style.display=wrong?'block':'none';if(wrong){let badK=mode==='amp'?Math.max(2,k):2,badD=d*badK;$('wrongEq').innerHTML=`${fraction(n,d)} <span style=\"color:var(--bad)\">≠</span> ${fraction(n,badD)}`;$('wrongBar').innerHTML=barMarkup(n,badD,'amber')}\n}\n$('d').addEventListener('change',e=>{state.d=Number(e.target.value);state.wrong=false;render()});$('n').addEventListener('change',e=>{state.n=Number(e.target.value);state.wrong=false;render()});$('k').addEventListener('input',e=>{state.k=Number(e.target.value);render()});$('divisor').addEventListener('change',e=>{state.divisor=Number(e.target.value);render()});$('amplify').addEventListener('click',()=>{state.mode='amp';render()});$('reduce').addEventListener('click',()=>{state.mode='reduce';render()});$('mistake').addEventListener('click',()=>{state.wrong=!state.wrong;render()});document.querySelectorAll('[data-frac]').forEach(b=>b.addEventListener('click',()=>{[state.n,state.d]=b.dataset.frac.split('/').map(Number);state.wrong=false;render()}));render();\n</script></body></html>"},"example3":"Ejemplo 3 · Amplificar una fracción\n1. $$\\dfrac25$$\n   Partimos de dos quintos.\n2. $$\\dfrac{2\\cdot3}{5\\cdot3}$$\n   Multiplicamos arriba y abajo por 3.\n3. $$\\dfrac25=\\dfrac6{15}$$\n   Es la misma cantidad expresada con más partes.","draw":5,"unit":0},{"id":"u1-s006","title":"Producto y división de fracciones","subtitle":"Simplificar antes de multiplicar; invertir al dividir","group":1,"symbol":"✧","minutes":35,"concept":"Multiplicar y dividir fracciones simplificando factores antes de calcular.\n\nProducto: multiplica numeradores entre sí y denominadores entre sí.\nAntes: reduce factores comunes entre cualquier numerador y cualquier denominador.\nDivisión: multiplica por el recíproco de la segunda fracción, siempre que sea distinta de cero.","example":"Calcula $\\frac{15}{28}\\cdot\\frac{14}{25}$.\n1. $$\\frac{15}{28}\\cdot\\frac{14}{25}$$ — Escribimos el producto.\n2. $$\\frac{3\\cdot5}{2\\cdot14}\\cdot\\frac{14}{5\\cdot5}$$ — Descomponemos para ver factores.\n3. $$\\frac3{2}\\cdot\\frac1{5}$$ — Cancelamos factores comunes.\n4. $$\\frac3{10}$$ — Multiplicamos.","media":[],"practice":[{"q":"Calcula $\\left(\\dfrac{1}{2}\\right)\\cdot\\left(\\dfrac{2}{3}\\right)$.","options":["$\\dfrac{3}{4}$","$\\dfrac{1}{3}$","$\\dfrac{4}{3}$","$-\\dfrac{2}{3}$"],"correct":1,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{1}{2}\\cdot\\dfrac{2}{3}=\\dfrac{1}{3}$.","level":1},{"q":"Calcula $\\left(\\dfrac{3}{4}\\right)\\cdot\\left(\\dfrac{2}{9}\\right)$.","options":["$\\dfrac{27}{8}$","$-\\dfrac{5}{6}$","$\\dfrac{7}{6}$","$\\dfrac{1}{6}$"],"correct":3,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{3}{4}\\cdot\\dfrac{2}{9}=\\dfrac{1}{6}$.","level":1},{"q":"Calcula $\\left(\\dfrac{5}{6}\\right)\\cdot\\left(\\dfrac{3}{10}\\right)$.","options":["$-\\dfrac{3}{4}$","$\\dfrac{5}{4}$","$\\dfrac{1}{4}$","$\\dfrac{25}{9}$"],"correct":2,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{5}{6}\\cdot\\dfrac{3}{10}=\\dfrac{1}{4}$.","level":1},{"q":"Calcula $\\left(\\dfrac{7}{12}\\right)\\cdot\\left(\\dfrac{6}{7}\\right)$.","options":["$-\\dfrac{1}{2}$","$\\dfrac{3}{2}$","$\\dfrac{1}{2}$","$\\dfrac{49}{72}$"],"correct":2,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{7}{12}\\cdot\\dfrac{6}{7}=\\dfrac{1}{2}$.","level":1},{"q":"Calcula $\\left(\\dfrac{4}{9}\\right)\\cdot\\left(\\dfrac{3}{8}\\right)$.","options":["$\\dfrac{1}{6}$","$\\dfrac{32}{27}$","$\\dfrac{7}{6}$","$-\\dfrac{5}{6}$"],"correct":0,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{4}{9}\\cdot\\dfrac{3}{8}=\\dfrac{1}{6}$.","level":1},{"q":"Calcula $\\left(\\dfrac{5}{14}\\right)\\cdot\\left(\\dfrac{7}{10}\\right)$.","options":["$\\dfrac{1}{4}$","$\\dfrac{25}{49}$","$-\\dfrac{3}{4}$","$\\dfrac{5}{4}$"],"correct":0,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{5}{14}\\cdot\\dfrac{7}{10}=\\dfrac{1}{4}$.","level":1},{"q":"Calcula $\\left(\\dfrac{9}{16}\\right)\\cdot\\left(\\dfrac{4}{15}\\right)$.","options":["$\\dfrac{23}{20}$","$-\\dfrac{17}{20}$","$\\dfrac{3}{20}$","$\\dfrac{135}{64}$"],"correct":2,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{9}{16}\\cdot\\dfrac{4}{15}=\\dfrac{3}{20}$.","level":1},{"q":"Calcula $\\left(\\dfrac{2}{5}\\right)\\cdot\\left(\\dfrac{15}{8}\\right)$.","options":["$\\dfrac{16}{75}$","$\\dfrac{7}{4}$","$-\\dfrac{1}{4}$","$\\dfrac{3}{4}$"],"correct":3,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{2}{5}\\cdot\\dfrac{15}{8}=\\dfrac{3}{4}$.","level":1},{"q":"Calcula $\\left(\\dfrac{3}{4}\\right)\\div\\left(\\dfrac{9}{8}\\right)$.","options":["$\\dfrac{5}{3}$","$\\dfrac{2}{3}$","$\\dfrac{27}{32}$","$-\\dfrac{1}{3}$"],"correct":1,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{3}{4}\\cdot\\dfrac{8}{9}=\\dfrac{2}{3}$.","level":2},{"q":"Calcula $\\left(\\dfrac{5}{6}\\right)\\div\\left(\\dfrac{10}{9}\\right)$.","options":["$-\\dfrac{1}{4}$","$\\dfrac{25}{27}$","$\\dfrac{7}{4}$","$\\dfrac{3}{4}$"],"correct":3,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{5}{6}\\cdot\\dfrac{9}{10}=\\dfrac{3}{4}$.","level":2},{"q":"Calcula $\\left(\\dfrac{7}{8}\\right)\\div\\left(\\dfrac{14}{15}\\right)$.","options":["$\\dfrac{15}{16}$","$\\dfrac{31}{16}$","$-\\dfrac{1}{16}$","$\\dfrac{49}{60}$"],"correct":0,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{7}{8}\\cdot\\dfrac{15}{14}=\\dfrac{15}{16}$.","level":2},{"q":"Calcula $\\left(\\dfrac{2}{3}\\right)\\div\\left(\\dfrac{4}{9}\\right)$.","options":["$\\dfrac{1}{2}$","$\\dfrac{8}{27}$","$\\dfrac{3}{2}$","$\\dfrac{5}{2}$"],"correct":2,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{2}{3}\\cdot\\dfrac{9}{4}=\\dfrac{3}{2}$.","level":2},{"q":"Calcula $\\left(\\dfrac{9}{10}\\right)\\div\\left(\\dfrac{3}{5}\\right)$.","options":["$\\dfrac{27}{50}$","$\\dfrac{5}{2}$","$\\dfrac{3}{2}$","$\\dfrac{1}{2}$"],"correct":2,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{9}{10}\\cdot\\dfrac{5}{3}=\\dfrac{3}{2}$.","level":2},{"q":"Calcula $\\left(\\dfrac{5}{12}\\right)\\div\\left(\\dfrac{25}{18}\\right)$.","options":["$\\dfrac{125}{216}$","$\\dfrac{13}{10}$","$\\dfrac{3}{10}$","$-\\dfrac{7}{10}$"],"correct":2,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{5}{12}\\cdot\\dfrac{18}{25}=\\dfrac{3}{10}$.","level":2},{"q":"Calcula $\\left(\\dfrac{4}{7}\\right)\\div\\left(\\dfrac{16}{21}\\right)$.","options":["$\\dfrac{3}{4}$","$\\dfrac{64}{147}$","$-\\dfrac{1}{4}$","$\\dfrac{7}{4}$"],"correct":0,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{4}{7}\\cdot\\dfrac{21}{16}=\\dfrac{3}{4}$.","level":2},{"q":"Calcula $\\left(\\dfrac{6}{11}\\right)\\div\\left(\\dfrac{15}{22}\\right)$.","options":["$-\\dfrac{1}{5}$","$\\dfrac{4}{5}$","$\\dfrac{9}{5}$","$\\dfrac{45}{121}$"],"correct":1,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{6}{11}\\cdot\\dfrac{22}{15}=\\dfrac{4}{5}$.","level":2},{"q":"Calcula $\\left(-\\dfrac{3}{5}\\right)\\cdot\\left(\\dfrac{9}{10}\\right)$.","options":["$-\\dfrac{27}{50}$","$-\\dfrac{77}{50}$","$-\\dfrac{2}{3}$","$\\dfrac{23}{50}$"],"correct":0,"why":"Multiplicamos, reduciendo factores comunes: $-\\dfrac{3}{5}\\cdot\\dfrac{9}{10}=-\\dfrac{27}{50}$.","level":3},{"q":"Calcula $\\left(\\dfrac{7}{9}\\right)\\cdot\\left(-\\dfrac{14}{15}\\right)$.","options":["$-\\dfrac{98}{135}$","$-\\dfrac{5}{6}$","$-\\dfrac{233}{135}$","$\\dfrac{37}{135}$"],"correct":0,"why":"Multiplicamos, reduciendo factores comunes: $\\dfrac{7}{9}\\cdot-\\dfrac{14}{15}=-\\dfrac{98}{135}$.","level":3},{"q":"Calcula $\\left(-\\dfrac{8}{15}\\right)\\cdot\\left(-\\dfrac{12}{35}\\right)$.","options":["$\\dfrac{14}{9}$","$\\dfrac{207}{175}$","$-\\dfrac{143}{175}$","$\\dfrac{32}{175}$"],"correct":3,"why":"Multiplicamos, reduciendo factores comunes: $-\\dfrac{8}{15}\\cdot-\\dfrac{12}{35}=\\dfrac{32}{175}$.","level":3},{"q":"Calcula $\\left(\\dfrac{13}{18}\\right)\\div\\left(\\dfrac{26}{27}\\right)$.","options":["$\\dfrac{3}{4}$","$-\\dfrac{1}{4}$","$\\dfrac{7}{4}$","$\\dfrac{169}{243}$"],"correct":0,"why":"Al dividir, invertimos la segunda fracción: $\\dfrac{13}{18}\\cdot\\dfrac{27}{26}=\\dfrac{3}{4}$.","level":3}],"check":{"q":"Una muestra pesa $\\dfrac{3}{4}$ g. ¿Cuánto pesan dos muestras iguales?","options":["$\\dfrac{3}{2}$ g","$\\dfrac{3}{8}$ g","$\\dfrac{5}{4}$ g"],"correct":0,"why":"$2\\cdot(3/4)=3/2$ g."},"learn":{"goal":"Multiplicar y dividir fracciones simplificando factores antes de calcular.","idea":"Producto: multiplica numeradores entre sí y denominadores entre sí.\nAntes: reduce factores comunes entre cualquier numerador y cualquier denominador.\nDivisión: multiplica por el recíproco de la segunda fracción, siempre que sea distinta de cero.","steps":{"title":"Calcula $\\frac{15}{28}\\cdot\\frac{14}{25}$.","items":[{"math":"\\frac{15}{28}\\cdot\\frac{14}{25}","why":"Escribimos el producto.","side":{"title":"Idea","text":"Buscamos factores comunes entre numeradores y denominadores."}},{"math":"\\frac{3\\cdot5}{2\\cdot14}\\cdot\\frac{14}{5\\cdot5}","why":"Descomponemos para ver factores.","side":{"title":"Factorización","text":"$15=3\\cdot5$, $28=2\\cdot14$, $25=5\\cdot5$."}},{"math":"\\frac3{2}\\cdot\\frac1{5}","why":"Cancelamos factores comunes.","side":{"title":"Simplificación","text":"Cancelamos un $14$ y un $5$, no sumandos."}},{"math":"\\frac3{10}","why":"Multiplicamos.","side":{"title":"Resultado","text":"$3\\cdot1=3$ y $2\\cdot5=10$."}}]},"warn":"Atención: solo se cancelan factores, nunca términos de una suma. Dividir por una fracción de numerador cero no está definido."},"example2":"Ejemplo 2 · División de fracciones\n1. $$\\dfrac34\\div\\dfrac98$$\n   Identificamos la fracción que divide.\n2. $$\\dfrac34\\cdot\\dfrac89$$\n   Invertimos SOLO la segunda.\n3. $$\\dfrac{3\\cdot8}{4\\cdot9}=\\dfrac23$$\n   Reducimos factores y multiplicamos.","example3":"Ejemplo 3 · Producto con signo\n1. $$-\\dfrac{10}{21}\\cdot\\dfrac7{15}$$\n   Conservamos el signo negativo.\n2. $$-\\dfrac{2}{3}\\cdot\\dfrac{1}{3}$$\n   Cancelamos 5, 7 y los demás factores comunes.\n3. $$-\\dfrac29$$\n   Multiplicamos los factores restantes.","draw":5,"unit":0},{"id":"u1-s007","title":"Suma y resta de fracciones","subtitle":"Denominador común mediante MCM","group":1,"symbol":"✧","minutes":50,"concept":"Sumar y restar fracciones con distintos denominadores utilizando el MCM.\n\nNecesitamos partes del mismo tamaño.\n1) Calcula el MCM de los denominadores.\n2) Escribe fracciones equivalentes con ese denominador.\n3) Suma o resta los numeradores y simplifica si corresponde.","example":"Calcula $\\frac16+\\frac14$.\n1. $$\\frac16+\\frac14$$ — Identificamos los denominadores.\n2. $$\\operatorname{mcm}(6,4)=12$$ — Encontramos el mínimo común múltiplo.\n3. $$\\frac2{12}+\\frac3{12}$$ — Construimos fracciones equivalentes.\n4. $$\\frac{2+3}{12}$$ — Sumamos numeradores.\n5. $$\\frac5{12}$$ — Expresamos el resultado.","media":[],"practice":[{"q":"Calcula $\\dfrac{1}{6}+\\left(\\dfrac{1}{4}\\right)$ usando el MCM.","options":["$-\\dfrac{7}{12}$","$-\\dfrac{5}{12}$","$\\dfrac{17}{12}$","$\\dfrac{5}{12}$"],"correct":3,"why":"El MCM de 6 y 4 es 12. Las fracciones equivalentes tienen numeradores 2 y 3. Sumamos. Resultado: $\\dfrac{5}{12}$.","level":1},{"q":"Calcula $\\dfrac{2}{3}-\\left(\\dfrac{1}{6}\\right)$ usando el MCM.","options":["$\\dfrac{1}{2}$","$\\dfrac{3}{2}$","$-\\dfrac{1}{2}$","$\\dfrac{5}{2}$"],"correct":0,"why":"El MCM de 3 y 6 es 6. Las fracciones equivalentes tienen numeradores 4 y 1. Restamos. Resultado: $\\dfrac{1}{2}$.","level":1},{"q":"Calcula $\\dfrac{3}{8}+\\left(\\dfrac{1}{4}\\right)$ usando el MCM.","options":["$\\dfrac{5}{8}$","$-\\dfrac{5}{8}$","$-\\dfrac{3}{8}$","$\\dfrac{13}{8}$"],"correct":0,"why":"El MCM de 8 y 4 es 8. Las fracciones equivalentes tienen numeradores 3 y 2. Sumamos. Resultado: $\\dfrac{5}{8}$.","level":1},{"q":"Calcula $\\dfrac{5}{12}+\\left(\\dfrac{7}{18}\\right)$ usando el MCM.","options":["$\\dfrac{65}{36}$","$-\\dfrac{7}{36}$","$-\\dfrac{29}{36}$","$\\dfrac{29}{36}$"],"correct":3,"why":"El MCM de 12 y 18 es 36. Las fracciones equivalentes tienen numeradores 15 y 14. Sumamos. Resultado: $\\dfrac{29}{36}$.","level":1},{"q":"Calcula $\\dfrac{7}{10}-\\left(\\dfrac{1}{5}\\right)$ usando el MCM.","options":["$-\\dfrac{1}{2}$","$\\dfrac{3}{2}$","$\\dfrac{5}{2}$","$\\dfrac{1}{2}$"],"correct":3,"why":"El MCM de 10 y 5 es 10. Las fracciones equivalentes tienen numeradores 7 y 2. Restamos. Resultado: $\\dfrac{1}{2}$.","level":1},{"q":"Calcula $\\dfrac{4}{9}+\\left(\\dfrac{1}{6}\\right)$ usando el MCM.","options":["$\\dfrac{29}{18}$","$\\dfrac{11}{18}$","$-\\dfrac{7}{18}$","$-\\dfrac{11}{18}$"],"correct":1,"why":"El MCM de 9 y 6 es 18. Las fracciones equivalentes tienen numeradores 8 y 3. Sumamos. Resultado: $\\dfrac{11}{18}$.","level":1},{"q":"Calcula $\\dfrac{1}{3}+\\left(\\dfrac{3}{8}\\right)$ usando el MCM.","options":["$-\\dfrac{7}{24}$","$\\dfrac{41}{24}$","$\\dfrac{17}{24}$","$-\\dfrac{17}{24}$"],"correct":2,"why":"El MCM de 3 y 8 es 24. Las fracciones equivalentes tienen numeradores 8 y 9. Sumamos. Resultado: $\\dfrac{17}{24}$.","level":1},{"q":"Calcula $\\dfrac{5}{6}-\\left(\\dfrac{1}{9}\\right)$ usando el MCM.","options":["$\\dfrac{31}{18}$","$-\\dfrac{5}{18}$","$\\dfrac{13}{18}$","$-\\dfrac{13}{18}$"],"correct":2,"why":"El MCM de 6 y 9 es 18. Las fracciones equivalentes tienen numeradores 15 y 2. Restamos. Resultado: $\\dfrac{13}{18}$.","level":1},{"q":"Calcula $\\dfrac{7}{12}+\\left(\\dfrac{5}{18}\\right)$ usando el MCM.","options":["$\\dfrac{67}{36}$","$\\dfrac{31}{36}$","$-\\dfrac{31}{36}$","$-\\dfrac{5}{36}$"],"correct":1,"why":"El MCM de 12 y 18 es 36. Las fracciones equivalentes tienen numeradores 21 y 10. Sumamos. Resultado: $\\dfrac{31}{36}$.","level":2},{"q":"Calcula $\\dfrac{5}{8}+\\left(\\dfrac{7}{20}\\right)$ usando el MCM.","options":["$-\\dfrac{39}{40}$","$\\dfrac{39}{40}$","$\\dfrac{79}{40}$","$-\\dfrac{1}{40}$"],"correct":1,"why":"El MCM de 8 y 20 es 40. Las fracciones equivalentes tienen numeradores 25 y 14. Sumamos. Resultado: $\\dfrac{39}{40}$.","level":2},{"q":"Calcula $\\dfrac{11}{15}-\\left(\\dfrac{2}{9}\\right)$ usando el MCM.","options":["$\\dfrac{23}{45}$","$-\\dfrac{23}{45}$","$-\\dfrac{22}{45}$","$\\dfrac{68}{45}$"],"correct":0,"why":"El MCM de 15 y 9 es 45. Las fracciones equivalentes tienen numeradores 33 y 10. Restamos. Resultado: $\\dfrac{23}{45}$.","level":2},{"q":"Calcula $\\dfrac{13}{24}+\\left(\\dfrac{5}{16}\\right)$ usando el MCM.","options":["$\\dfrac{89}{48}$","$-\\dfrac{41}{48}$","$-\\dfrac{7}{48}$","$\\dfrac{41}{48}$"],"correct":3,"why":"El MCM de 24 y 16 es 48. Las fracciones equivalentes tienen numeradores 26 y 15. Sumamos. Resultado: $\\dfrac{41}{48}$.","level":2},{"q":"Calcula $\\dfrac{7}{18}+\\left(\\dfrac{11}{30}\\right)$ usando el MCM.","options":["$\\dfrac{34}{45}$","$-\\dfrac{11}{45}$","$-\\dfrac{34}{45}$","$\\dfrac{79}{45}$"],"correct":0,"why":"El MCM de 18 y 30 es 90. Las fracciones equivalentes tienen numeradores 35 y 33. Sumamos. Resultado: $\\dfrac{34}{45}$.","level":2},{"q":"Calcula $\\dfrac{3}{14}-\\left(\\dfrac{5}{21}\\right)$ usando el MCM.","options":["$-\\dfrac{43}{42}$","$\\dfrac{1}{42}$","$\\dfrac{41}{42}$","$-\\dfrac{1}{42}$"],"correct":3,"why":"El MCM de 14 y 21 es 42. Las fracciones equivalentes tienen numeradores 9 y 10. Restamos. Resultado: $-\\dfrac{1}{42}$.","level":2},{"q":"Calcula $\\dfrac{11}{12}+\\left(\\dfrac{7}{15}\\right)$ usando el MCM.","options":["$\\dfrac{143}{60}$","$\\dfrac{83}{60}$","$-\\dfrac{83}{60}$","$\\dfrac{23}{60}$"],"correct":1,"why":"El MCM de 12 y 15 es 60. Las fracciones equivalentes tienen numeradores 55 y 28. Sumamos. Resultado: $\\dfrac{83}{60}$.","level":2},{"q":"Calcula $\\dfrac{9}{20}+\\left(\\dfrac{3}{8}\\right)$ usando el MCM.","options":["$-\\dfrac{33}{40}$","$\\dfrac{33}{40}$","$\\dfrac{73}{40}$","$-\\dfrac{7}{40}$"],"correct":1,"why":"El MCM de 20 y 8 es 40. Las fracciones equivalentes tienen numeradores 18 y 15. Sumamos. Resultado: $\\dfrac{33}{40}$.","level":2},{"q":"Calcula $-\\dfrac{2}{9}-\\left(\\dfrac{7}{12}\\right)$ usando el MCM.","options":["$-\\dfrac{65}{36}$","$\\dfrac{29}{36}$","$\\dfrac{7}{36}$","$-\\dfrac{29}{36}$"],"correct":3,"why":"El MCM de 9 y 12 es 36. Las fracciones equivalentes tienen numeradores -8 y 21. Restamos. Resultado: $-\\dfrac{29}{36}$.","level":3},{"q":"Calcula $-\\dfrac{5}{18}+\\left(-\\dfrac{1}{6}\\right)$ usando el MCM.","options":["$-\\dfrac{4}{9}$","$\\dfrac{5}{9}$","$\\dfrac{4}{9}$","$-\\dfrac{13}{9}$"],"correct":0,"why":"El MCM de 18 y 6 es 18. Las fracciones equivalentes tienen numeradores -5 y -3. Sumamos. Resultado: $-\\dfrac{4}{9}$.","level":3},{"q":"Calcula $\\dfrac{13}{28}+\\left(\\dfrac{17}{42}\\right)$ usando el MCM.","options":["$\\dfrac{73}{84}$","$\\dfrac{157}{84}$","$-\\dfrac{73}{84}$","$-\\dfrac{11}{84}$"],"correct":0,"why":"El MCM de 28 y 42 es 84. Las fracciones equivalentes tienen numeradores 39 y 34. Sumamos. Resultado: $\\dfrac{73}{84}$.","level":3},{"q":"Calcula $-\\dfrac{7}{15}-\\left(\\dfrac{11}{18}\\right)$ usando el MCM.","options":["$\\dfrac{97}{90}$","$-\\dfrac{7}{90}$","$-\\dfrac{187}{90}$","$-\\dfrac{97}{90}$"],"correct":3,"why":"El MCM de 15 y 18 es 90. Las fracciones equivalentes tienen numeradores -42 y 55. Restamos. Resultado: $-\\dfrac{97}{90}$.","level":3}],"check":{"q":"Se mezclan $\\dfrac{1}{4}$ L y $\\dfrac{1}{2}$ L de agua. ¿Cuál es el volumen total?","options":["$\\dfrac{3}{4}$ L","$\\dfrac{2}{6}$ L","$\\dfrac{1}{8}$ L"],"correct":0,"why":"$1/4+2/4=3/4$ L."},"learn":{"goal":"Sumar y restar fracciones con distintos denominadores utilizando el MCM.","idea":"Necesitamos partes del mismo tamaño.\n1) Calcula el MCM de los denominadores.\n2) Escribe fracciones equivalentes con ese denominador.\n3) Suma o resta los numeradores y simplifica si corresponde.","steps":{"title":"Calcula $\\frac16+\\frac14$.","items":[{"math":"\\frac16+\\frac14","why":"Identificamos los denominadores.","side":{"title":"Denominador común","text":"No se suman directamente partes de tamaños distintos."}},{"math":"\\operatorname{mcm}(6,4)=12","why":"Encontramos el mínimo común múltiplo.","side":{"title":"Factorización","math":"\\begin{aligned}6&=2\\cdot3\\\\4&=2^2\\\\\\mathrm{mcm}&=2^2\\cdot3=12\\end{aligned}"}},{"math":"\\frac2{12}+\\frac3{12}","why":"Construimos fracciones equivalentes.","side":{"title":"Amplificación","text":"$1/6$ se amplifica por $2$; $1/4$, por $3$."}},{"math":"\\frac{2+3}{12}","why":"Sumamos numeradores.","side":{"title":"Misma unidad","text":"Ahora ambas fracciones están expresadas en doceavos."}},{"math":"\\frac5{12}","why":"Expresamos el resultado.","side":{"title":"Comprobación","text":"La fracción es irreducible."}}]},"warn":"Atención: $\\frac12+\\frac13\\ne\\frac25$. El producto de denominadores también es común, pero usar MCM suele evitar números innecesariamente grandes."},"example2":"Ejemplo 2 · MCM frente a producto directo\n1. $$\\dfrac5{12}+\\dfrac7{18}$$\n   Los denominadores son distintos.\n2. $$\\mathrm{MCM}(12,18)=36$$\n   Elegimos el menor denominador común.\n3. $$\\dfrac{15}{36}+\\dfrac{14}{36}$$\n   Construimos equivalentes.\n4. $$\\dfrac{29}{36}$$\n   Sumamos los numeradores.","example3":"Ejemplo 3 · Resta de fracciones\n1. $$\\dfrac34-\\dfrac16$$\n   El MCM de 4 y 6 es 12.\n2. $$\\dfrac9{12}-\\dfrac2{12}$$\n   Amplificamos ambas fracciones.\n3. $$\\dfrac7{12}$$\n   Restamos numeradores.","explore":{"title":"Laboratorio de fracciones","desc":"Explora la suma y resta de fracciones usando denominadores comunes y MCM.","instr":"Prueba distintas fracciones y compara los resultados de ambos métodos.","alt":"Laboratorio de fracciones · actividad interactiva opcional, sin porcentaje de avance.","height":850,"html":"<!DOCTYPE html>\n<html lang=\"es\"><head><meta charset=\"UTF-8\"/><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"/><meta name=\"color-scheme\" content=\"light\"/><title>Explora · Laboratorio de fracciones · PACE UACh</title><style>:root{--bg:#f3f7fb;--paper:#fff;--ink:#1a3044;--muted:#607588;--stroke:#dce6ed;--main:#2575ac;--main2:#0b9a83;--mist:#e9f4f9;--warm:#fff6e5;--gold:#aa731d;--ok:#137d64;--bad:#a04a3c;--shadow:0 16px 36px rgba(30,62,86,.07)}\n*{box-sizing:border-box}html{font-size:16px}body{margin:0;background:radial-gradient(circle at 90% 0%,#e1f3f7 0%,transparent 32%),var(--bg);font-family:system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif;color:var(--ink);line-height:1.5}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f3bd59;outline-offset:2px}button:disabled{cursor:not-allowed;opacity:.45}\n.shell{width:min(1060px,calc(100% - 32px));margin:26px auto 42px}.hero{padding:25px 27px 24px;color:white;border-radius:22px;background:linear-gradient(119deg,#12476f 0%,#1b7d9f 57%,#138d83 100%);box-shadow:var(--shadow);position:relative;overflow:hidden}.hero:before,.hero:after{content:\"\";position:absolute;border:2px solid #ffffff20;border-radius:50%;width:270px;height:270px;right:-95px;top:-175px}.hero:after{width:180px;height:180px;right:35px;top:-120px}.kicker{text-transform:uppercase;font-size:.77rem;letter-spacing:.14em;font-weight:750;opacity:.88}.hero h1{font-size:clamp(1.48rem,3.6vw,2.15rem);margin:7px 0 5px;line-height:1.17;letter-spacing:-.03em}.hero p{margin:0;max-width:700px;color:#ebf9ff;line-height:1.5}.topline{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.chip{display:inline-flex;border-radius:999px;padding:6px 11px;background:#ffffff2b;font-weight:650;font-size:.79rem;white-space:nowrap;z-index:1}.layout{display:grid;grid-template-columns:335px minmax(0,1fr);align-items:start;gap:16px;margin-top:16px}.card{background:var(--paper);border:1px solid var(--stroke);border-radius:18px;padding:20px;box-shadow:var(--shadow);min-width:0}.card h2,.card h3{margin:0 0 12px;letter-spacing:-.02em}.card h2{font-size:1.14rem}.card h3{font-size:1.02rem}.lede{font-size:.96rem;color:var(--muted);margin:0 0 13px}.muted{color:var(--muted)}.small{font-size:.85rem}.tiny{font-size:.75rem}.controls{display:grid;gap:12px}.field{display:grid;gap:5px}.field label{font-size:.87rem;font-weight:700;color:#344f65}.field select,.field input[type=number]{width:100%;min-height:43px;border:1px solid #cddce7;background:#fff;border-radius:10px;padding:8px 11px;color:var(--ink)}.field input[type=range]{width:100%;accent-color:var(--main2);cursor:pointer}.inline-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pills{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--main);background:var(--main);color:white;font-weight:720;min-height:42px;border-radius:11px;padding:8px 14px;transition:transform .15s,filter .15s}.btn:hover:not(:disabled){filter:brightness(1.06);transform:translateY(-1px)}.btn.alt{background:#f1f7fb;color:#235e82;border-color:#bcd5e4}.btn.minor{border-color:#d4e1e9;background:white;color:#3b5d75}.btn.green{background:#0e8f78;border-color:#0e8f78}.btn.active{background:#155d89;color:white;border-color:#155d89}.btn.sm{font-size:.85rem;min-height:36px;padding:6px 10px}.btnrow{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.panel{border-radius:14px;background:#f5fafc;border:1px solid #dfecf2;padding:15px}.panel.warm{background:var(--warm);border-color:#f1e2c4}.panel.green{background:#eaf8f3;border-color:#c9e9dd}.panel p:last-child{margin-bottom:0}.panel p:first-child{margin-top:0}.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat{background:#f1f8fb;border:1px solid #ddebf1;border-radius:13px;padding:12px}.stat .value{font-size:1.45rem;font-weight:800;color:#1a6289;line-height:1.25}.stat .label{font-size:.78rem;color:var(--muted)}.formula{font-family:Georgia,\"Times New Roman\",serif;font-size:clamp(1.25rem,3.5vw,1.8rem);font-weight:650;line-height:1.5;text-align:center;word-break:normal}.formula.big{font-size:clamp(1.6rem,4.5vw,2.4rem)}.formula-row{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}.frac{display:inline-flex;flex-direction:column;vertical-align:middle;text-align:center;line-height:1.07;padding:0 2px;font-variant-numeric:tabular-nums}.frac>.n{display:block;border-bottom:1.7px solid currentColor;padding:0 5px 3px}.frac>.d{display:block;padding:3px 5px 0}.stepper{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-top:14px}.stepbadge{font-size:.8rem;font-weight:700;color:#587186}.bar{display:flex;overflow:hidden;border:1px solid #96b0c3;height:32px;border-radius:7px;background:#eef3f5}.segment{flex:1;border-right:1px solid #ffffff90;min-width:0;background:#edf3f7}.segment:last-child{border-right:0}.segment.on{background:#248ac4}.segment.on.teal{background:#28a88b}.segment.on.amber{background:#e4a145}.section-gap{height:16px}.note{border-left:4px solid #d9a03f;background:#fff8e9;padding:11px 13px;border-radius:8px;font-size:.9rem;color:#6b5127}.footer{margin-top:16px;color:#657b8d;font-size:.8rem;text-align:center}.frame{border:1px solid #d8e6ec;background:#f9fcfd;border-radius:13px;overflow:hidden;padding:6px}.frame svg{width:100%;height:auto;display:block}.highlight{color:#0d887b;font-weight:800}.warn{color:#a45327;font-weight:780}.subhead{font-weight:800;font-size:.89rem;color:#42617a;text-transform:uppercase;letter-spacing:.055em;margin-bottom:8px}.reveal{animation:appear .3s ease-out}@keyframes appear{from{opacity:.25;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}\n@media(max-width:760px){.shell{width:min(100% - 18px,610px);margin:9px auto 28px}.hero{padding:19px;border-radius:16px}.layout{grid-template-columns:1fr;gap:11px;margin-top:11px}.card{padding:16px;border-radius:14px}.topline{flex-direction:column}.chip{align-self:flex-start}.inline-fields{grid-template-columns:1fr 1fr}.footer{padding:0 8px}.stat .value{font-size:1.25rem}}\n@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}\n</style></head><body><div class=\"shell\">\n<header class=\"hero\"><div class=\"topline\"><div><div class=\"kicker\">EXPLORA · UNIDAD I · ESTACIÓN 7</div><h1>Laboratorio de fracciones</h1><p>Prueba sumas y restas. Descubre por qué un denominador común pequeño facilita los cálculos.</p></div><span class=\"chip\">Sin notas ni puntajes</span></div></header>\n<div class=\"layout\">\n<aside class=\"card\"><h2>1. Elige dos fracciones</h2><p class=\"lede\">Puedes cambiar cualquier número y comenzar de nuevo.</p>\n<div class=\"controls\">\n  <div class=\"inline-fields\"><div class=\"field\"><label for=\"n1\">Numerador A</label><select id=\"n1\"></select></div><div class=\"field\"><label for=\"d1\">Denominador A</label><select id=\"d1\"></select></div></div>\n  <div class=\"field\"><label for=\"op\">Operación</label><select id=\"op\"><option value=\"+\">Sumar (+)</option><option value=\"-\">Restar (−)</option></select></div>\n  <div class=\"inline-fields\"><div class=\"field\"><label for=\"n2\">Numerador B</label><select id=\"n2\"></select></div><div class=\"field\"><label for=\"d2\">Denominador B</label><select id=\"d2\"></select></div></div>\n  <div class=\"subhead\">Prueba un ejemplo</div>\n  <div class=\"pills\"><button class=\"btn minor sm\" data-eg=\"0\">1/6 + 1/4</button><button class=\"btn minor sm\" data-eg=\"1\">5/12 + 7/18</button><button class=\"btn minor sm\" data-eg=\"2\">3/4 − 1/6</button></div>\n  <div class=\"note\"><strong>Investiga:</strong> el MCM es el menor denominador positivo que sirve para ambas fracciones. No siempre coincide con el producto de los denominadores.</div>\n</div></aside>\n<main class=\"card\"><h2>2. Observa las partes</h2><div class=\"panel\"><div class=\"formula big formula-row\" id=\"expression\"></div></div>\n<div class=\"section-gap\"></div>\n<div class=\"subhead\">Así se ve cada cantidad</div><div id=\"originalBars\" class=\"controls\"></div>\n<div class=\"section-gap\"></div>\n<div class=\"panel green\" id=\"resultPanel\" aria-live=\"polite\"><div class=\"subhead\" id=\"stageName\">¿Qué notas?</div><div id=\"stageContent\"></div></div>\n<div class=\"stepper\"><button id=\"back\" class=\"btn alt\">← Anterior</button><span class=\"stepbadge\" id=\"stepBadge\">1 de 4</span><button id=\"next\" class=\"btn\">Siguiente →</button></div>\n<div class=\"section-gap\"></div><div class=\"stats\"><div class=\"stat\"><div class=\"label\">Denominador por producto</div><div class=\"value\" id=\"prod\">24</div></div><div class=\"stat\"><div class=\"label\">Denominador mínimo común</div><div class=\"value\" id=\"least\">12</div></div></div>\n</main></div><div class=\"footer\">Puedes explorar libremente. Esta actividad no guarda resultados ni modifica tu avance en el curso.</div>\n</div>\n<script>function $(id){return document.getElementById(id)}\nfunction clamp(v,a,b){return Math.min(b,Math.max(a,Number(v)||0))}\nfunction gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b]}return a}\nfunction lcm(a,b){return Math.abs(a*b)/gcd(a,b)}\nfunction fmt(n){return String(n).replace('-', '−')}\nfunction fraction(n,d){let s=n<0?'−':'';n=Math.abs(n);return `<span class=\"frac\"><span class=\"n\">${s}${n}</span><span class=\"d\">${d}</span></span>`}\nfunction fractionStr(n,d){return `${fmt(n)}/${d}`}\nfunction simplify(n,d){if(d<0){n=-n;d=-d}const g=gcd(n,d)||1;return [n/g,d/g]}\nfunction barMarkup(n,d,cls=''){let out='';for(let i=0;i<d;i++){out+=`<span class=\"segment ${i<n?'on '+cls:''}\" aria-hidden=\"true\"></span>`}return `<div class=\"bar\" role=\"img\" aria-label=\"${n} de ${d} partes sombreadas\">${out}</div>`}\nfunction options(el,values,selected){el.innerHTML=values.map(v=>`<option value=\"${v}\" ${String(v)===String(selected)?'selected':''}>${v}</option>`).join('')}\nfunction setText(id,val){$(id).textContent=val}\n</script><script>let st={n1:1,d1:6,n2:1,d2:4,op:'+',step:0};\nconst examples=[[1,6,1,4,'+'],[5,12,7,18,'+'],[3,4,1,6,'-']];\nfunction populate(){for(let side of [1,2]){const d=st['d'+side],n=Math.min(st['n'+side],d);st['n'+side]=n;options($('d'+side),Array.from({length:11},(_,i)=>i+2),d);options($('n'+side),Array.from({length:d},(_,i)=>i+1),n)}$('op').value=st.op}\nfunction strip(n,d,color,title){return `<div><div class=\"small\" style=\"font-weight:700;margin-bottom:6px\">${title}: ${fraction(n,d)}</div>${barMarkup(n,d,color)}</div>`}\nfunction render(){populate();const {n1,d1,n2,d2,op,step}=st,L=lcm(d1,d2),p=d1*d2,a=n1*(L/d1),b=n2*(L/d2),ans=op==='+'?a+b:a-b,[sn,sd]=simplify(ans,L);\n$('expression').innerHTML=`${fraction(n1,d1)} <span style=\"color:var(--muted)\">${op==='+'?'+':'−'}</span> ${fraction(n2,d2)}`;\n$('originalBars').innerHTML=strip(n1,d1,'','Fracción A')+strip(n2,d2,'teal','Fracción B');\nsetText('prod',p);setText('least',L);setText('stepBadge',`${step+1} de 4`);$('back').disabled=step===0;$('next').textContent=step===3?'Reiniciar ↺':'Siguiente →';\nconst title=['Mira los tamaños','Busca un denominador común','Convierte sin cambiar el valor','Ahora sí, opera'][step];setText('stageName',title);\nlet html='';if(step===0){html='<p>Las barras representan unidades del <strong>mismo tamaño</strong>, pero están divididas en partes distintas. Para sumar o restar, necesitamos partes iguales.</p>'}\nif(step===1){let multiples=(d)=>Array.from({length:Math.ceil(L/d)},(_,i)=>d*(i+1)).slice(0,9).join(', ');html=`<div class=\"formula\">mcm(${d1}, ${d2}) = <span class=\"highlight\">${L}</span></div><p class=\"small\">Múltiplos de ${d1}: ${multiples(d1)}${L/d1>9?', …':''}<br>Múltiplos de ${d2}: ${multiples(d2)}${L/d2>9?', …':''}</p><p class=\"small\">El producto ${d1} × ${d2} = ${p} también sirve, pero ${p===L?'en este caso ya es el menor.':`el MCM usa ${p/L} veces menos partes.`}</p>`}\nif(step===2){html=`<div class=\"formula formula-row\">${fraction(n1,d1)} = ${fraction(a,L)} <span style=\"font-size:1rem;color:var(--muted)\">y</span> ${fraction(n2,d2)} = ${fraction(b,L)}</div><p class=\"small\">Amplificamos la primera por ${L/d1} y la segunda por ${L/d2}; numerador y denominador se multiplican por el mismo factor.</p><div class=\"controls\">${strip(a,L,'','Primera expresada en '+L+'-avos')}${strip(b,L,'teal','Segunda expresada en '+L+'-avos')}</div>`}\nif(step===3){let sign=op==='+'?'+':'−';html=`<div class=\"formula formula-row\">${fraction(a,L)} ${sign} ${fraction(b,L)} = ${fraction(ans,L)} ${sn!==ans||sd!==L?'= '+fraction(sn,sd):''}</div><p class=\"small\">Con el denominador común, ${op==='+'?'sumamos':'restamos'} los numeradores. ${sn!==ans||sd!==L?'Finalmente simplificamos.':'El resultado ya está simplificado.'}</p>${sn<0?'<p class=\"small\">El resultado es negativo: sustraemos una cantidad mayor de otra menor.</p>':''}`}\n$('stageContent').innerHTML=`<div class=\"reveal\">${html}</div>`}\nfor(let side of [1,2]){for(let kind of ['n','d']){$(kind+side).addEventListener('change',e=>{st[kind+side]=Number(e.target.value);st.step=0;render()})}}\n$('op').addEventListener('change',e=>{st.op=e.target.value;st.step=0;render()});\n$('back').addEventListener('click',()=>{st.step=Math.max(0,st.step-1);render()});$('next').addEventListener('click',()=>{st.step=(st.step+1)%4;render()});\ndocument.querySelectorAll('[data-eg]').forEach(b=>b.addEventListener('click',()=>{let e=examples[Number(b.dataset.eg)];[st.n1,st.d1,st.n2,st.d2,st.op]=e;st.step=0;render()}));render();\n</script></body></html>"},"draw":5,"unit":0},{"id":"u1-s008","title":"Potencias enteras","subtitle":"Propiedades y exponentes negativos","group":2,"symbol":"✧","minutes":45,"concept":"Interpretar y calcular potencias con exponente entero, considerando signos y condiciones.\n\nPotencia natural: $a^n$ repite $n$ factores iguales a $a$.\nExponente cero: $a^0=1$ si $a\\ne0$.\nExponente negativo: $a^{-n}=1/a^n$ si $a\\ne0$.\nAl multiplicar potencias de igual base se suman exponentes.","example":"Calcula $2^{-3}$.\n1. $$2^{-3}$$ — Reconocemos el exponente negativo.\n2. $$2^{-3}=\\frac1{2^3}$$ — Aplicamos la definición.\n3. $$2^{-3}=\\frac1{2\\cdot2\\cdot2}$$ — Desarrollamos la potencia.\n4. $$2^{-3}=\\frac18$$ — Calculamos.","media":[],"practice":[{"q":"Calcula $2^{3}$.","options":["$9$","$-8$","$8$","$7$"],"correct":2,"why":"Desarrollamos la potencia respetando los paréntesis. Resultado: $8$.","level":1},{"q":"Calcula $\\left(-2\\right)^{2}$.","options":["$5$","$-4$","$4$","$3$"],"correct":2,"why":"Desarrollamos la potencia respetando los paréntesis. Resultado: $4$.","level":1},{"q":"Calcula $\\left(-3\\right)^{3}$.","options":["$-26$","$-27$","$-28$","$27$"],"correct":1,"why":"Desarrollamos la potencia respetando los paréntesis. Resultado: $-27$.","level":1},{"q":"Calcula $5^{0}$.","options":["$2$","$-1$","$1$","$0$"],"correct":2,"why":"Cualquier base no nula elevada a cero es 1. Resultado: $1$.","level":1},{"q":"Calcula $3^{2}$.","options":["$-9$","$8$","$9$","$10$"],"correct":2,"why":"Desarrollamos la potencia respetando los paréntesis. Resultado: $9$.","level":1},{"q":"Calcula $\\left(-1\\right)^{7}$.","options":["$0$","$1$","$-1$","$-2$"],"correct":2,"why":"Desarrollamos la potencia respetando los paréntesis. Resultado: $-1$.","level":1},{"q":"Calcula $10^{2}$.","options":["$101$","$-100$","$99$","$100$"],"correct":3,"why":"Desarrollamos la potencia respetando los paréntesis. Resultado: $100$.","level":1},{"q":"Calcula $-4^{2}$.","options":["$-15$","$16$","$-17$","$-16$"],"correct":3,"why":"El signo negativo está fuera de la potencia. Resultado: $-16$.","level":1},{"q":"Calcula $2^{-3}$.","options":["$\\dfrac{1}{8}$","$-\\dfrac{7}{8}$","$\\dfrac{9}{8}$","$-\\dfrac{1}{8}$"],"correct":0,"why":"El exponente negativo indica el inverso de la potencia positiva. Resultado: $\\dfrac{1}{8}$.","level":2},{"q":"Calcula $3^{-2}$.","options":["$\\dfrac{1}{9}$","$\\dfrac{10}{9}$","$-\\dfrac{1}{9}$","$-\\dfrac{8}{9}$"],"correct":0,"why":"El exponente negativo indica el inverso de la potencia positiva. Resultado: $\\dfrac{1}{9}$.","level":2},{"q":"Calcula $\\left(-2\\right)^{-2}$.","options":["$\\dfrac{5}{4}$","$-\\dfrac{3}{4}$","$\\dfrac{1}{4}$","$-\\dfrac{1}{4}$"],"correct":2,"why":"El exponente negativo indica el inverso de la potencia positiva. Resultado: $\\dfrac{1}{4}$.","level":2},{"q":"Calcula $5^{-1}$.","options":["$-\\dfrac{1}{5}$","$\\dfrac{6}{5}$","$\\dfrac{1}{5}$","$-\\dfrac{4}{5}$"],"correct":2,"why":"El exponente negativo indica el inverso de la potencia positiva. Resultado: $\\dfrac{1}{5}$.","level":2},{"q":"Calcula $2^{3}\\cdot2^{2}$.","options":["$33$","$-32$","$31$","$32$"],"correct":3,"why":"Con la misma base, sumamos exponentes: 3+2=5. Resultado: $32$.","level":2},{"q":"Calcula $3^{2}\\cdot3^{3}$.","options":["$243$","$244$","$-243$","$242$"],"correct":0,"why":"Con la misma base, sumamos exponentes: 2+3=5. Resultado: $243$.","level":2},{"q":"Calcula $2^{5}\\div2^{2}$.","options":["$-8$","$9$","$7$","$8$"],"correct":3,"why":"Con la misma base, restamos exponentes: 5-2=3. Resultado: $8$.","level":2},{"q":"Calcula $5^{3}\\div5^{1}$.","options":["$-25$","$26$","$25$","$24$"],"correct":2,"why":"Con la misma base, restamos exponentes: 3-1=2. Resultado: $25$.","level":2},{"q":"Calcula $-2^{3}$.","options":["$-8$","$8$","$-9$","$-7$"],"correct":0,"why":"El signo negativo está fuera de la potencia. Resultado: $-8$.","level":3},{"q":"Calcula $-3^{2}$.","options":["$-8$","$-10$","$-9$","$9$"],"correct":2,"why":"El signo negativo está fuera de la potencia. Resultado: $-9$.","level":3},{"q":"Calcula $\\left(-2\\right)^{-3}$.","options":["$-\\dfrac{1}{8}$","$-\\dfrac{9}{8}$","$\\dfrac{7}{8}$","$\\dfrac{1}{8}$"],"correct":0,"why":"El exponente negativo indica el inverso de la potencia positiva. Resultado: $-\\dfrac{1}{8}$.","level":3},{"q":"Calcula $\\left(-\\dfrac{3}{2}\\right)^{2}$.","options":["$\\dfrac{9}{4}$","$-\\dfrac{9}{4}$","$\\dfrac{5}{4}$","$\\dfrac{13}{4}$"],"correct":0,"why":"Desarrollamos la potencia respetando los paréntesis. Resultado: $\\dfrac{9}{4}$.","level":3}],"check":{"q":"Una población bacteriana se duplica dos veces desde $5$ unidades. ¿Cuántas unidades hay?","options":["$20$","$10$","$25$"],"correct":0,"why":"$5\\cdot2^2=20$."},"learn":{"goal":"Interpretar y calcular potencias con exponente entero, considerando signos y condiciones.","idea":"Potencia natural: $a^n$ repite $n$ factores iguales a $a$.\nExponente cero: $a^0=1$ si $a\\ne0$.\nExponente negativo: $a^{-n}=1/a^n$ si $a\\ne0$.\nAl multiplicar potencias de igual base se suman exponentes.","steps":{"title":"Calcula $2^{-3}$.","items":[{"math":"2^{-3}","why":"Reconocemos el exponente negativo.","side":{"title":"Sentido","text":"No significa que la potencia sea negativa."}},{"math":"2^{-3}=\\frac1{2^3}","why":"Aplicamos la definición.","side":{"title":"Base no nula","text":"El recíproco existe porque $2\\ne0$."}},{"math":"2^{-3}=\\frac1{2\\cdot2\\cdot2}","why":"Desarrollamos la potencia.","side":{"title":"Multiplicación reiterada","text":"El exponente positivo $3$ indica tres factores."}},{"math":"2^{-3}=\\frac18","why":"Calculamos.","side":{"title":"Resultado","text":"El valor es positivo y menor que $1$."}}]},"warn":"Atención: $(-2)^4=16$, pero $-2^4=-16$: los paréntesis determinan si el signo pertenece a la base. En general, $a^m+a^n\\ne a^{m+n}$."},"example2":"Ejemplo 2 · Producto de potencias\n1. $$2^3\\cdot2^2$$\n   Ambas potencias tienen la misma base.\n2. $$2^{3+2}=2^5$$\n   Sumamos los exponentes.\n3. $$32$$\n   Calculamos el resultado.","example3":"Ejemplo 3 · Cuidado con los paréntesis\n1. $$(-2)^4=(-2)(-2)(-2)(-2)=16$$\n   El signo negativo está dentro de la base.\n2. $$-2^4=-(2^4)=-16$$\n   Sin paréntesis, el signo queda fuera de la potencia.","draw":5,"unit":0},{"id":"u1-s009","title":"Operaciones con racionales","subtitle":"Fracciones, signos, paréntesis y potencias","group":2,"symbol":"✧","minutes":60,"concept":"Resolver operaciones combinadas con números racionales, signos, paréntesis y potencias.\n\nOrden: paréntesis, potencias, multiplicaciones o divisiones y finalmente sumas o restas.\nEn operaciones del mismo nivel, avanza de izquierda a derecha.\nConsejo: conserva fracciones exactas y simplifica antes de operar.","example":"Calcula $-\\frac34+\\frac56\\cdot(-\\frac95)$.\n1. $$-\\frac34+\\frac56\\cdot\\left(-\\frac95\\right)$$ — Leemos la expresión.\n2. $$-\\frac34-\\frac32$$ — Multiplicamos las fracciones.\n3. $$-\\frac34-\\frac64$$ — Igualamos denominadores.\n4. $$\\frac{-3-6}{4}$$ — Reunimos los numeradores.\n5. $$-\\frac94$$ — Concluimos.","media":[],"practice":[{"q":"Resuelve $\\dfrac{1}{2}+\\dfrac{3}{4}\\cdot\\dfrac{2}{3}$.","options":["$-1$","$0$","$2$","$1$"],"correct":3,"why":"Primero multiplicamos: $\\dfrac{1}{2}$; después sumamos $\\dfrac{1}{2}+\\dfrac{1}{2}=1$.","level":1},{"q":"Resuelve $\\left(\\dfrac{3}{4}-\\dfrac{2}{5}\\right)\\cdot\\dfrac{1}{6}$.","options":["$-\\dfrac{113}{120}$","$\\dfrac{127}{120}$","$-\\dfrac{7}{120}$","$\\dfrac{7}{120}$"],"correct":3,"why":"El paréntesis vale $\\dfrac{7}{20}$; luego multiplicamos por $\\dfrac{1}{6}$.","level":1},{"q":"Resuelve $\\dfrac{5}{6}-\\dfrac{1}{3}\\cdot\\dfrac{3}{4}$.","options":["$\\dfrac{19}{12}$","$-\\dfrac{5}{12}$","$-\\dfrac{7}{12}$","$\\dfrac{7}{12}$"],"correct":3,"why":"Primero multiplicamos: $\\dfrac{1}{4}$; después restamos $\\dfrac{5}{6}-\\dfrac{1}{4}=\\dfrac{7}{12}$.","level":1},{"q":"Resuelve $\\dfrac{2}{3}+\\dfrac{3}{5}\\cdot\\dfrac{1}{2}$.","options":["$-\\dfrac{1}{30}$","$\\dfrac{59}{30}$","$\\dfrac{29}{30}$","$-\\dfrac{29}{30}$"],"correct":2,"why":"Primero multiplicamos: $\\dfrac{3}{10}$; después sumamos $\\dfrac{2}{3}+\\dfrac{3}{10}=\\dfrac{29}{30}$.","level":1},{"q":"Resuelve $\\left(\\dfrac{7}{8}-\\dfrac{2}{3}\\right)\\cdot\\dfrac{1}{4}$.","options":["$\\dfrac{5}{96}$","$-\\dfrac{5}{96}$","$\\dfrac{101}{96}$","$-\\dfrac{91}{96}$"],"correct":0,"why":"El paréntesis vale $\\dfrac{5}{24}$; luego multiplicamos por $\\dfrac{1}{4}$.","level":1},{"q":"Resuelve $\\dfrac{4}{5}-\\dfrac{3}{7}\\cdot\\dfrac{1}{2}$.","options":["$-\\dfrac{41}{70}$","$\\dfrac{41}{70}$","$-\\dfrac{29}{70}$","$\\dfrac{111}{70}$"],"correct":1,"why":"Primero multiplicamos: $\\dfrac{3}{14}$; después restamos $\\dfrac{4}{5}-\\dfrac{3}{14}=\\dfrac{41}{70}$.","level":1},{"q":"Resuelve $\\dfrac{5}{12}+\\dfrac{3}{4}\\cdot\\dfrac{2}{9}$.","options":["$\\dfrac{19}{12}$","$-\\dfrac{7}{12}$","$-\\dfrac{5}{12}$","$\\dfrac{7}{12}$"],"correct":3,"why":"Primero multiplicamos: $\\dfrac{1}{6}$; después sumamos $\\dfrac{5}{12}+\\dfrac{1}{6}=\\dfrac{7}{12}$.","level":1},{"q":"Resuelve $\\left(\\dfrac{3}{10}-\\dfrac{5}{6}\\right)\\cdot\\dfrac{1}{3}$.","options":["$\\dfrac{37}{45}$","$-\\dfrac{8}{45}$","$\\dfrac{8}{45}$","$-\\dfrac{53}{45}$"],"correct":1,"why":"El paréntesis vale $-\\dfrac{8}{15}$; luego multiplicamos por $\\dfrac{1}{3}$.","level":1},{"q":"Resuelve $\\dfrac{2}{3}-\\dfrac{7}{10}\\cdot\\dfrac{3}{5}$.","options":["$-\\dfrac{113}{150}$","$-\\dfrac{37}{150}$","$\\dfrac{37}{150}$","$\\dfrac{187}{150}$"],"correct":2,"why":"Primero multiplicamos: $\\dfrac{21}{50}$; después restamos $\\dfrac{2}{3}-\\dfrac{21}{50}=\\dfrac{37}{150}$.","level":2},{"q":"Resuelve $\\dfrac{5}{8}+\\dfrac{3}{4}\\cdot\\dfrac{1}{6}$.","options":["$\\dfrac{3}{4}$","$-\\dfrac{1}{4}$","$-\\dfrac{3}{4}$","$\\dfrac{7}{4}$"],"correct":0,"why":"Primero multiplicamos: $\\dfrac{1}{8}$; después sumamos $\\dfrac{5}{8}+\\dfrac{1}{8}=\\dfrac{3}{4}$.","level":2},{"q":"Resuelve $\\left(\\dfrac{7}{9}-\\dfrac{2}{5}\\right)\\cdot\\dfrac{1}{3}$.","options":["$\\dfrac{152}{135}$","$-\\dfrac{118}{135}$","$-\\dfrac{17}{135}$","$\\dfrac{17}{135}$"],"correct":3,"why":"El paréntesis vale $\\dfrac{17}{45}$; luego multiplicamos por $\\dfrac{1}{3}$.","level":2},{"q":"Resuelve $\\dfrac{5}{6}-\\dfrac{3}{8}\\cdot\\dfrac{1}{4}$.","options":["$\\dfrac{71}{96}$","$-\\dfrac{25}{96}$","$\\dfrac{167}{96}$","$-\\dfrac{71}{96}$"],"correct":0,"why":"Primero multiplicamos: $\\dfrac{3}{32}$; después restamos $\\dfrac{5}{6}-\\dfrac{3}{32}=\\dfrac{71}{96}$.","level":2},{"q":"Resuelve $\\dfrac{8}{9}+\\dfrac{2}{7}\\cdot\\dfrac{3}{4}$.","options":["$\\dfrac{265}{126}$","$-\\dfrac{139}{126}$","$\\dfrac{13}{126}$","$\\dfrac{139}{126}$"],"correct":3,"why":"Primero multiplicamos: $\\dfrac{3}{14}$; después sumamos $\\dfrac{8}{9}+\\dfrac{3}{14}=\\dfrac{139}{126}$.","level":2},{"q":"Resuelve $\\left(\\dfrac{11}{12}-\\dfrac{5}{8}\\right)\\cdot\\dfrac{1}{3}$.","options":["$\\dfrac{7}{72}$","$\\dfrac{79}{72}$","$-\\dfrac{7}{72}$","$-\\dfrac{65}{72}$"],"correct":0,"why":"El paréntesis vale $\\dfrac{7}{24}$; luego multiplicamos por $\\dfrac{1}{3}$.","level":2},{"q":"Resuelve $\\dfrac{3}{5}-\\dfrac{4}{9}\\cdot\\dfrac{1}{6}$.","options":["$-\\dfrac{71}{135}$","$-\\dfrac{64}{135}$","$\\dfrac{206}{135}$","$\\dfrac{71}{135}$"],"correct":3,"why":"Primero multiplicamos: $\\dfrac{2}{27}$; después restamos $\\dfrac{3}{5}-\\dfrac{2}{27}=\\dfrac{71}{135}$.","level":2},{"q":"Resuelve $\\dfrac{7}{10}+\\dfrac{5}{12}\\cdot\\dfrac{2}{3}$.","options":["$\\dfrac{89}{45}$","$\\dfrac{44}{45}$","$-\\dfrac{44}{45}$","$-\\dfrac{1}{45}$"],"correct":1,"why":"Primero multiplicamos: $\\dfrac{5}{18}$; después sumamos $\\dfrac{7}{10}+\\dfrac{5}{18}=\\dfrac{44}{45}$.","level":2},{"q":"Resuelve $\\left(\\dfrac{9}{14}-\\dfrac{3}{7}\\right)\\cdot\\dfrac{1}{2}$.","options":["$\\dfrac{31}{28}$","$-\\dfrac{3}{28}$","$\\dfrac{3}{28}$","$-\\dfrac{25}{28}$"],"correct":2,"why":"El paréntesis vale $\\dfrac{3}{14}$; luego multiplicamos por $\\dfrac{1}{2}$.","level":3},{"q":"Resuelve $\\dfrac{4}{11}-\\dfrac{7}{8}\\cdot\\dfrac{3}{5}$.","options":["$-\\dfrac{511}{440}$","$\\dfrac{71}{440}$","$-\\dfrac{71}{440}$","$\\dfrac{369}{440}$"],"correct":2,"why":"Primero multiplicamos: $\\dfrac{21}{40}$; después restamos $\\dfrac{4}{11}-\\dfrac{21}{40}=-\\dfrac{71}{440}$.","level":3},{"q":"Resuelve $\\dfrac{5}{9}+\\dfrac{4}{7}\\cdot\\dfrac{2}{3}$.","options":["$\\dfrac{122}{63}$","$-\\dfrac{4}{63}$","$\\dfrac{59}{63}$","$-\\dfrac{59}{63}$"],"correct":2,"why":"Primero multiplicamos: $\\dfrac{8}{21}$; después sumamos $\\dfrac{5}{9}+\\dfrac{8}{21}=\\dfrac{59}{63}$.","level":3},{"q":"Resuelve $\\left(\\dfrac{11}{15}-\\dfrac{5}{6}\\right)\\cdot\\dfrac{3}{10}$.","options":["$\\dfrac{97}{100}$","$-\\dfrac{3}{100}$","$\\dfrac{3}{100}$","$-\\dfrac{103}{100}$"],"correct":1,"why":"El paréntesis vale $-\\dfrac{1}{10}$; luego multiplicamos por $\\dfrac{3}{10}$.","level":3}],"check":{"q":"Un experimento utiliza $\\dfrac12$ L y luego otros $\\dfrac14$ L dos veces. ¿Cuánto se utiliza en total?","options":["$1$ L","$\\dfrac34$ L","$\\dfrac58$ L"],"correct":0,"why":"$1/2+2\\cdot(1/4)=1$ L."},"learn":{"goal":"Resolver operaciones combinadas con números racionales, signos, paréntesis y potencias.","idea":"Orden: paréntesis, potencias, multiplicaciones o divisiones y finalmente sumas o restas.\nEn operaciones del mismo nivel, avanza de izquierda a derecha.\nConsejo: conserva fracciones exactas y simplifica antes de operar.","steps":{"title":"Calcula $-\\frac34+\\frac56\\cdot(-\\frac95)$.","items":[{"math":"-\\frac34+\\frac56\\cdot\\left(-\\frac95\\right)","why":"Leemos la expresión.","side":{"title":"Prioridad","text":"La multiplicación se efectúa antes de la suma."}},{"math":"-\\frac34-\\frac32","why":"Multiplicamos las fracciones.","side":{"title":"Simplificación","text":"$\\frac56\\cdot(-\\frac95)=-\\frac32$ después de simplificar."}},{"math":"-\\frac34-\\frac64","why":"Igualamos denominadores.","side":{"title":"MCM","text":"$3/2=6/4$; ambas fracciones se expresan en cuartos."}},{"math":"\\frac{-3-6}{4}","why":"Reunimos los numeradores.","side":{"title":"Signos","text":"Se suman dos cantidades negativas."}},{"math":"-\\frac94","why":"Concluimos.","side":{"title":"Resultado","text":"El resultado es una fracción irreducible."}}]},"warn":"Atención: no sumes antes de multiplicar. El signo negativo de una fracción debe conservarse en cada paso."},"example2":"Ejemplo 2 · Primero una potencia\n1. $$\\dfrac12+\\left(-\\dfrac32\\right)^2$$\n   Calculamos la potencia antes de sumar.\n2. $$\\dfrac12+\\dfrac94$$\n   Al cuadrar, el resultado es positivo.\n3. $$\\dfrac24+\\dfrac94=\\dfrac{11}4$$\n   Usamos denominador común y sumamos.","example3":"Ejemplo 3 · Paréntesis y producto\n1. $$\\left(\\dfrac12-\\dfrac34\\right)\\cdot(-8)$$\n   Primero resolvemos el paréntesis.\n2. $$\\left(-\\dfrac14\\right)\\cdot(-8)$$\n   Calculamos la diferencia.\n3. $$2$$\n   Multiplicamos; negativo por negativo es positivo.","draw":5,"unit":0},{"id":"u1-s010","title":"Raíces y aproximaciones","subtitle":"Raíces exactas y estimación","group":3,"symbol":"✧","minutes":35,"concept":"Calcular raíces cuadradas exactas y acotar raíces no exactas entre enteros consecutivos.\n\nRaíz principal: $\\sqrt a$ es el número no negativo cuyo cuadrado es $a$ (para $a\\ge0$).\nPara estimar $\\sqrt a$, busca cuadrados perfectos consecutivos entre los cuales esté $a$.","example":"¿Entre qué enteros está $\\sqrt{20}$?\n1. $$4^2=16,\\qquad5^2=25$$ — Identificamos cuadrados cercanos.\n2. $$16<20<25$$ — Encerramos el radicando.\n3. $$\\sqrt{16}<\\sqrt{20}<\\sqrt{25}$$ — Aplicamos raíz a los tres términos.\n4. $$4<\\sqrt{20}<5$$ — Concluimos la estimación.","media":[],"practice":[{"q":"Calcula la raíz principal $\\sqrt{1}$.","options":["$1$","$2$","$0$","$-1$"],"correct":0,"why":"$1^2=1$ y la raíz principal es no negativa.","level":1},{"q":"Calcula la raíz principal $\\sqrt{4}$.","options":["$1$","$-2$","$2$","$3$"],"correct":2,"why":"$2^2=4$ y la raíz principal es no negativa.","level":1},{"q":"Calcula la raíz principal $\\sqrt{9}$.","options":["$-3$","$3$","$4$","$2$"],"correct":1,"why":"$3^2=9$ y la raíz principal es no negativa.","level":1},{"q":"Calcula la raíz principal $\\sqrt{16}$.","options":["$-4$","$5$","$3$","$4$"],"correct":3,"why":"$4^2=16$ y la raíz principal es no negativa.","level":1},{"q":"Calcula la raíz principal $\\sqrt{25}$.","options":["$5$","$-5$","$4$","$6$"],"correct":0,"why":"$5^2=25$ y la raíz principal es no negativa.","level":1},{"q":"Calcula la raíz principal $\\sqrt{36}$.","options":["$-6$","$5$","$6$","$7$"],"correct":2,"why":"$6^2=36$ y la raíz principal es no negativa.","level":1},{"q":"Calcula la raíz principal $\\sqrt{49}$.","options":["$8$","$6$","$-7$","$7$"],"correct":3,"why":"$7^2=49$ y la raíz principal es no negativa.","level":1},{"q":"Calcula la raíz principal $\\sqrt{64}$.","options":["$-8$","$7$","$9$","$8$"],"correct":3,"why":"$8^2=64$ y la raíz principal es no negativa.","level":1},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{2}$?","options":["$3<\\sqrt{2}<4$","$2<\\sqrt{2}<3$","$0<\\sqrt{2}<1$","$1<\\sqrt{2}<2$"],"correct":3,"why":"Como $1<2<4$, se cumple $1<\\sqrt{2}<2$.","level":2},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{3}$?","options":["$0<\\sqrt{3}<1$","$1<\\sqrt{3}<2$","$3<\\sqrt{3}<4$","$2<\\sqrt{3}<3$"],"correct":1,"why":"Como $1<3<4$, se cumple $1<\\sqrt{3}<2$.","level":2},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{5}$?","options":["$1<\\sqrt{5}<2$","$4<\\sqrt{5}<5$","$3<\\sqrt{5}<4$","$2<\\sqrt{5}<3$"],"correct":3,"why":"Como $4<5<9$, se cumple $2<\\sqrt{5}<3$.","level":2},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{6}$?","options":["$3<\\sqrt{6}<4$","$1<\\sqrt{6}<2$","$4<\\sqrt{6}<5$","$2<\\sqrt{6}<3$"],"correct":3,"why":"Como $4<6<9$, se cumple $2<\\sqrt{6}<3$.","level":2},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{7}$?","options":["$1<\\sqrt{7}<2$","$4<\\sqrt{7}<5$","$3<\\sqrt{7}<4$","$2<\\sqrt{7}<3$"],"correct":3,"why":"Como $4<7<9$, se cumple $2<\\sqrt{7}<3$.","level":2},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{8}$?","options":["$2<\\sqrt{8}<3$","$3<\\sqrt{8}<4$","$1<\\sqrt{8}<2$","$4<\\sqrt{8}<5$"],"correct":0,"why":"Como $4<8<9$, se cumple $2<\\sqrt{8}<3$.","level":2},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{10}$?","options":["$4<\\sqrt{10}<5$","$3<\\sqrt{10}<4$","$5<\\sqrt{10}<6$","$2<\\sqrt{10}<3$"],"correct":1,"why":"Como $9<10<16$, se cumple $3<\\sqrt{10}<4$.","level":2},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{13}$?","options":["$4<\\sqrt{13}<5$","$5<\\sqrt{13}<6$","$2<\\sqrt{13}<3$","$3<\\sqrt{13}<4$"],"correct":3,"why":"Como $9<13<16$, se cumple $3<\\sqrt{13}<4$.","level":2},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{20}$?","options":["$5<\\sqrt{20}<6$","$3<\\sqrt{20}<4$","$4<\\sqrt{20}<5$","$6<\\sqrt{20}<7$"],"correct":2,"why":"Como $16<20<25$, se cumple $4<\\sqrt{20}<5$.","level":3},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{30}$?","options":["$6<\\sqrt{30}<7$","$5<\\sqrt{30}<6$","$7<\\sqrt{30}<8$","$4<\\sqrt{30}<5$"],"correct":1,"why":"Como $25<30<36$, se cumple $5<\\sqrt{30}<6$.","level":3},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{120}$?","options":["$11<\\sqrt{120}<12$","$10<\\sqrt{120}<11$","$12<\\sqrt{120}<13$","$9<\\sqrt{120}<10$"],"correct":1,"why":"Como $100<120<121$, se cumple $10<\\sqrt{120}<11$.","level":3},{"q":"¿Entre qué enteros consecutivos está $\\sqrt{210}$?","options":["$16<\\sqrt{210}<17$","$14<\\sqrt{210}<15$","$15<\\sqrt{210}<16$","$13<\\sqrt{210}<14$"],"correct":1,"why":"Como $196<210<225$, se cumple $14<\\sqrt{210}<15$.","level":3}],"check":{"q":"El área de un cuadrado es $49\\,\\mathrm{cm}^2$. ¿Cuánto mide su lado?","options":["$7\\,\\mathrm{cm}$","$14\\,\\mathrm{cm}$","$24,5\\,\\mathrm{cm}$"],"correct":0,"why":"El lado es $\\sqrt{49}=7$ cm."},"learn":{"goal":"Calcular raíces cuadradas exactas y acotar raíces no exactas entre enteros consecutivos.","idea":"Raíz principal: $\\sqrt a$ es el número no negativo cuyo cuadrado es $a$ (para $a\\ge0$).\nPara estimar $\\sqrt a$, busca cuadrados perfectos consecutivos entre los cuales esté $a$.","steps":{"title":"¿Entre qué enteros está $\\sqrt{20}$?","items":[{"math":"4^2=16,\\qquad5^2=25","why":"Identificamos cuadrados cercanos.","side":{"title":"Cuadrados perfectos","text":"$16$ y $25$ son cuadrados consecutivos alrededor de $20$."}},{"math":"16<20<25","why":"Encerramos el radicando.","side":{"title":"Orden","text":"El número $20$ queda entre los dos cuadrados."}},{"math":"\\sqrt{16}<\\sqrt{20}<\\sqrt{25}","why":"Aplicamos raíz a los tres términos.","side":{"title":"Monotonía","text":"Para números no negativos, la raíz cuadrada conserva el orden."}},{"math":"4<\\sqrt{20}<5","why":"Concluimos la estimación.","side":{"title":"Localización","text":"La raíz está entre $4$ y $5$."}}]},"warn":"Atención: $\\sqrt{49}=7$, no $\\pm7$. En cambio, la ecuación $x^2=49$ tiene dos soluciones: $x=7$ y $x=-7$."},"example2":"Ejemplo 2 · Encerrar una raíz\n1. $$36<40<49$$\n   Buscamos los cuadrados perfectos vecinos.\n2. $$6<\\sqrt{40}<7$$\n   Aplicamos raíz a cada término.","explore":{"title":"Constructor de cuadrados","desc":"Relaciona el área de un cuadrado con la longitud de su lado y estima raíces cuadradas.","instr":"Modifica el área y observa qué sucede con la longitud del lado.","alt":"Constructor de cuadrados · actividad interactiva opcional, sin porcentaje de avance.","height":850,"html":"<!DOCTYPE html>\n<html lang=\"es\"><head><meta charset=\"UTF-8\"/><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"/><meta name=\"color-scheme\" content=\"light\"/><title>Explora · Constructor de cuadrados · PACE UACh</title><style>:root{--bg:#f3f7fb;--paper:#fff;--ink:#1a3044;--muted:#607588;--stroke:#dce6ed;--main:#2575ac;--main2:#0b9a83;--mist:#e9f4f9;--warm:#fff6e5;--gold:#aa731d;--ok:#137d64;--bad:#a04a3c;--shadow:0 16px 36px rgba(30,62,86,.07)}\n*{box-sizing:border-box}html{font-size:16px}body{margin:0;background:radial-gradient(circle at 90% 0%,#e1f3f7 0%,transparent 32%),var(--bg);font-family:system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif;color:var(--ink);line-height:1.5}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f3bd59;outline-offset:2px}button:disabled{cursor:not-allowed;opacity:.45}\n.shell{width:min(1060px,calc(100% - 32px));margin:26px auto 42px}.hero{padding:25px 27px 24px;color:white;border-radius:22px;background:linear-gradient(119deg,#12476f 0%,#1b7d9f 57%,#138d83 100%);box-shadow:var(--shadow);position:relative;overflow:hidden}.hero:before,.hero:after{content:\"\";position:absolute;border:2px solid #ffffff20;border-radius:50%;width:270px;height:270px;right:-95px;top:-175px}.hero:after{width:180px;height:180px;right:35px;top:-120px}.kicker{text-transform:uppercase;font-size:.77rem;letter-spacing:.14em;font-weight:750;opacity:.88}.hero h1{font-size:clamp(1.48rem,3.6vw,2.15rem);margin:7px 0 5px;line-height:1.17;letter-spacing:-.03em}.hero p{margin:0;max-width:700px;color:#ebf9ff;line-height:1.5}.topline{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.chip{display:inline-flex;border-radius:999px;padding:6px 11px;background:#ffffff2b;font-weight:650;font-size:.79rem;white-space:nowrap;z-index:1}.layout{display:grid;grid-template-columns:335px minmax(0,1fr);align-items:start;gap:16px;margin-top:16px}.card{background:var(--paper);border:1px solid var(--stroke);border-radius:18px;padding:20px;box-shadow:var(--shadow);min-width:0}.card h2,.card h3{margin:0 0 12px;letter-spacing:-.02em}.card h2{font-size:1.14rem}.card h3{font-size:1.02rem}.lede{font-size:.96rem;color:var(--muted);margin:0 0 13px}.muted{color:var(--muted)}.small{font-size:.85rem}.tiny{font-size:.75rem}.controls{display:grid;gap:12px}.field{display:grid;gap:5px}.field label{font-size:.87rem;font-weight:700;color:#344f65}.field select,.field input[type=number]{width:100%;min-height:43px;border:1px solid #cddce7;background:#fff;border-radius:10px;padding:8px 11px;color:var(--ink)}.field input[type=range]{width:100%;accent-color:var(--main2);cursor:pointer}.inline-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pills{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--main);background:var(--main);color:white;font-weight:720;min-height:42px;border-radius:11px;padding:8px 14px;transition:transform .15s,filter .15s}.btn:hover:not(:disabled){filter:brightness(1.06);transform:translateY(-1px)}.btn.alt{background:#f1f7fb;color:#235e82;border-color:#bcd5e4}.btn.minor{border-color:#d4e1e9;background:white;color:#3b5d75}.btn.green{background:#0e8f78;border-color:#0e8f78}.btn.active{background:#155d89;color:white;border-color:#155d89}.btn.sm{font-size:.85rem;min-height:36px;padding:6px 10px}.btnrow{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.panel{border-radius:14px;background:#f5fafc;border:1px solid #dfecf2;padding:15px}.panel.warm{background:var(--warm);border-color:#f1e2c4}.panel.green{background:#eaf8f3;border-color:#c9e9dd}.panel p:last-child{margin-bottom:0}.panel p:first-child{margin-top:0}.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat{background:#f1f8fb;border:1px solid #ddebf1;border-radius:13px;padding:12px}.stat .value{font-size:1.45rem;font-weight:800;color:#1a6289;line-height:1.25}.stat .label{font-size:.78rem;color:var(--muted)}.formula{font-family:Georgia,\"Times New Roman\",serif;font-size:clamp(1.25rem,3.5vw,1.8rem);font-weight:650;line-height:1.5;text-align:center;word-break:normal}.formula.big{font-size:clamp(1.6rem,4.5vw,2.4rem)}.formula-row{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}.frac{display:inline-flex;flex-direction:column;vertical-align:middle;text-align:center;line-height:1.07;padding:0 2px;font-variant-numeric:tabular-nums}.frac>.n{display:block;border-bottom:1.7px solid currentColor;padding:0 5px 3px}.frac>.d{display:block;padding:3px 5px 0}.stepper{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-top:14px}.stepbadge{font-size:.8rem;font-weight:700;color:#587186}.bar{display:flex;overflow:hidden;border:1px solid #96b0c3;height:32px;border-radius:7px;background:#eef3f5}.segment{flex:1;border-right:1px solid #ffffff90;min-width:0;background:#edf3f7}.segment:last-child{border-right:0}.segment.on{background:#248ac4}.segment.on.teal{background:#28a88b}.segment.on.amber{background:#e4a145}.section-gap{height:16px}.note{border-left:4px solid #d9a03f;background:#fff8e9;padding:11px 13px;border-radius:8px;font-size:.9rem;color:#6b5127}.footer{margin-top:16px;color:#657b8d;font-size:.8rem;text-align:center}.frame{border:1px solid #d8e6ec;background:#f9fcfd;border-radius:13px;overflow:hidden;padding:6px}.frame svg{width:100%;height:auto;display:block}.highlight{color:#0d887b;font-weight:800}.warn{color:#a45327;font-weight:780}.subhead{font-weight:800;font-size:.89rem;color:#42617a;text-transform:uppercase;letter-spacing:.055em;margin-bottom:8px}.reveal{animation:appear .3s ease-out}@keyframes appear{from{opacity:.25;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}\n@media(max-width:760px){.shell{width:min(100% - 18px,610px);margin:9px auto 28px}.hero{padding:19px;border-radius:16px}.layout{grid-template-columns:1fr;gap:11px;margin-top:11px}.card{padding:16px;border-radius:14px}.topline{flex-direction:column}.chip{align-self:flex-start}.inline-fields{grid-template-columns:1fr 1fr}.footer{padding:0 8px}.stat .value{font-size:1.25rem}}\n@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}\n</style></head><body><div class=\"shell\"><header class=\"hero\"><div class=\"topline\"><div><div class=\"kicker\">EXPLORA · UNIDAD I · ESTACIÓN 10</div><h1>Constructor de cuadrados</h1><p>Cambia el área de un cuadrado y observa su lado. Investiga cuándo una raíz es exacta y cómo acotarla.</p></div><span class=\"chip\">Manipulador geométrico</span></div></header>\n<div class=\"layout\"><aside class=\"card\"><h2>1. Elige un área</h2><div class=\"controls\"><div class=\"field\"><label for=\"area\">Área del cuadrado (u²)</label><input id=\"area\" type=\"number\" min=\"1\" max=\"144\" step=\"1\" value=\"20\"/></div><div class=\"field\"><label for=\"areaSlider\">Ajusta el área</label><input id=\"areaSlider\" type=\"range\" min=\"1\" max=\"144\" value=\"20\"/></div><div class=\"pills\"><button class=\"btn minor sm\" data-area=\"9\">9</button><button class=\"btn minor sm\" data-area=\"16\">16</button><button class=\"btn minor sm\" data-area=\"20\">20</button><button class=\"btn minor sm\" data-area=\"50\">50</button><button class=\"btn minor sm\" data-area=\"72\">72</button><button class=\"btn minor sm\" data-area=\"100\">100</button></div></div><div class=\"section-gap\"></div><div class=\"panel warm\"><h3>2. Estima el lado</h3><p class=\"small\">Mueve el control: ¿qué longitud al cuadrado se aproxima al área elegida?</p><div class=\"field\"><label id=\"estimateLabel\" for=\"estimate\">Tu estimación del lado</label><input id=\"estimate\" type=\"range\" min=\"4\" max=\"5\" step=\"0.01\" value=\"4.5\"/></div><div class=\"stats\"><div class=\"stat\"><div class=\"value\" id=\"estimatedSide\">4,50</div><div class=\"label\">Lado elegido (u)</div></div><div class=\"stat\"><div class=\"value\" id=\"estimatedArea\">20,25</div><div class=\"label\">Área que produce (u²)</div></div></div><p id=\"estimateHint\" class=\"small\"></p></div></aside>\n<main class=\"card\"><h2>3. Mira cómo crece el cuadrado</h2><div class=\"frame\"><svg id=\"square\" viewBox=\"0 0 500 345\" role=\"img\" aria-label=\"Cuadrado representado sobre una retícula de unidades\"></svg></div><div class=\"section-gap\"></div><div class=\"panel green\" id=\"bounds\" aria-live=\"polite\"></div><div class=\"section-gap\"></div><div class=\"stats\"><div class=\"stat\"><div class=\"label\">Área elegida</div><div class=\"value\" id=\"areaValue\">20 u²</div></div><div class=\"stat\"><div class=\"label\">Lado del cuadrado</div><div class=\"value\" id=\"sideValue\">√20 u</div></div></div><div class=\"section-gap\"></div><div class=\"note\">La raíz cuadrada principal de un área es la longitud <strong>no negativa</strong> del lado del cuadrado correspondiente.</div></main></div>\n<div class=\"footer\">No se registran respuestas. Lo importante es experimentar con áreas distintas y observar patrones.</div></div>\n<script>function $(id){return document.getElementById(id)}\nfunction clamp(v,a,b){return Math.min(b,Math.max(a,Number(v)||0))}\nfunction gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b]}return a}\nfunction lcm(a,b){return Math.abs(a*b)/gcd(a,b)}\nfunction fmt(n){return String(n).replace('-', '−')}\nfunction fraction(n,d){let s=n<0?'−':'';n=Math.abs(n);return `<span class=\"frac\"><span class=\"n\">${s}${n}</span><span class=\"d\">${d}</span></span>`}\nfunction fractionStr(n,d){return `${fmt(n)}/${d}`}\nfunction simplify(n,d){if(d<0){n=-n;d=-d}const g=gcd(n,d)||1;return [n/g,d/g]}\nfunction barMarkup(n,d,cls=''){let out='';for(let i=0;i<d;i++){out+=`<span class=\"segment ${i<n?'on '+cls:''}\" aria-hidden=\"true\"></span>`}return `<div class=\"bar\" role=\"img\" aria-label=\"${n} de ${d} partes sombreadas\">${out}</div>`}\nfunction options(el,values,selected){el.innerHTML=values.map(v=>`<option value=\"${v}\" ${String(v)===String(selected)?'selected':''}>${v}</option>`).join('')}\nfunction setText(id,val){$(id).textContent=val}\n</script><script>let A=20,estimate=4.5;\nfunction num(n){return Number(n).toLocaleString('es-CL',{maximumFractionDigits:2,minimumFractionDigits:2})}\nfunction changeArea(v){if(!Number.isInteger(v)||v<1||v>144){$('area').setCustomValidity('El área debe ser un entero entre 1 y 144');$('area').reportValidity();return}$('area').setCustomValidity('');A=v;const side=Math.sqrt(A),lo=Math.floor(side),hi=Math.ceil(side);estimate=side===lo?lo:lo+.5;$('area').value=A;$('areaSlider').value=A;$('estimate').min=lo;$('estimate').max=hi;$('estimate').value=estimate;$('estimate').disabled=lo===hi;render()}\nfunction render(){const side=Math.sqrt(A),lo=Math.floor(side),hi=Math.ceil(side),exact=lo===hi,max=Math.max(2,hi+1),S=258/max,x=62,y=23;\nlet grid='';for(let i=0;i<=max;i++){let p=i*S;grid+=`<line x1=\"${x+p}\" y1=\"${y}\" x2=\"${x+p}\" y2=\"${y+max*S}\" stroke=\"#d8e5ed\" stroke-width=\"1\"/><line x1=\"${x}\" y1=\"${y+p}\" x2=\"${x+max*S}\" y2=\"${y+p}\" stroke=\"#d8e5ed\" stroke-width=\"1\"/>`}\nlet lower=lo*S,upper=hi*S,real=side*S;let outline=exact?'':`<rect x=\"${x}\" y=\"${y}\" width=\"${upper}\" height=\"${upper}\" fill=\"none\" stroke=\"#d99a2a\" stroke-width=\"3\" stroke-dasharray=\"8 5\"/>`;\n$('square').innerHTML=`<rect width=\"500\" height=\"345\" fill=\"#f9fcfe\" rx=\"12\"/><rect x=\"${x}\" y=\"${y}\" width=\"${max*S}\" height=\"${max*S}\" fill=\"#fff\" stroke=\"#b5c9d7\"/>${grid}<rect x=\"${x}\" y=\"${y}\" width=\"${real}\" height=\"${real}\" fill=\"#259a9a\" opacity=\".35\" stroke=\"#178b8d\" stroke-width=\"4\"/><rect x=\"${x}\" y=\"${y}\" width=\"${lower}\" height=\"${lower}\" fill=\"none\" stroke=\"#1e77ae\" stroke-width=\"3\"/>${outline}<path d=\"M${x} ${y+real+11} v9 M${x+real} ${y+real+11} v9 M${x} ${y+real+16} H${x+real}\" stroke=\"#1a6e8d\" stroke-width=\"2\"/><text x=\"${x+real/2}\" y=\"${y+real+37}\" text-anchor=\"middle\" font-size=\"17\" fill=\"#155e76\" font-weight=\"750\">lado = √${A} u</text><text x=\"${x+max*S+25}\" y=\"${y+18}\" font-size=\"14\" fill=\"#4e6980\">1 cuadro</text><text x=\"${x+max*S+25}\" y=\"${y+37}\" font-size=\"14\" fill=\"#4e6980\">= 1 u²</text><rect x=\"${x+max*S+27}\" y=\"${y+48}\" width=\"20\" height=\"20\" fill=\"#e6f1f6\" stroke=\"#afc6d5\"/><rect x=\"${x+max*S+22}\" y=\"${y+95}\" width=\"12\" height=\"12\" fill=\"#259a9a\" opacity=\".55\"/><text x=\"${x+max*S+42}\" y=\"${y+107}\" font-size=\"12\" fill=\"#516f81\">Área ${A} u²</text><path d=\"M28 293 h16 M36 285 v16\" stroke=\"#aec6d4\" stroke-width=\"2\"/>`;\n$('bounds').innerHTML=exact?`<div class=\"subhead\">Raíz exacta</div><div class=\"formula\">√${A} = ${lo}</div><p style=\"text-align:center\">${lo} × ${lo} = ${A}. Es un cuadrado perfecto.</p>`:`<div class=\"subhead\">Entre dos cuadrados perfectos</div><div class=\"formula\">${lo*lo} &lt; ${A} &lt; ${hi*hi}</div><div class=\"formula\" style=\"color:var(--ok)\">${lo} &lt; √${A} &lt; ${hi}</div><p class=\"small\" style=\"text-align:center\">El área ${A} está entre ${lo*lo} y ${hi*hi} u², por eso el lado mide entre ${lo} y ${hi} u.</p>`;\nsetText('areaValue',`${A} u²`);setText('sideValue',exact?`${lo} u`:`√${A} ≈ ${num(side)} u`);\nsetText('estimatedSide',num(estimate));setText('estimatedArea',num(estimate*estimate));setText('estimateLabel',exact?'Raíz exacta (no hace falta estimar)':'Tu estimación del lado');setText('estimateHint',exact?'¡Es un cuadrado perfecto!':`Tu cuadrado tendría un área ${estimate*estimate<A?'menor':'mayor'} que ${A} u²${Math.abs(estimate*estimate-A)<.10?'. ¡Muy cerca!':'. Prueba acercarte más.'}`)}\n$('area').addEventListener('change',e=>changeArea(Number(e.target.value)));$('areaSlider').addEventListener('input',e=>changeArea(Number(e.target.value)));$('estimate').addEventListener('input',e=>{estimate=Number(e.target.value);render()});document.querySelectorAll('[data-area]').forEach(btn=>btn.addEventListener('click',()=>changeArea(Number(btn.dataset.area))));changeArea(20);\n</script></body></html>"},"example3":"Ejemplo 3 · Raíz exacta y ecuación\n1. $$\\sqrt{81}=9$$\n   La raíz principal es no negativa.\n2. $$x^2=81\\Rightarrow x=9\\ \\text{o}\\ x=-9$$\n   Resolver la ecuación es distinto de calcular la raíz principal.","draw":5,"unit":0},{"id":"u1-s011","title":"Simplificación de raíces","subtitle":"Extraer factores cuadrados","group":3,"symbol":"✧","minutes":40,"concept":"Simplificar raíces cuadradas extrayendo factores cuadrados perfectos.\n\nPropiedad: si $a,b\\ge0$, entonces $\\sqrt{ab}=\\sqrt a\\cdot\\sqrt b$.\nBusca un cuadrado perfecto que divida al radicando. Si eliges el mayor, evitarás pasos adicionales.","example":"Simplifica $\\sqrt{72}$.\n1. $$\\sqrt{72}$$ — Partimos del radical.\n2. $$\\sqrt{36\\cdot2}$$ — Separamos un factor cuadrado.\n3. $$\\sqrt{36}\\cdot\\sqrt2$$ — Aplicamos la propiedad del producto.\n4. $$6\\sqrt2$$ — Extraemos la raíz exacta.","media":[],"practice":[{"q":"Simplifica $\\sqrt{8}$ extrayendo factores cuadrados.","options":["$2\\sqrt{3}$","$1\\sqrt{2}$","$2\\sqrt{2}$","$3\\sqrt{2}$"],"correct":2,"why":"$8=4\\cdot2$ y $4=2^2$, por tanto $\\sqrt{8}=2\\sqrt{2}$.","level":1},{"q":"Simplifica $\\sqrt{18}$ extrayendo factores cuadrados.","options":["$3\\sqrt{2}$","$2\\sqrt{2}$","$3\\sqrt{3}$","$4\\sqrt{2}$"],"correct":0,"why":"$18=9\\cdot2$ y $9=3^2$, por tanto $\\sqrt{18}=3\\sqrt{2}$.","level":1},{"q":"Simplifica $\\sqrt{12}$ extrayendo factores cuadrados.","options":["$2\\sqrt{3}$","$1\\sqrt{3}$","$3\\sqrt{3}$","$2\\sqrt{4}$"],"correct":0,"why":"$12=4\\cdot3$ y $4=2^2$, por tanto $\\sqrt{12}=2\\sqrt{3}$.","level":1},{"q":"Simplifica $\\sqrt{32}$ extrayendo factores cuadrados.","options":["$5\\sqrt{2}$","$4\\sqrt{3}$","$3\\sqrt{2}$","$4\\sqrt{2}$"],"correct":3,"why":"$32=16\\cdot2$ y $16=4^2$, por tanto $\\sqrt{32}=4\\sqrt{2}$.","level":1},{"q":"Simplifica $\\sqrt{45}$ extrayendo factores cuadrados.","options":["$4\\sqrt{5}$","$3\\sqrt{5}$","$2\\sqrt{5}$","$3\\sqrt{6}$"],"correct":1,"why":"$45=9\\cdot5$ y $9=3^2$, por tanto $\\sqrt{45}=3\\sqrt{5}$.","level":1},{"q":"Simplifica $\\sqrt{50}$ extrayendo factores cuadrados.","options":["$4\\sqrt{2}$","$5\\sqrt{2}$","$5\\sqrt{3}$","$6\\sqrt{2}$"],"correct":1,"why":"$50=25\\cdot2$ y $25=5^2$, por tanto $\\sqrt{50}=5\\sqrt{2}$.","level":1},{"q":"Simplifica $\\sqrt{28}$ extrayendo factores cuadrados.","options":["$3\\sqrt{7}$","$1\\sqrt{7}$","$2\\sqrt{7}$","$2\\sqrt{8}$"],"correct":2,"why":"$28=4\\cdot7$ y $4=2^2$, por tanto $\\sqrt{28}=2\\sqrt{7}$.","level":1},{"q":"Simplifica $\\sqrt{48}$ extrayendo factores cuadrados.","options":["$4\\sqrt{4}$","$3\\sqrt{3}$","$5\\sqrt{3}$","$4\\sqrt{3}$"],"correct":3,"why":"$48=16\\cdot3$ y $16=4^2$, por tanto $\\sqrt{48}=4\\sqrt{3}$.","level":1},{"q":"Simplifica $\\sqrt{75}$ extrayendo factores cuadrados.","options":["$5\\sqrt{3}$","$6\\sqrt{3}$","$5\\sqrt{4}$","$4\\sqrt{3}$"],"correct":0,"why":"$75=25\\cdot3$ y $25=5^2$, por tanto $\\sqrt{75}=5\\sqrt{3}$.","level":2},{"q":"Simplifica $\\sqrt{72}$ extrayendo factores cuadrados.","options":["$7\\sqrt{2}$","$6\\sqrt{3}$","$6\\sqrt{2}$","$5\\sqrt{2}$"],"correct":2,"why":"$72=36\\cdot2$ y $36=6^2$, por tanto $\\sqrt{72}=6\\sqrt{2}$.","level":2},{"q":"Simplifica $\\sqrt{63}$ extrayendo factores cuadrados.","options":["$3\\sqrt{7}$","$3\\sqrt{8}$","$2\\sqrt{7}$","$4\\sqrt{7}$"],"correct":0,"why":"$63=9\\cdot7$ y $9=3^2$, por tanto $\\sqrt{63}=3\\sqrt{7}$.","level":2},{"q":"Simplifica $\\sqrt{80}$ extrayendo factores cuadrados.","options":["$4\\sqrt{6}$","$5\\sqrt{5}$","$3\\sqrt{5}$","$4\\sqrt{5}$"],"correct":3,"why":"$80=16\\cdot5$ y $16=4^2$, por tanto $\\sqrt{80}=4\\sqrt{5}$.","level":2},{"q":"Simplifica $\\sqrt{98}$ extrayendo factores cuadrados.","options":["$7\\sqrt{3}$","$8\\sqrt{2}$","$6\\sqrt{2}$","$7\\sqrt{2}$"],"correct":3,"why":"$98=49\\cdot2$ y $49=7^2$, por tanto $\\sqrt{98}=7\\sqrt{2}$.","level":2},{"q":"Simplifica $\\sqrt{150}$ extrayendo factores cuadrados.","options":["$4\\sqrt{6}$","$6\\sqrt{6}$","$5\\sqrt{6}$","$5\\sqrt{7}$"],"correct":2,"why":"$150=25\\cdot6$ y $25=5^2$, por tanto $\\sqrt{150}=5\\sqrt{6}$.","level":2},{"q":"Simplifica $\\sqrt{180}$ extrayendo factores cuadrados.","options":["$6\\sqrt{5}$","$6\\sqrt{6}$","$7\\sqrt{5}$","$5\\sqrt{5}$"],"correct":0,"why":"$180=36\\cdot5$ y $36=6^2$, por tanto $\\sqrt{180}=6\\sqrt{5}$.","level":2},{"q":"Simplifica $\\sqrt{147}$ extrayendo factores cuadrados.","options":["$7\\sqrt{4}$","$8\\sqrt{3}$","$6\\sqrt{3}$","$7\\sqrt{3}$"],"correct":3,"why":"$147=49\\cdot3$ y $49=7^2$, por tanto $\\sqrt{147}=7\\sqrt{3}$.","level":2},{"q":"Simplifica $\\sqrt{128}$ extrayendo factores cuadrados.","options":["$8\\sqrt{2}$","$8\\sqrt{3}$","$9\\sqrt{2}$","$7\\sqrt{2}$"],"correct":0,"why":"$128=64\\cdot2$ y $64=8^2$, por tanto $\\sqrt{128}=8\\sqrt{2}$.","level":3},{"q":"Simplifica $\\sqrt{243}$ extrayendo factores cuadrados.","options":["$10\\sqrt{3}$","$9\\sqrt{4}$","$8\\sqrt{3}$","$9\\sqrt{3}$"],"correct":3,"why":"$243=81\\cdot3$ y $81=9^2$, por tanto $\\sqrt{243}=9\\sqrt{3}$.","level":3},{"q":"Simplifica $\\sqrt{252}$ extrayendo factores cuadrados.","options":["$5\\sqrt{7}$","$6\\sqrt{8}$","$6\\sqrt{7}$","$7\\sqrt{7}$"],"correct":2,"why":"$252=36\\cdot7$ y $36=6^2$, por tanto $\\sqrt{252}=6\\sqrt{7}$.","level":3},{"q":"Simplifica $\\sqrt{600}$ extrayendo factores cuadrados.","options":["$10\\sqrt{6}$","$11\\sqrt{6}$","$9\\sqrt{6}$","$10\\sqrt{7}$"],"correct":0,"why":"$600=100\\cdot6$ y $100=10^2$, por tanto $\\sqrt{600}=10\\sqrt{6}$.","level":3}],"check":{"q":"La longitud de una diagonal es $\\sqrt{32}$ cm. ¿Cuál es su expresión simplificada?","options":["$4\\sqrt2$ cm","$8\\sqrt2$ cm","$2\\sqrt2$ cm"],"correct":0,"why":"$32=16\\cdot2$, luego $\\sqrt{32}=4\\sqrt2$."},"learn":{"goal":"Simplificar raíces cuadradas extrayendo factores cuadrados perfectos.","idea":"Propiedad: si $a,b\\ge0$, entonces $\\sqrt{ab}=\\sqrt a\\cdot\\sqrt b$.\nBusca un cuadrado perfecto que divida al radicando. Si eliges el mayor, evitarás pasos adicionales.","steps":{"title":"Simplifica $\\sqrt{72}$.","items":[{"math":"\\sqrt{72}","why":"Partimos del radical.","side":{"title":"Búsqueda","text":"Buscamos el mayor cuadrado perfecto que divide a $72$."}},{"math":"\\sqrt{36\\cdot2}","why":"Separamos un factor cuadrado.","side":{"title":"Factor elegido","text":"$72=36\\cdot2$ y $36=6^2$."}},{"math":"\\sqrt{36}\\cdot\\sqrt2","why":"Aplicamos la propiedad del producto.","side":{"title":"Condición","text":"Ambos radicandos son no negativos."}},{"math":"6\\sqrt2","why":"Extraemos la raíz exacta.","side":{"title":"Resultado","text":"$\\sqrt{36}=6$ y el $2$ no tiene factor cuadrado mayor que $1$."}}]},"warn":"Atención: $\\sqrt{9+16}\\ne\\sqrt9+\\sqrt{16}$. La propiedad de extracción se aplica a productos de radicandos no negativos, no a sumas."},"example2":"Ejemplo 2 · Sacar cuadrados\n1. $$\\sqrt{50}$$\n   Buscamos el mayor factor cuadrado posible.\n2. $$\\sqrt{25\\cdot2}$$\n   Separamos el 25, que es cuadrado perfecto.\n3. $$5\\sqrt2$$\n   Extraemos la raíz de 25.","example3":"Ejemplo 3 · Más de un factor\n1. $$\\sqrt{180}$$\n   El cuadrado perfecto 36 divide a 180.\n2. $$\\sqrt{36\\cdot5}$$\n   Escribimos el producto.\n3. $$6\\sqrt5$$\n   Simplificamos el radical.","draw":5,"unit":0},{"id":"u1-s012","title":"Operaciones con radicales","subtitle":"Reducir radicales semejantes","group":3,"symbol":"✧","minutes":45,"concept":"Sumar y restar radicales semejantes después de simplificarlos.\n\nSemejantes: los términos comparten el mismo radical simplificado.\nSe suman o restan los coeficientes, como en $2x+3x=5x$.\nSi los radicales son distintos, primero intenta simplificarlos.","example":"Simplifica $\\sqrt{12}+\\sqrt{27}$.\n1. $$\\sqrt{12}+\\sqrt{27}$$ — Identificamos dos radicales.\n2. $$\\sqrt{4\\cdot3}+\\sqrt{9\\cdot3}$$ — Extraemos factores cuadrados.\n3. $$2\\sqrt3+3\\sqrt3$$ — Simplificamos cada radical.\n4. $$(2+3)\\sqrt3$$ — Factorizamos el radical común.\n5. $$5\\sqrt3$$ — Obtenemos el resultado.","media":[],"practice":[{"q":"Calcula $3\\sqrt{12}+\\sqrt{12}$ y simplifica.","options":["$8\\sqrt{3}$","$9\\sqrt{3}$","$7\\sqrt{3}$","$16\\sqrt{3}$"],"correct":0,"why":"$\\sqrt{12}=2\\sqrt{3}$ y $\\sqrt{12}=2\\sqrt{3}$. Operamos coeficientes: $3\\cdot2+1\\cdot2=8$.","level":1},{"q":"Calcula $2\\sqrt{8}-\\sqrt{18}$ y simplifica.","options":["$3\\sqrt{2}$","$\\sqrt{2}$","$0$","$2\\sqrt{2}$"],"correct":1,"why":"$\\sqrt{8}=2\\sqrt{2}$ y $\\sqrt{18}=3\\sqrt{2}$. Operamos coeficientes: $2\\cdot2-1\\cdot3=1$.","level":1},{"q":"Calcula $2\\sqrt{18}+2\\sqrt{8}$ y simplifica.","options":["$20\\sqrt{2}$","$9\\sqrt{2}$","$11\\sqrt{2}$","$10\\sqrt{2}$"],"correct":3,"why":"$\\sqrt{18}=3\\sqrt{2}$ y $\\sqrt{8}=2\\sqrt{2}$. Operamos coeficientes: $2\\cdot3+2\\cdot2=10$.","level":1},{"q":"Calcula $3\\sqrt{75}-\\sqrt{12}$ y simplifica.","options":["$26\\sqrt{3}$","$14\\sqrt{3}$","$13\\sqrt{3}$","$12\\sqrt{3}$"],"correct":2,"why":"$\\sqrt{75}=5\\sqrt{3}$ y $\\sqrt{12}=2\\sqrt{3}$. Operamos coeficientes: $3\\cdot5-1\\cdot2=13$.","level":1},{"q":"Calcula $2\\sqrt{20}+3\\sqrt{20}$ y simplifica.","options":["$20\\sqrt{5}$","$11\\sqrt{5}$","$10\\sqrt{5}$","$9\\sqrt{5}$"],"correct":2,"why":"$\\sqrt{20}=2\\sqrt{5}$ y $\\sqrt{20}=2\\sqrt{5}$. Operamos coeficientes: $2\\cdot2+3\\cdot2=10$.","level":1},{"q":"Calcula $3\\sqrt{63}-\\sqrt{28}$ y simplifica.","options":["$7\\sqrt{7}$","$8\\sqrt{7}$","$6\\sqrt{7}$","$14\\sqrt{7}$"],"correct":0,"why":"$\\sqrt{63}=3\\sqrt{7}$ y $\\sqrt{28}=2\\sqrt{7}$. Operamos coeficientes: $3\\cdot3-1\\cdot2=7$.","level":1},{"q":"Calcula $2\\sqrt{24}+\\sqrt{54}$ y simplifica.","options":["$7\\sqrt{6}$","$14\\sqrt{6}$","$8\\sqrt{6}$","$6\\sqrt{6}$"],"correct":0,"why":"$\\sqrt{24}=2\\sqrt{6}$ y $\\sqrt{54}=3\\sqrt{6}$. Operamos coeficientes: $2\\cdot2+1\\cdot3=7$.","level":1},{"q":"Calcula $2\\sqrt{27}-\\sqrt{12}$ y simplifica.","options":["$5\\sqrt{3}$","$8\\sqrt{3}$","$3\\sqrt{3}$","$4\\sqrt{3}$"],"correct":3,"why":"$\\sqrt{27}=3\\sqrt{3}$ y $\\sqrt{12}=2\\sqrt{3}$. Operamos coeficientes: $2\\cdot3-1\\cdot2=4$.","level":1},{"q":"Calcula $3\\sqrt{32}+\\sqrt{18}$ y simplifica.","options":["$16\\sqrt{2}$","$30\\sqrt{2}$","$15\\sqrt{2}$","$14\\sqrt{2}$"],"correct":2,"why":"$\\sqrt{32}=4\\sqrt{2}$ y $\\sqrt{18}=3\\sqrt{2}$. Operamos coeficientes: $3\\cdot4+1\\cdot3=15$.","level":2},{"q":"Calcula $3\\sqrt{50}-2\\sqrt{8}$ y simplifica.","options":["$10\\sqrt{2}$","$22\\sqrt{2}$","$11\\sqrt{2}$","$12\\sqrt{2}$"],"correct":2,"why":"$\\sqrt{50}=5\\sqrt{2}$ y $\\sqrt{8}=2\\sqrt{2}$. Operamos coeficientes: $3\\cdot5-2\\cdot2=11$.","level":2},{"q":"Calcula $2\\sqrt{45}+\\sqrt{45}$ y simplifica.","options":["$18\\sqrt{5}$","$10\\sqrt{5}$","$9\\sqrt{5}$","$8\\sqrt{5}$"],"correct":2,"why":"$\\sqrt{45}=3\\sqrt{5}$ y $\\sqrt{45}=3\\sqrt{5}$. Operamos coeficientes: $2\\cdot3+1\\cdot3=9$.","level":2},{"q":"Calcula $3\\sqrt{28}-\\sqrt{175}$ y simplifica.","options":["$2\\sqrt{7}$","$\\sqrt{7}$","$0$","$3\\sqrt{7}$"],"correct":1,"why":"$\\sqrt{28}=2\\sqrt{7}$ y $\\sqrt{175}=5\\sqrt{7}$. Operamos coeficientes: $3\\cdot2-1\\cdot5=1$.","level":2},{"q":"Calcula $4\\sqrt{48}+2\\sqrt{12}$ y simplifica.","options":["$21\\sqrt{3}$","$19\\sqrt{3}$","$40\\sqrt{3}$","$20\\sqrt{3}$"],"correct":3,"why":"$\\sqrt{48}=4\\sqrt{3}$ y $\\sqrt{12}=2\\sqrt{3}$. Operamos coeficientes: $4\\cdot4+2\\cdot2=20$.","level":2},{"q":"Calcula $5\\sqrt{54}-\\sqrt{54}$ y simplifica.","options":["$11\\sqrt{6}$","$24\\sqrt{6}$","$13\\sqrt{6}$","$12\\sqrt{6}$"],"correct":3,"why":"$\\sqrt{54}=3\\sqrt{6}$ y $\\sqrt{54}=3\\sqrt{6}$. Operamos coeficientes: $5\\cdot3-1\\cdot3=12$.","level":2},{"q":"Calcula $3\\sqrt{40}+2\\sqrt{160}$ y simplifica.","options":["$14\\sqrt{10}$","$28\\sqrt{10}$","$13\\sqrt{10}$","$15\\sqrt{10}$"],"correct":0,"why":"$\\sqrt{40}=2\\sqrt{10}$ y $\\sqrt{160}=4\\sqrt{10}$. Operamos coeficientes: $3\\cdot2+2\\cdot4=14$.","level":2},{"q":"Calcula $2\\sqrt{75}-4\\sqrt{27}$ y simplifica.","options":["$-4\\sqrt{3}$","$-\\sqrt{3}$","$-2\\sqrt{3}$","$-3\\sqrt{3}$"],"correct":2,"why":"$\\sqrt{75}=5\\sqrt{3}$ y $\\sqrt{27}=3\\sqrt{3}$. Operamos coeficientes: $2\\cdot5-4\\cdot3=-2$.","level":2},{"q":"Calcula $4\\sqrt{72}+3\\sqrt{8}$ y simplifica.","options":["$31\\sqrt{2}$","$60\\sqrt{2}$","$29\\sqrt{2}$","$30\\sqrt{2}$"],"correct":3,"why":"$\\sqrt{72}=6\\sqrt{2}$ y $\\sqrt{8}=2\\sqrt{2}$. Operamos coeficientes: $4\\cdot6+3\\cdot2=30$.","level":3},{"q":"Calcula $5\\sqrt{80}-2\\sqrt{45}$ y simplifica.","options":["$14\\sqrt{5}$","$28\\sqrt{5}$","$13\\sqrt{5}$","$15\\sqrt{5}$"],"correct":0,"why":"$\\sqrt{80}=4\\sqrt{5}$ y $\\sqrt{45}=3\\sqrt{5}$. Operamos coeficientes: $5\\cdot4-2\\cdot3=14$.","level":3},{"q":"Calcula $5\\sqrt{98}+\\sqrt{18}$ y simplifica.","options":["$39\\sqrt{2}$","$76\\sqrt{2}$","$37\\sqrt{2}$","$38\\sqrt{2}$"],"correct":3,"why":"$\\sqrt{98}=7\\sqrt{2}$ y $\\sqrt{18}=3\\sqrt{2}$. Operamos coeficientes: $5\\cdot7+1\\cdot3=38$.","level":3},{"q":"Calcula $6\\sqrt{112}-3\\sqrt{28}$ y simplifica.","options":["$19\\sqrt{7}$","$36\\sqrt{7}$","$17\\sqrt{7}$","$18\\sqrt{7}$"],"correct":3,"why":"$\\sqrt{112}=4\\sqrt{7}$ y $\\sqrt{28}=2\\sqrt{7}$. Operamos coeficientes: $6\\cdot4-3\\cdot2=18$.","level":3}],"check":{"q":"Dos segmentos miden $\\sqrt8$ cm y $\\sqrt{18}$ cm. ¿Cuánto suman?","options":["$5\\sqrt2$ cm","$\\sqrt{26}$ cm","$13\\sqrt2$ cm"],"correct":0,"why":"$\\sqrt8=2\\sqrt2$ y $\\sqrt{18}=3\\sqrt2$."},"learn":{"goal":"Sumar y restar radicales semejantes después de simplificarlos.","idea":"Semejantes: los términos comparten el mismo radical simplificado.\nSe suman o restan los coeficientes, como en $2x+3x=5x$.\nSi los radicales son distintos, primero intenta simplificarlos.","steps":{"title":"Simplifica $\\sqrt{12}+\\sqrt{27}$.","items":[{"math":"\\sqrt{12}+\\sqrt{27}","why":"Identificamos dos radicales.","side":{"title":"Primero","text":"Todavía no se ven semejantes; simplificamos por separado."}},{"math":"\\sqrt{4\\cdot3}+\\sqrt{9\\cdot3}","why":"Extraemos factores cuadrados.","side":{"title":"Cuadrados","text":"$4=2^2$ y $9=3^2$."}},{"math":"2\\sqrt3+3\\sqrt3","why":"Simplificamos cada radical.","side":{"title":"Semejantes","text":"Ambos términos tienen el mismo radical $\\sqrt3$."}},{"math":"(2+3)\\sqrt3","why":"Factorizamos el radical común.","side":{"title":"Distributiva","text":"Solo sumamos los coeficientes."}},{"math":"5\\sqrt3","why":"Obtenemos el resultado.","side":{"title":"Resultado","text":"No quedan términos por reducir."}}]},"warn":"Atención: en general, $\\sqrt a+\\sqrt b\\ne\\sqrt{a+b}$. Por ejemplo, $\\sqrt2+\\sqrt3$ no puede reducirse como suma de radicales semejantes."},"example2":"Ejemplo 2 · Resta tras simplificar\n1. $$2\\sqrt8-\\sqrt{18}$$\n   Primero simplificamos cada radical.\n2. $$4\\sqrt2-3\\sqrt2$$\n   Ambos tienen ahora el mismo radical.\n3. $$\\sqrt2$$\n   Restamos coeficientes.","example3":"Ejemplo 3 · Tres términos\n1. $$\\sqrt{12}+\\sqrt{27}-\\sqrt3$$\n   Simplificamos los dos primeros radicales.\n2. $$2\\sqrt3+3\\sqrt3-\\sqrt3$$\n   Todos son términos semejantes.\n3. $$(2+3-1)\\sqrt3=4\\sqrt3$$\n   Sumamos y restamos coeficientes.","draw":5,"unit":0}];
